INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('balance', '/ˈbæləns/', 'noun', 'An even distribution of weight; a state of equilibrium', '平衡；天平；余额', 1, 300, '["cet4"]', '源自古法语balance，来自拉丁语bilanx，bi-表示两个，lanx表示盘子，原指天平的两个盘子', '[{"en": "You need to find a balance between work and leisure.", "cn": "你需要在工作和休闲之间找到平衡。"}, {"en": "She lost her balance and fell.", "cn": "她失去平衡摔倒了。"}]', '["equilibrium", "stability"]', '["imbalance", "instability"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bargain', '/ˈbɑːrɡən/', 'noun', 'An agreement between parties; a thing bought for less than usual price', '交易；便宜货；讨价还价', 1, 900, '["cet4"]', '源自古法语bargaigne，来自日耳曼语borgan（借、交易），表示双方协商达成的交易', '[{"en": "The car was a real bargain at that price.", "cn": "这辆车以那个价格真是便宜货。"}, {"en": "They drove a hard bargain with the supplier.", "cn": "他们与供应商进行了艰苦的谈判。"}]', '["deal", "agreement"]', '["disagreement", "rip-off"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('barrier', '/ˈbæriər/', 'noun', 'An obstacle that prevents movement or access', '障碍；屏障；隔阂', 2, 800, '["cet4"]', '源自古法语barriere，来自barre（横木、栏杆），表示阻挡通行的障碍物', '[{"en": "Language can be a barrier to communication.", "cn": "语言可能成为沟通的障碍。"}, {"en": "The government has set up barriers to trade.", "cn": "政府设置了贸易壁垒。"}]', '["obstacle", "hurdle"]', '["aid", "assistance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('benefit', '/ˈbenɪfɪt/', 'noun', 'An advantage or profit gained from something', '利益；好处；福利', 1, 200, '["cet4"]', '来自拉丁语benefactum，bene表示好，facere表示做，即做好事带来的好处', '[{"en": "The new policy will benefit the public.", "cn": "新政策将使公众受益。"}, {"en": "Exercise has many health benefits.", "cn": "锻炼有很多健康益处。"}]', '["advantage", "profit"]', '["disadvantage", "detriment"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('blame', '/bleɪm/', 'verb', 'To assign responsibility for a fault or wrong', '责备；归咎于', 1, 500, '["cet4"]', '源自古法语blamer，来自拉丁语blasphemare，原意为亵渎、责骂', '[{"en": "Don''t blame others for your mistakes.", "cn": "不要把你的错误归咎于别人。"}, {"en": "He was blamed for the accident.", "cn": "他因这起事故受到了责备。"}]', '["accuse", "condemn"]', '["praise", "absolve"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('border', '/ˈbɔːrdər/', 'noun', 'The line separating two countries or regions; an edge or boundary', '边界；边境；边缘', 1, 600, '["cet4"]', '源自古法语bord，来自日耳曼语bord，意为边缘、边界', '[{"en": "They crossed the border into France.", "cn": "他们越过边境进入法国。"}, {"en": "The border between the two countries is heavily guarded.", "cn": "两国之间的边界守卫森严。"}]', '["boundary", "frontier"]', '["interior", "center"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('brilliant', '/ˈbrɪliənt/', 'adjective', 'Exceptionally clever or talented; shining brightly', '杰出的；光辉的；灿烂的', 1, 500, '["cet4"]', '源自法语brillant，来自briller（闪耀），来自拉丁语beryllus（绿柱石），因宝石闪耀而得名', '[{"en": "She is a brilliant scientist.", "cn": "她是一位杰出的科学家。"}, {"en": "The sun was brilliant in the clear sky.", "cn": "阳光在晴朗的天空中灿烂夺目。"}]', '["outstanding", "radiant"]', '["dull", "mediocre"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('budget', '/ˈbʌdʒɪt/', 'noun', 'An estimate of income and expenditure; a financial plan', '预算；财政计划', 1, 400, '["cet4"]', '源自法语bougette，是bouge（袋子）的缩小形式，原指装钱的小袋子', '[{"en": "The government has cut the defense budget.", "cn": "政府削减了国防预算。"}, {"en": "We need to plan our budget carefully.", "cn": "我们需要仔细规划预算。"}]', '["allocation", "funds"]', '["debt", "deficit"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('burden', '/ˈbɜːrdn/', 'noun', 'A heavy load; something difficult to endure or a responsibility', '负担；重担；责任', 2, 700, '["cet4"]', '源自古英语byrthen，与bear（承受）同源，表示需要承载的重量或责任', '[{"en": "The tax burden falls on everyone.", "cn": "税收负担落在每个人身上。"}, {"en": "She felt a heavy burden of responsibility.", "cn": "她感到沉重的责任负担。"}]', '["load", "weight"]', '["relief", "ease"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('campaign', '/kæmˈpeɪn/', 'noun', 'An organized course of action to achieve a goal', '运动；战役；竞选活动', 2, 600, '["cet4"]', '源自法语campagne，来自拉丁语campus（田野），原指在开阔地带进行的军事行动', '[{"en": "The government launched a campaign against smoking.", "cn": "政府发起了一场禁烟运动。"}, {"en": "The election campaign lasted six months.", "cn": "竞选活动持续了六个月。"}]', '["movement", "crusade"]', '["inaction", "peace"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('candidate', '/ˈkændɪdət/', 'noun', 'A person who applies for a job or is nominated for election', '候选人；求职者；应试者', 1, 500, '["cet4"]', '来自拉丁语candidatus，candidus意为白色的，因古罗马候选人穿白色长袍而得名', '[{"en": "She is a candidate for the position of manager.", "cn": "她是经理职位的候选人。"}, {"en": "All candidates must submit their applications by Friday.", "cn": "所有候选人必须在周五前提交申请。"}]', '["applicant", "nominee"]', '["voter", "elector"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capable', '/ˈkeɪpəbl/', 'adjective', 'Having the ability or qualities necessary for doing something', '有能力的；能干的', 1, 400, '["cet4"]', '来自拉丁语capabilis，capere意为拿取、容纳，表示有能力承担或完成某事', '[{"en": "She is capable of handling any situation.", "cn": "她有能力处理任何情况。"}, {"en": "He is a very capable engineer.", "cn": "他是一位非常能干的工程师。"}]', '["competent", "qualified"]', '["incompetent", "incapable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capacity', '/kəˈpæsɪti/', 'noun', 'The maximum amount that something can contain; the ability to do something', '容量；能力；产能', 2, 600, '["cet4"]', '来自拉丁语capacitas，capax意为能容纳的，capere意为拿取，表示容纳或承担的能力', '[{"en": "The stadium has a capacity of 50,000 people.", "cn": "这个体育场能容纳五万人。"}, {"en": "She has a great capacity for learning languages.", "cn": "她有很强的学习语言的能力。"}]', '["volume", "ability"]', '["incapacity", "inability"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('career', '/kəˈrɪr/', 'noun', 'An occupation pursued over a significant period of one''s life', '职业；事业；生涯', 1, 300, '["cet4"]', '源自法语carriere（跑道），来自拉丁语carrus（车），原指马车行驶的道路，引申为人生道路', '[{"en": "She has had a successful career in marketing.", "cn": "她在市场营销领域有着成功的职业生涯。"}, {"en": "Choosing the right career is very important.", "cn": "选择正确的职业非常重要。"}]', '["profession", "occupation"]', '["hobby", "pastime"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('casual', '/ˈkæʒuəl/', 'adjective', 'Relaxed and informal; not showing much interest or concern', '随意的；漫不经心的；临时的', 2, 800, '["cet4"]', '来自拉丁语casualis，casus意为偶然、意外，表示随机发生的、非正式的', '[{"en": "The meeting was casual and friendly.", "cn": "会议轻松友好。"}, {"en": "He gave a casual glance at the newspaper.", "cn": "他随意地看了一眼报纸。"}]', '["informal", "relaxed"]', '["formal", "serious"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('category', '/ˈkætəɡɔːri/', 'noun', 'A class or division of things sharing common characteristics', '类别；种类；范畴', 2, 900, '["cet4"]', '来自希腊语kategoria，kata意为向下，agoreuein意为公开宣称，原指对事物的归类断言', '[{"en": "The books are divided into different categories.", "cn": "这些书被分成不同的类别。"}, {"en": "This question falls into the category of science.", "cn": "这个问题属于科学范畴。"}]', '["class", "classification"]', '["individual", "entity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('challenge', '/ˈtʃælɪndʒ/', 'noun', 'A task or situation that tests someone''s abilities', '挑战；难题；质疑', 1, 300, '["cet4"]', '源自古法语chalenge，来自拉丁语calumnia（诽谤、诡辩），原意为对某人的公开质疑或挑战', '[{"en": "Learning a new language is always a challenge.", "cn": "学习一门新语言总是一个挑战。"}, {"en": "She accepted the challenge to run the marathon.", "cn": "她接受了跑马拉松的挑战。"}]', '["dare", "test"]', '["ease", "surrender"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('channel', '/ˈtʃænl/', 'noun', 'A medium for communication or passage; a television station', '频道；渠道；通道', 1, 500, '["cet4"]', '源自拉丁语canalis（管道、沟渠），与canal同源，表示信息或物质流通的通道', '[{"en": "Which TV channel is the news on?", "cn": "新闻在哪个频道？"}, {"en": "The Internet is an important channel for information.", "cn": "互联网是重要的信息渠道。"}]', '["medium", "avenue"]', '["blockage", "obstruction"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('characteristic', '/ˌkærɪktəˈrɪstɪk/', 'noun', 'A typical feature or quality belonging to a person or thing', '特征；特性；特点', 2, 800, '["cet4"]', '来自希腊语kharakteristikos，kharakter意为刻印的标记，原指铭刻在事物上的独特标记', '[{"en": "Kindness is her most notable characteristic.", "cn": "善良是她最显著的特征。"}, {"en": "The city has many unique characteristics.", "cn": "这座城市有许多独特的特征。"}]', '["feature", "trait"]', '["commonality", "normality"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('civil', '/ˈsɪvl/', 'adjective', 'Relating to citizens or the state; polite and courteous', '公民的；民事的；文明的', 2, 900, '["cet4"]', '来自拉丁语civilis，civis意为公民，原指与公民权利和义务相关的事务', '[{"en": "Civil rights are protected by the constitution.", "cn": "公民权利受到宪法保护。"}, {"en": "He was very civil to his neighbors.", "cn": "他对邻居非常礼貌。"}]', '["civic", "polite"]', '["rude", "military"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('claim', '/kleɪm/', 'verb', 'To assert or state that something is true; to demand as a right', '声称；索赔；要求', 1, 400, '["cet4"]', '来自拉丁语clamare（呼喊、大声说），原指公开声明或正式要求某事物', '[{"en": "He claims to have seen a UFO.", "cn": "他声称自己看到了不明飞行物。"}, {"en": "You can claim compensation for the damage.", "cn": "你可以要求损害赔偿。"}]', '["assert", "declare"]', '["deny", "renounce"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('command', '/kəˈmænd/', 'verb', 'To give an authoritative order; to have control over', '命令；指挥；掌握', 1, 600, '["cet4"]', '来自拉丁语commandare，com-（加强）+ mandare（委托、命令），表示授权或下令', '[{"en": "The general commanded his troops to advance.", "cn": "将军命令部队前进。"}, {"en": "She has a good command of English.", "cn": "她精通英语。"}]', '["order", "direct"]', '["obey", "submit"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commit', '/kəˈmɪt/', 'verb', 'To carry out or perpetrate; to pledge or bind oneself to something', '犯（罪）；承诺；投入', 1, 500, '["cet4"]', '来自拉丁语committere，com-（共同）+ mittere（发送、委托），表示将自己交付给某事', '[{"en": "He committed himself to the project.", "cn": "他全身心投入到这个项目中。"}, {"en": "The crime was committed last night.", "cn": "犯罪发生在昨晚。"}]', '["pledge", "dedicate"]', '["abstain", "withdraw"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('communicate', '/kəˈmjuːnɪkeɪt/', 'verb', 'To share or exchange information, ideas, or feelings', '交流；沟通；传达', 1, 400, '["cet4"]', '来自拉丁语communicare，communis意为共同的，表示使信息或思想成为共同拥有的', '[{"en": "We communicate with each other through email.", "cn": "我们通过电子邮件互相交流。"}, {"en": "It is important to communicate your ideas clearly.", "cn": "清楚地表达你的想法很重要。"}]', '["convey", "transmit"]', '["conceal", "suppress"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('community', '/kəˈmjuːnɪti/', 'noun', 'A group of people living in the same place or sharing common interests', '社区；团体；共同体', 1, 300, '["cet4"]', '来自拉丁语communitas，communis意为共同的，表示共同生活或拥有共同特征的群体', '[{"en": "The local community organized a charity event.", "cn": "当地社区组织了一场慈善活动。"}, {"en": "She is an active member of the scientific community.", "cn": "她是科学界的活跃成员。"}]', '["society", "neighborhood"]', '["isolation", "individual"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compare', '/kəmˈper/', 'verb', 'To examine two or more things to identify similarities and differences', '比较；对比；比喻', 1, 300, '["cet4"]', '来自拉丁语comparare，com-（共同）+ par（平等的），表示将事物并列以辨别异同', '[{"en": "Compare the two products before making a decision.", "cn": "做决定之前比较一下这两个产品。"}, {"en": "Her singing has been compared to that of a nightingale.", "cn": "她的歌声被比作夜莺的歌唱。"}]', '["contrast", "liken"]', '["contrast", "differ"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compete', '/kəmˈpiːt/', 'verb', 'To strive against others to win or achieve something', '竞争；比赛；对抗', 1, 400, '["cet4"]', '来自拉丁语competere，com-（共同）+ petere（追求、寻求），表示共同追求同一目标', '[{"en": "The two companies compete for the same market.", "cn": "两家公司争夺同一个市场。"}, {"en": "Athletes from around the world compete in the Olympics.", "cn": "来自世界各地的运动员在奥运会上竞技。"}]', '["contest", "rival"]', '["cooperate", "collaborate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('complex', '/ˈkɑːmpleks/', 'adjective', 'Consisting of many interconnected parts; not simple', '复杂的；综合的', 1, 500, '["cet4"]', '来自拉丁语complexus，com-（共同）+ plectere（编织），表示多部分交织在一起的复杂体', '[{"en": "The human brain is an extremely complex organ.", "cn": "人脑是一个极其复杂的器官。"}, {"en": "This is a complex problem with no easy solution.", "cn": "这是一个没有简单解决方案的复杂问题。"}]', '["complicated", "intricate"]', '["simple", "straightforward"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('concept', '/ˈkɑːnsept/', 'noun', 'An abstract idea or general notion; a plan or intention', '概念；观念；思想', 1, 600, '["cet4"]', '来自拉丁语conceptus，concipere意为构思，com-（共同）+ capere（拿取），指头脑中形成的想法', '[{"en": "The concept of democracy is widely accepted.", "cn": "民主的概念被广泛接受。"}, {"en": "He introduced a new concept in his research paper.", "cn": "他在研究论文中引入了一个新概念。"}]', '["idea", "notion"]', '["reality", "fact"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('conduct', '/kənˈdʌkt/', 'verb', 'To organize and carry out; to lead or guide; to behave', '实施；指挥；行为举止', 1, 600, '["cet4"]', '来自拉丁语conducere，com-（共同）+ ducere（引导），表示引导事情进行', '[{"en": "The scientist conducted several experiments.", "cn": "这位科学家进行了几项实验。"}, {"en": "She conducted herself with great dignity.", "cn": "她举止端庄得体。"}]', '["perform", "execute"]', '["mismanage", "neglect"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('consequence', '/ˈkɑːnsɪkwens/', 'noun', 'A result or effect of an action or condition', '结果；后果；重要性', 1, 500, '["cet4"]', '来自拉丁语consequentia，com-（共同）+ sequi（跟随），即跟随某事而来的结果', '[{"en": "He suffered the consequences of his actions.", "cn": "他承受了自己行为的后果。"}, {"en": "As a consequence of the rain, the match was cancelled.", "cn": "由于下雨，比赛被取消了。"}]', '["result", "outcome"]', '["cause", "origin"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('consider', '/kənˈsɪdər/', 'verb', 'To think carefully about something before making a decision', '考虑；认为；体谅', 1, 300, '["cet4"]', '来自拉丁语considerare，com-（共同）+ sidus（星），原意为观察星象以预测吉凶', '[{"en": "Please consider my proposal carefully.", "cn": "请仔细考虑我的提议。"}, {"en": "I consider him to be a reliable friend.", "cn": "我认为他是一个可靠的朋友。"}]', '["contemplate", "ponder"]', '["ignore", "disregard"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('constant', '/ˈkɑːnstənt/', 'adjective', 'Occurring continuously over a period of time; unchanging', '不断的；恒定的；忠实的', 1, 600, '["cet4"]', '来自拉丁语constans，com-（共同）+ stare（站立），表示始终站立不变的、持续稳定的', '[{"en": "The constant noise made it hard to concentrate.", "cn": "持续不断的噪音使人难以集中注意力。"}, {"en": "The speed of light is a constant value.", "cn": "光速是一个恒定值。"}]', '["continuous", "steady"]', '["intermittent", "variable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('construct', '/kənˈstrʌkt/', 'verb', 'To build or make something by putting different elements together', '建造；构建；构成', 1, 600, '["cet4"]', '来自拉丁语construere，com-（共同）+ struere（堆砌），表示将材料堆砌在一起建造', '[{"en": "They plan to construct a new bridge across the river.", "cn": "他们计划在河上建造一座新桥。"}, {"en": "The theory was constructed on the basis of years of research.", "cn": "该理论是在多年研究的基础上构建的。"}]', '["build", "erect"]', '["destroy", "demolish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('consume', '/kənˈsuːm/', 'verb', 'To eat, drink, or use up a resource', '消耗；消费；吃喝', 1, 500, '["cet4"]', '来自拉丁语consumere，com-（完全）+ sumere（拿取），表示完全取用、消耗殆尽', '[{"en": "Americans consume a lot of fast food.", "cn": "美国人消费大量快餐。"}, {"en": "The fire consumed the entire building.", "cn": "大火吞噬了整栋建筑。"}]', '["use", "devour"]', '["produce", "create"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('database', '/ˈdeɪtəbeɪs/', 'noun', 'A structured set of data held in a computer', '数据库', 1, 500, '["cet4"]', '由data（数据，拉丁语datum已知事物的复数）和base（基础，希腊语basis）组合而成', '[{"en": "The company stores customer information in a database.", "cn": "公司将客户信息存储在数据库中。"}, {"en": "You can search the database for relevant articles.", "cn": "你可以在数据库中搜索相关文章。"}]', '["data bank", "repository"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('deadline', '/ˈdedlaɪn/', 'noun', 'The latest time or date by which something should be completed', '截止日期；最后期限', 1, 400, '["cet4"]', '由dead（死的）和line（线）组合，原指美国内战时期战俘营的警戒线，后引申为最终期限', '[{"en": "The deadline for the project is next Monday.", "cn": "这个项目的截止日期是下周一。"}, {"en": "We must meet the deadline no matter what.", "cn": "无论如何我们必须赶上截止日期。"}]', '["time limit", "due date"]', '["extension", "postponement"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('debate', '/dɪˈbeɪt/', 'noun', 'A formal discussion on a particular topic; an argument about a subject', '辩论；争论；讨论', 1, 600, '["cet4"]', '源自古法语debatre，de-（向下、完全）+ batre（打），原意为思想上的激烈交锋', '[{"en": "There was a heated debate about the new policy.", "cn": "关于新政策有一场激烈的辩论。"}, {"en": "The candidates participated in a televised debate.", "cn": "候选人参加了电视辩论。"}]', '["discussion", "argument"]', '["agreement", "accord"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('decade', '/ˈdekeɪd/', 'noun', 'A period of ten years', '十年', 1, 500, '["cet4"]', '来自拉丁语decas，源自希腊语dekas（十），与decimal（十进制的）同源', '[{"en": "Great changes have taken place in the last decade.", "cn": "在过去十年里发生了巨大的变化。"}, {"en": "This tradition has lasted for decades.", "cn": "这个传统已经持续了几十年。"}]', '["ten years", "decennium"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('decline', '/dɪˈklaɪn/', 'verb', 'To become smaller or fewer; to politely refuse', '下降；衰退；拒绝', 1, 500, '["cet4"]', '来自拉丁语declinare，de-（向下）+ clinare（倾斜），表示向下倾斜或偏离', '[{"en": "The population has been declining in recent years.", "cn": "近年来人口一直在下降。"}, {"en": "She politely declined the invitation.", "cn": "她礼貌地拒绝了邀请。"}]', '["decrease", "refuse"]', '["increase", "accept"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('decrease', '/dɪˈkriːs/', 'verb', 'To become smaller in size, amount, or intensity', '减少；减小；降低', 1, 500, '["cet4"]', '来自拉丁语decrescere，de-（向下）+ crescere（生长），表示数量逐渐向下减少', '[{"en": "The number of students has decreased this year.", "cn": "今年学生人数减少了。"}, {"en": "Prices decreased by 10 percent last month.", "cn": "上个月物价下降了百分之十。"}]', '["reduce", "diminish"]', '["increase", "expand"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('dedicate', '/ˈdedɪkeɪt/', 'verb', 'To devote time, energy, or oneself to a particular purpose', '奉献；致力于；题献', 2, 900, '["cet4"]', '来自拉丁语dedicare，de-（完全）+ dicare（宣告、奉献），原指将某物神圣地献给神灵', '[{"en": "She dedicated her life to helping the poor.", "cn": "她将一生奉献给了帮助穷人。"}, {"en": "The book is dedicated to her parents.", "cn": "这本书是献给她父母的。"}]', '["devote", "commit"]', '["neglect", "abandon"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('defend', '/dɪˈfend/', 'verb', 'To protect from harm or danger; to speak in favor of', '防御；保卫；辩护', 1, 500, '["cet4"]', '来自拉丁语defendere，de-（离开）+ fendere（打击），表示击退攻击、保卫安全', '[{"en": "We must defend our country against invasion.", "cn": "我们必须保卫国家免受入侵。"}, {"en": "The lawyer defended his client in court.", "cn": "律师在法庭上为他的当事人辩护。"}]', '["protect", "guard"]', '["attack", "assault"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('define', '/dɪˈfaɪn/', 'verb', 'To state or describe exactly the nature or meaning of something', '定义；限定；明确', 1, 500, '["cet4"]', '来自拉丁语definire，de-（完全）+ finire（结束、限定），表示精确划定事物的范围和含义', '[{"en": "How would you define success?", "cn": "你如何定义成功？"}, {"en": "The law defines the rights of citizens.", "cn": "法律规定了公民的权利。"}]', '["describe", "specify"]', '["confuse", "obscure"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('deliver', '/dɪˈlɪvər/', 'verb', 'To bring and hand over goods or messages; to give birth to', '递送；发表；接生；解救', 1, 400, '["cet4"]', '源自古法语delivrer，来自拉丁语deliberare，de-（完全）+ liberare（释放），原意为使自由', '[{"en": "The postman delivered the package to my door.", "cn": "邮递员把包裹送到了我家门口。"}, {"en": "She delivered an inspiring speech at the conference.", "cn": "她在会议上发表了鼓舞人心的演讲。"}]', '["transport", "convey"]', '["withhold", "retain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('demand', '/dɪˈmænd/', 'verb', 'To ask for something forcefully; to require as necessary', '要求；需求；需要', 1, 300, '["cet4"]', '来自拉丁语demandare，de-（完全）+ mandare（委托、命令），表示强烈要求或迫切需求', '[{"en": "The workers demanded higher wages.", "cn": "工人们要求更高的工资。"}, {"en": "The demand for clean energy is increasing.", "cn": "对清洁能源的需求正在增加。"}]', '["require", "request"]', '["supply", "offer"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('depart', '/dɪˈpɑːrt/', 'verb', 'To leave a place; to start a journey; to deviate from', '离开；出发；背离', 1, 700, '["cet4"]', '源自古法语departir，de-（离开）+ partir（分开），表示从某地离开或启程', '[{"en": "The train departs at 9 a.m.", "cn": "火车上午九点出发。"}, {"en": "She departed from the traditional approach.", "cn": "她背离了传统方法。"}]', '["leave", "set out"]', '["arrive", "stay"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('depend', '/dɪˈpend/', 'verb', 'To be controlled or determined by; to rely on', '依靠；取决于；信赖', 1, 200, '["cet4"]', '来自拉丁语dependere，de-（向下）+ pendere（悬挂），原意为悬挂于下方，引申为依赖', '[{"en": "Your success depends on your effort.", "cn": "你的成功取决于你的努力。"}, {"en": "Children depend on their parents for support.", "cn": "孩子依靠父母的支持。"}]', '["rely", "count on"]', '["independent", "distrust"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('deserve', '/dɪˈzɜːrv/', 'verb', 'To be worthy of or entitled to a reward or punishment', '值得；应得；应受', 1, 600, '["cet4"]', '源自古法语deservir，de-（完全）+ servir（服务），原意为通过服务赢得回报', '[{"en": "You deserve a rest after all that hard work.", "cn": "辛苦工作之后你应该休息。"}, {"en": "He deserves punishment for his crimes.", "cn": "他应该为自己的罪行受到惩罚。"}]', '["merit", "earn"]', '["forfeit", "lose"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('detect', '/dɪˈtekt/', 'verb', 'To discover or identify the presence of something', '探测；发现；察觉', 2, 900, '["cet4"]', '来自拉丁语detegere，de-（去除）+ tegere（覆盖），表示揭开覆盖物以发现隐藏的事物', '[{"en": "The sensor can detect even the smallest amount of radiation.", "cn": "该传感器可以探测到最小量的辐射。"}, {"en": "She detected a note of sarcasm in his voice.", "cn": "她察觉到他的声音中带有一丝讽刺。"}]', '["discover", "identify"]', '["miss", "overlook"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('determine', '/dɪˈtɜːrmɪn/', 'verb', 'To cause something to occur in a particular way; to ascertain by research', '决定；确定；下决心', 1, 400, '["cet4"]', '来自拉丁语determinare，de-（完全）+ terminare（设定界限），表示划定范围从而做出决定', '[{"en": "We need to determine the cause of the problem.", "cn": "我们需要确定问题的原因。"}, {"en": "She was determined to succeed.", "cn": "她下定决心要成功。"}]', '["decide", "establish"]', '["waver", "hesitate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('discipline', '/ˈdɪsɪplɪn/', 'noun', 'The practice of training people to obey rules; a branch of knowledge', '纪律；学科；训练', 1, 700, '["cet4"]', '来自拉丁语disciplina，discipulus意为学生，原指对学生的教导和训练', '[{"en": "Good discipline is essential in any school.", "cn": "良好的纪律在任何学校都是必不可少的。"}, {"en": "Psychology is a fascinating discipline.", "cn": "心理学是一门引人入胜的学科。"}]', '["regulation", "field"]', '["chaos", "disorder"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('domestic', '/dəˈmestɪk/', 'adjective', 'Relating to the home, family, or one''s own country', '家庭的；国内的；驯养的', 2, 800, '["cet4"]', '来自拉丁语domesticus，domus意为家，表示与家庭生活或本国相关的事务', '[{"en": "The country''s domestic economy is growing steadily.", "cn": "该国的国内经济稳步增长。"}, {"en": "Domestic animals have lived with humans for thousands of years.", "cn": "家畜与人类一起生活了数千年。"}]', '["household", "national"]', '["foreign", "wild"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('dominate', '/ˈdɑːmɪneɪt/', 'verb', 'To have power and influence over; to be the most important feature of', '支配；统治；占主导地位', 2, 900, '["cet4"]', '来自拉丁语dominari，dominus意为主人，表示像主人一样控制或支配', '[{"en": "One company dominates the market.", "cn": "一家公司主导着市场。"}, {"en": "The mountain dominates the landscape.", "cn": "这座山在景观中占主导地位。"}]', '["control", "govern"]', '["submit", "follow"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('dynamic', '/daɪˈnæmɪk/', 'adjective', 'Characterized by constant change, activity, or progress', '动态的；有活力的；动力的', 2, 900, '["cet4"]', '来自希腊语dynamikos，dynamis意为力量，原指具有强大力量和活力的特性', '[{"en": "She is a dynamic and ambitious young woman.", "cn": "她是一个充满活力和雄心的年轻女性。"}, {"en": "The market is very dynamic and constantly changing.", "cn": "市场非常活跃，不断变化。"}]', '["energetic", "active"]', '["static", "passive"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('economy', '/ɪˈkɑːnəmi/', 'noun', 'The state of a country regarding production and consumption of goods', '经济；节约；经济体', 1, 300, '["cet4"]', '来自希腊语oikonomia，oikos意为家，nomos意为管理，原指家庭管理，后扩展为国家经济', '[{"en": "The country''s economy is recovering slowly.", "cn": "该国的经济正在缓慢复苏。"}, {"en": "We should practice economy in our daily lives.", "cn": "我们在日常生活中应该厉行节约。"}]', '["finance", "thrift"]', '["waste", "extravagance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('election', '/ɪˈlekʃn/', 'noun', 'A formal process of selecting a person for a position by voting', '选举；当选；选择权', 1, 500, '["cet4"]', '来自拉丁语electio，eligere意为选出，e-（出）+ legere（选择），表示通过选择做出决定', '[{"en": "The presidential election will be held next year.", "cn": "总统选举将于明年举行。"}, {"en": "She won the election with a large majority.", "cn": "她以多数票赢得了选举。"}]', '["vote", "poll"]', '["appointment", "nomination"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('eliminate', '/ɪˈlɪmɪneɪt/', 'verb', 'To completely remove or get rid of something', '消除；淘汰；排除', 2, 800, '["cet4"]', '来自拉丁语eliminare，e-（出）+ limen（门槛），原意为逐出门外，即彻底排除', '[{"en": "The government aims to eliminate poverty.", "cn": "政府旨在消除贫困。"}, {"en": "Three teams were eliminated in the first round.", "cn": "三支队伍在第一轮被淘汰。"}]', '["remove", "eradicate"]', '["add", "include"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('emotion', '/ɪˈmoʊʃn/', 'noun', 'A strong feeling such as love, fear, or anger', '情感；情绪；感动', 1, 600, '["cet4"]', '来自拉丁语emovere，e-（出）+ movere（移动），原意为内心被搅动产生的强烈感受', '[{"en": "She showed no emotion when she heard the news.", "cn": "她听到消息时没有表现出任何情绪。"}, {"en": "Music can evoke powerful emotions.", "cn": "音乐能唤起强烈的情感。"}]', '["feeling", "sentiment"]', '["apathy", "indifference"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('emphasis', '/ˈemfəsɪs/', 'noun', 'Special importance or significance given to something', '强调；重点；重要性', 2, 800, '["cet4"]', '来自希腊语emphasis，em-（在…中）+ phainein（显示），原指突出显示某事物的重要性', '[{"en": "The school places great emphasis on reading skills.", "cn": "学校非常重视阅读技能。"}, {"en": "The emphasis should be on quality rather than quantity.", "cn": "重点应放在质量而非数量上。"}]', '["stress", "highlight"]', '["de-emphasis", "neglect"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('employ', '/ɪmˈplɔɪ/', 'verb', 'To give work to someone and pay them for it; to make use of', '雇用；使用；利用', 1, 500, '["cet4"]', '源自古法语employer，来自拉丁语implicare，im-（在…中）+ plicare（折叠），原意为使卷入', '[{"en": "The factory employs over 500 workers.", "cn": "这家工厂雇用了500多名工人。"}, {"en": "New technology is being employed in the classroom.", "cn": "新技术正在课堂中得到应用。"}]', '["hire", "utilize"]', '["fire", "dismiss"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('enable', '/ɪˈneɪbl/', 'verb', 'To give someone the authority or means to do something', '使能够；启用；允许', 1, 600, '["cet4"]', '由en-（使）和able（能够，来自拉丁语habilis）组合，表示赋予能力或条件使某事成为可能', '[{"en": "The scholarship enabled her to attend university.", "cn": "奖学金使她能够上大学。"}, {"en": "Technology has enabled us to communicate more easily.", "cn": "技术使我们能够更轻松地交流。"}]', '["empower", "allow"]', '["prevent", "hinder"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('encourage', '/ɪnˈkɜːrɪdʒ/', 'verb', 'To give support, confidence, or hope to someone', '鼓励；激励；促进', 1, 400, '["cet4"]', '由en-（使）和courage（勇气，来自拉丁语cor心）组合，表示给予勇气', '[{"en": "Parents should encourage their children to read.", "cn": "父母应该鼓励孩子阅读。"}, {"en": "The teacher encouraged us to ask questions.", "cn": "老师鼓励我们提问。"}]', '["motivate", "inspire"]', '["discourage", "deter"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('engage', '/ɪnˈɡeɪdʒ/', 'verb', 'To occupy or attract interest; to participate in', '从事；参与；吸引；订婚', 1, 500, '["cet4"]', '源自古法语engagier，en-（在…中）+ gage（保证），原意为以承诺约束自己', '[{"en": "She engaged in volunteer work during the summer.", "cn": "她在暑假期间从事志愿者工作。"}, {"en": "The book failed to engage my interest.", "cn": "这本书没能引起我的兴趣。"}]', '["involve", "participate"]', '["disengage", "withdraw"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('enhance', '/ɪnˈhæns/', 'verb', 'To improve the quality, value, or extent of', '增强；提高；改善', 2, 800, '["cet4"]', '源自古法语enhaucier，来自拉丁语in-（向上）+ altus（高），表示使事物变得更高更好', '[{"en": "Regular exercise can enhance your health.", "cn": "定期锻炼可以增强你的健康。"}, {"en": "The new lighting enhances the beauty of the building.", "cn": "新灯光增添了建筑的美感。"}]', '["improve", "boost"]', '["reduce", "diminish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('environment', '/ɪnˈvaɪrənmənt/', 'noun', 'The surroundings or conditions in which a person lives', '环境；自然环境；周围', 1, 300, '["cet4"]', '源自古法语environner，en-（在…中）+ virer（转），表示围绕在周围的一切条件', '[{"en": "We should protect the environment.", "cn": "我们应该保护环境。"}, {"en": "A good learning environment is important for children.", "cn": "良好的学习环境对孩子很重要。"}]', '["surroundings", "habitat"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('evaluate', '/ɪˈvæljueɪt/', 'verb', 'To form an idea of the amount or value of; to assess', '评估；评价；估价', 1, 600, '["cet4"]', '由e-（出）和value（价值，来自拉丁语valere有价值）组合，表示评估出价值', '[{"en": "We need to evaluate the results of the experiment.", "cn": "我们需要评估实验结果。"}, {"en": "The teacher will evaluate each student''s performance.", "cn": "老师将评估每个学生的表现。"}]', '["assess", "appraise"]', '["ignore", "neglect"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('facility', '/fəˈsɪlɪti/', 'noun', 'A place or equipment provided for a particular purpose', '设施；设备；便利', 1, 700, '["cet4"]', '来自拉丁语facilitas，facilis意为容易的，facere意为做，表示使做事容易的条件', '[{"en": "The hotel has excellent sports facilities.", "cn": "这家酒店有极好的体育设施。"}, {"en": "The new facility will open next month.", "cn": "新设施将于下月开放。"}]', '["amenity", "installation"]', '["difficulty", "hindrance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('failure', '/ˈfeɪljər/', 'noun', 'Lack of success; omission of expected action', '失败；故障；破产', 1, 400, '["cet4"]', '源自古法语faillir，来自拉丁语fallere（欺骗、失败），表示未能达成预期目标', '[{"en": "Failure is the mother of success.", "cn": "失败是成功之母。"}, {"en": "The engine failure caused the plane to make an emergency landing.", "cn": "引擎故障导致飞机紧急降落。"}]', '["defeat", "breakdown"]', '["success", "achievement"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('flexible', '/ˈfleksɪbl/', 'adjective', 'Capable of bending easily; able to be changed or adapted', '灵活的；柔韧的；可变通的', 1, 800, '["cet4"]', '来自拉丁语flexibilis，flectere意为弯曲，表示容易弯曲或灵活变通的', '[{"en": "We need a more flexible approach to this problem.", "cn": "我们需要对这个问题采取更灵活的方法。"}, {"en": "The material is both strong and flexible.", "cn": "这种材料既坚固又有弹性。"}]', '["adaptable", "pliable"]', '["rigid", "inflexible"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('generate', '/ˈdʒenəreɪt/', 'verb', 'To cause something to arise; to produce energy', '产生；生成；引起', 1, 600, '["cet4"]', '来自拉丁语generare，genus意为种类、出生，表示使事物产生或生成', '[{"en": "The power station generates electricity for the whole city.", "cn": "发电站为整个城市供电。"}, {"en": "The project generated a lot of public interest.", "cn": "该项目引起了公众的极大兴趣。"}]', '["produce", "create"]', '["destroy", "eliminate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('genuine', '/ˈdʒenjuɪn/', 'adjective', 'Truly what it is said to be; sincere', '真正的；真诚的；名副其实的', 2, 1000, '["cet4"]', '来自拉丁语genuinus，genu意为膝盖，古罗马父亲将新生儿放在膝上表示承认', '[{"en": "Is this a genuine diamond?", "cn": "这是真钻石吗？"}, {"en": "She showed genuine concern for his well-being.", "cn": "她对他的幸福表现出真诚的关心。"}]', '["authentic", "sincere"]', '["fake", "artificial"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('hesitate', '/ˈhezɪteɪt/', 'verb', 'To pause before doing something because of uncertainty', '犹豫；迟疑；不愿意', 2, 1000, '["cet4"]', '来自拉丁语haesitare，haerere意为粘住、附着，表示因不确定而停住不前', '[{"en": "Don''t hesitate to ask for help if you need it.", "cn": "如果需要帮助，不要犹豫。"}, {"en": "She hesitated before opening the door.", "cn": "她在开门前犹豫了一下。"}]', '["waver", "pause"]', '["decide", "proceed"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('highlight', '/ˈhaɪlaɪt/', 'verb', 'To pick out and emphasize', '强调；突出；最精彩部分', 1, 600, '["cet4"]', '由high（高）和light（光）组合，原指用高光标记文字，引申为强调重要部分', '[{"en": "The report highlights the need for reform.", "cn": "报告强调了改革的必要性。"}, {"en": "The highlight of the trip was visiting the ancient temple.", "cn": "旅行的亮点是参观古庙。"}]', '["emphasize", "spotlight"]', '["downplay", "ignore"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('humble', '/ˈhʌmbl/', 'adjective', 'Having a modest estimate of one''s importance', '谦逊的；卑微的；简陋的', 2, 1100, '["cet4"]', '来自拉丁语humilis，humus意为土地，原意为接近地面的，引申为谦虚不自大的', '[{"en": "He remained humble despite his great success.", "cn": "尽管取得了巨大成功，他仍然保持谦逊。"}, {"en": "They lived in a humble cottage by the river.", "cn": "他们住在河边一间简陋的小屋里。"}]', '["modest", "meek"]', '["arrogant", "proud"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('identity', '/aɪˈdentɪti/', 'noun', 'The fact of being who or what a person or thing is', '身份；特性；同一性', 2, 800, '["cet4"]', '来自拉丁语identitas，idem意为同一个，表示使某人或某物可被识别的独特特征', '[{"en": "She had to prove her identity before entering the building.", "cn": "她必须在进入大楼前证明自己的身份。"}, {"en": "The country has a strong national identity.", "cn": "这个国家有很强的民族认同感。"}]', '["individuality", "character"]', '["anonymity", "similarity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('impact', '/ˈɪmpækt/', 'noun', 'A marked effect or influence', '影响；冲击；碰撞', 1, 400, '["cet4"]', '来自拉丁语impactus，impingere意为推入，im-（向）+ pangere（固定），原指物理撞击', '[{"en": "The new law will have a major impact on businesses.", "cn": "新法律将对企业产生重大影响。"}, {"en": "The environmental impact is being assessed.", "cn": "环境影响正在评估中。"}]', '["influence", "effect"]', '["insignificance", "irrelevance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('implement', '/ˈɪmplɪment/', 'verb', 'To put a plan or decision into effect', '实施；执行；工具', 2, 800, '["cet4"]', '来自拉丁语implere，im-（在…中）+ plere（填充），原意为填满完成，引申为付诸实施', '[{"en": "The government plans to implement new education reforms.", "cn": "政府计划实施新的教育改革。"}, {"en": "Farmers use various implements to work the land.", "cn": "农民使用各种农具耕种土地。"}]', '["execute", "carry out"]', '["neglect", "abandon"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('indicate', '/ˈɪndɪkeɪt/', 'verb', 'To point out or show something; to be a sign of', '表明；指出；暗示', 1, 500, '["cet4"]', '来自拉丁语indicare，in-（在…上）+ dicare（宣告），表示通过迹象指明或显示', '[{"en": "Research indicates that exercise improves mental health.", "cn": "研究表明锻炼能改善心理健康。"}, {"en": "The arrow on the sign indicates the direction.", "cn": "标志上的箭头指明了方向。"}]', '["show", "suggest"]', '["conceal", "hide"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('individual', '/ˌɪndɪˈvɪdʒuəl/', 'noun', 'A single human being considered separately from a group', '个人；个体；独特的', 1, 400, '["cet4"]', '来自拉丁语individuus，in-（不）+ dividuus（可分的），表示不可再分的最小单位', '[{"en": "Each individual has the right to express their opinion.", "cn": "每个人都有表达自己观点的权利。"}, {"en": "The needs of the individual must be considered.", "cn": "必须考虑个人的需求。"}]', '["person", "entity"]', '["group", "collective"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('influence', '/ˈɪnfluəns/', 'noun', 'The capacity to have an effect on someone''s behavior', '影响；影响力；势力', 1, 400, '["cet4"]', '来自拉丁语influere，in-（进入）+ fluere（流动），原指星体向人间倾注的神秘力量', '[{"en": "Parents have a great influence on their children.", "cn": "父母对孩子有很大的影响。"}, {"en": "He used his political influence to get the law changed.", "cn": "他利用自己的政治影响力推动了法律修改。"}]', '["effect", "impact"]', '["powerlessness", "insignificance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('maintain', '/meɪnˈteɪn/', 'verb', 'To cause something to continue; to keep in good condition', '维持；保养；坚持；赡养', 1, 400, '["cet4"]', '来自拉丁语manu tenere，manus意为手，tenere意为持有，原意为握在手中保持', '[{"en": "It is important to maintain good health.", "cn": "保持良好的健康很重要。"}, {"en": "The building is well maintained.", "cn": "这栋楼保养得很好。"}]', '["preserve", "sustain"]', '["neglect", "abandon"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('negotiate', '/nɪˈɡoʊʃieɪt/', 'verb', 'To discuss something in order to reach an agreement', '谈判；协商；顺利通过', 1, 700, '["cet4"]', '来自拉丁语negotiari，nec-（不）+ otium（闲暇），原意为不空闲忙于事务', '[{"en": "The two sides are negotiating a peace agreement.", "cn": "双方正在谈判和平协议。"}, {"en": "She negotiated a better salary.", "cn": "她谈判获得了更高的薪水。"}]', '["bargain", "mediate"]', '["impose", "dictate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('jealousy', '/ˈdʒeləsi/', 'noun', 'The feeling of being envious of someone', '嫉妒；猜忌；羡慕', 2, 1200, '["cet4"]', '源自古法语jalousie，来自希腊语zelos（热情、竞争），表示对他人拥有的东西感到不满', '[{"en": "His success aroused the jealousy of his colleagues.", "cn": "他的成功引起了同事们的嫉妒。"}, {"en": "Jealousy can destroy relationships.", "cn": "嫉妒可以摧毁关系。"}]', '["envy", "resentment"]', '["admiration", "contentment"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('judgment', '/ˈdʒʌdʒmənt/', 'noun', 'The ability to make considered decisions', '判断；审判；评价', 1, 700, '["cet4"]', '来自拉丁语judicium，judex意为法官，jus（法律）+ dicere（说），表示法官依据法律做出的判断', '[{"en": "She showed good judgment in choosing her career.", "cn": "她在选择职业方面表现出良好的判断力。"}, {"en": "The court delivered its judgment yesterday.", "cn": "法庭昨天做出了判决。"}]', '["decision", "verdict"]', '["indecision", "uncertainty"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('justify', '/ˈdʒʌstɪfaɪ/', 'verb', 'To show or prove to be right or reasonable', '证明…正当；为…辩护', 2, 900, '["cet4"]', '由just（公正的，来自拉丁语justus）和-fy（使成为）组合，表示使某事显得正当合理', '[{"en": "How can you justify such a large expense?", "cn": "你怎么证明如此大的开支是合理的？"}, {"en": "The end does not justify the means.", "cn": "目的不能证明手段正当。"}]', '["defend", "vindicate"]', '["condemn", "criticize"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('labor', '/ˈleɪbər/', 'noun', 'Work, especially hard physical work', '劳动；劳工；劳工运动', 1, 500, '["cet4"]', '来自拉丁语labor（劳动、辛苦），原指身体的劳累和辛苦工作', '[{"en": "Manual labor is essential in construction.", "cn": "体力劳动在建筑业中是必不可少的。"}, {"en": "The cost of labor has increased significantly.", "cn": "劳动力成本大幅上升。"}]', '["work", "toil"]', '["leisure", "rest"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('launch', '/lɔːntʃ/', 'verb', 'To start a new activity; to send a rocket into space', '发射；发起；推出；启动', 1, 600, '["cet4"]', '源自古法语lanchier，来自拉丁语lanceare（投掷长矛），lancea意为长矛', '[{"en": "The company launched a new product last month.", "cn": "公司上个月推出了一款新产品。"}, {"en": "The rocket was launched successfully.", "cn": "火箭发射成功。"}]', '["initiate", "start"]', '["terminate", "conclude"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('landscape', '/ˈlændskeɪp/', 'noun', 'All the visible features of an area of land', '风景；景观；全景', 1, 800, '["cet4"]', '由land（土地）和scape（景象，源自荷兰语-schap）组合，原为绘画术语', '[{"en": "The landscape of the countryside is beautiful.", "cn": "乡村的风景很美。"}, {"en": "The political landscape has changed dramatically.", "cn": "政治格局发生了巨大变化。"}]', '["scenery", "vista"]', '["indoors", "interior"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('likewise', '/ˈlaɪkwaɪz/', 'adverb', 'In the same way; also; similarly', '同样地；也；类似地', 2, 1200, '["cet4"]', '由like（相似的）和-wise（方式）组合，表示以同样的方式', '[{"en": "Watch what I do and do likewise.", "cn": "看着我怎么做，然后照做。"}, {"en": "She was awarded a prize, and her partner likewise.", "cn": "她获得了奖品，她的搭档也获得了。"}]', '["similarly", "also"]', '["differently", "otherwise"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('manufacture', '/ˌmænjuˈfæktʃər/', 'verb', 'To make goods on a large scale using machinery', '制造；生产；捏造', 1, 700, '["cet4"]', '来自拉丁语manufactura，manus意为手，factura意为制作，原指手工制作', '[{"en": "The factory manufactures electronic components.", "cn": "这家工厂生产电子元件。"}, {"en": "The company manufactures cars in three countries.", "cn": "该公司在三个国家制造汽车。"}]', '["produce", "fabricate"]', '["destroy", "demolish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('obligation', '/ˌɑːblɪˈɡeɪʃn/', 'noun', 'A duty or commitment; a legal or moral requirement', '义务；责任；债务', 2, 1000, '["cet4"]', '来自拉丁语obligatio，ob-（向）+ ligare（绑），原意为被绑定的义务', '[{"en": "Parents have an obligation to educate their children.", "cn": "父母有教育孩子的义务。"}, {"en": "You are under no obligation to accept the offer.", "cn": "你没有义务接受这个提议。"}]', '["duty", "responsibility"]', '["freedom", "exemption"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('oppose', '/əˈpoʊz/', 'verb', 'To actively resist or refuse to comply with', '反对；对抗；抵制', 1, 600, '["cet4"]', '来自拉丁语opponere，ob-（对面）+ ponere（放置），表示放置在对面以示反对', '[{"en": "Many people oppose the new policy.", "cn": "许多人反对新政策。"}, {"en": "She opposed the plan to build a new highway.", "cn": "她反对修建新高速公路的计划。"}]', '["resist", "object to"]', '["support", "endorse"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('origin', '/ˈɔːrɪdʒɪn/', 'noun', 'The point or place where something begins', '起源；来源；出身', 1, 600, '["cet4"]', '来自拉丁语origo，oriri意为升起、出现，表示事物的起点或来源', '[{"en": "The origin of the universe is still a mystery.", "cn": "宇宙的起源仍然是一个谜。"}, {"en": "She is of Chinese origin.", "cn": "她具有中国血统。"}]', '["source", "beginning"]', '["end", "conclusion"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('participate', '/pɑːrˈtɪsɪpeɪt/', 'verb', 'To take part in an activity or event', '参与；参加；分享', 1, 500, '["cet4"]', '来自拉丁语participare，pars意为部分，capere意为拿取，表示拿取自己的一份即参与', '[{"en": "All students are encouraged to participate in class discussions.", "cn": "鼓励所有学生参与课堂讨论。"}, {"en": "She participated in the marathon last year.", "cn": "她去年参加了马拉松比赛。"}]', '["join", "engage"]', '["withdraw", "abstain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('permanent', '/ˈpɜːrmənənt/', 'adjective', 'Lasting indefinitely without change', '永久的；固定的；持久的', 1, 700, '["cet4"]', '来自拉丁语permanere，per-（始终）+ manere（保持），表示始终保持不变的状态', '[{"en": "She is looking for a permanent job.", "cn": "她正在找一份固定的工作。"}, {"en": "The damage to the building is permanent.", "cn": "建筑的损坏是永久性的。"}]', '["lasting", "enduring"]', '["temporary", "fleeting"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('perspective', '/pərˈspektɪv/', 'noun', 'A particular attitude or way of regarding something', '观点；视角；透视法', 2, 900, '["cet4"]', '来自拉丁语perspectiva，perspicere意为看透，per-（通过）+ specere（看），表示观察事物的角度', '[{"en": "Try to see the problem from a different perspective.", "cn": "试着从不同的角度看问题。"}, {"en": "The painting uses perspective to create depth.", "cn": "这幅画运用透视法创造深度感。"}]', '["viewpoint", "outlook"]', '["narrow-mindedness", "bias"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('predict', '/prɪˈdɪkt/', 'verb', 'To say what will happen based on evidence', '预测；预言；预报', 1, 600, '["cet4"]', '来自拉丁语praedicere，prae-（提前）+ dicere（说），表示在事情发生之前说出', '[{"en": "Scientists predict that temperatures will continue to rise.", "cn": "科学家预测温度将继续上升。"}, {"en": "It is impossible to predict the future with certainty.", "cn": "不可能确切地预测未来。"}]', '["forecast", "foresee"]', '["recall", "remember"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('radical', '/ˈrædɪkl/', 'adjective', 'Relating to the fundamental nature; favoring extreme changes', '根本的；激进的；彻底的', 2, 1000, '["cet4"]', '来自拉丁语radicalis，radix意为根，原指触及事物根本的，后引申为彻底变革的', '[{"en": "The government needs radical reform.", "cn": "政府需要彻底的改革。"}, {"en": "He has very radical political views.", "cn": "他的政治观点非常激进。"}]', '["fundamental", "extreme"]', '["moderate", "conservative"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('recognize', '/ˈrekəɡnaɪz/', 'verb', 'To identify from having seen before; to acknowledge', '认出；承认；识别', 1, 500, '["cet4"]', '来自拉丁语recognoscere，re-（再）+ cognoscere（知道），表示再次认出或正式承认', '[{"en": "I didn''t recognize her at first because she had changed so much.", "cn": "我起初没认出她，因为她变化太大了。"}, {"en": "The government recognized the need for change.", "cn": "政府承认了变革的必要性。"}]', '["identify", "acknowledge"]', '["ignore", "deny"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('reform', '/rɪˈfɔːrm/', 'verb', 'To make changes to something in order to improve it', '改革；改造；改正', 1, 600, '["cet4"]', '由re-（再）和form（形成，来自拉丁语forma形状）组合，表示重新塑造以改善', '[{"en": "The government plans to reform the education system.", "cn": "政府计划改革教育体制。"}, {"en": "He promised to reform the tax laws.", "cn": "他承诺改革税法。"}]', '["improve", "revise"]', '["worsen", "preserve"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('resolve', '/rɪˈzɑːlv/', 'verb', 'To settle or find a solution; to decide firmly', '解决；决定；决心', 1, 600, '["cet4"]', '来自拉丁语resolvere，re-（再）+ solvere（解开），表示把复杂问题解开、找到答案', '[{"en": "We must resolve this issue immediately.", "cn": "我们必须立即解决这个问题。"}, {"en": "She resolved to work harder.", "cn": "她决心更加努力工作。"}]', '["solve", "determine"]', '["complicate", "waver"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('routine', '/ruːˈtiːn/', 'noun', 'A sequence of actions regularly followed', '常规；例行公事；日常事务', 1, 800, '["cet4"]', '源自法语routine，来自route（道路），表示每天走的同一条路、固定的程序', '[{"en": "Morning exercise is part of my daily routine.", "cn": "晨练是我日常惯例的一部分。"}, {"en": "She found the office routine boring.", "cn": "她觉得办公室的日常工作很无聊。"}]', '["regimen", "schedule"]', '["irregularity", "spontaneity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('sacrifice', '/ˈsækrɪfaɪs/', 'noun', 'An act of giving up something valued for something else', '牺牲；献祭；祭品', 2, 1000, '["cet4"]', '来自拉丁语sacrificium，sacer（神圣的）+ facere（做），原指献给神的祭品', '[{"en": "Parents often make sacrifices for their children.", "cn": "父母经常为孩子做出牺牲。"}, {"en": "He sacrificed his career for his family.", "cn": "他为了家庭牺牲了自己的事业。"}]', '["offering", "surrender"]', '["gain", "selfishness"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('satisfy', '/ˈsætɪsfaɪ/', 'verb', 'To meet the expectations, needs, or desires of', '满足；使满意；符合', 1, 600, '["cet4"]', '来自拉丁语satisfacere，satis（足够的）+ facere（做），表示做到足够的程度', '[{"en": "The meal satisfied our hunger.", "cn": "这顿饭满足了我们的饥饿。"}, {"en": "Her answer did not satisfy the teacher.", "cn": "她的回答没有让老师满意。"}]', '["fulfill", "content"]', '["dissatisfy", "disappoint"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('significant', '/sɪɡˈnɪfɪkənt/', 'adjective', 'Sufficiently great or important', '重要的；有意义的；显著的', 1, 500, '["cet4"]', '来自拉丁语significare，signum（标记）+ facere（做），表示具有标志性意义的', '[{"en": "There has been a significant increase in sales.", "cn": "销售额有了显著增长。"}, {"en": "This is a significant step forward for the company.", "cn": "这是公司向前迈出的重要一步。"}]', '["important", "notable"]', '["insignificant", "trivial"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('strategy', '/ˈstrætɪdʒi/', 'noun', 'A plan of action designed to achieve a long-term aim', '策略；战略；方针', 1, 600, '["cet4"]', '来自希腊语strategia，strategos意为将军，stratos（军队）+ agein（引导），表示将军的指挥艺术', '[{"en": "We need a new strategy to increase sales.", "cn": "我们需要新的策略来增加销售。"}, {"en": "Military strategy requires careful planning.", "cn": "军事战略需要仔细规划。"}]', '["plan", "tactic"]', '["randomness", "improvisation"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('temporary', '/ˈtempəreri/', 'adjective', 'Lasting for only a limited period of time', '临时的；暂时的', 1, 800, '["cet4"]', '来自拉丁语temporarius，tempus意为时间，表示只持续一段时间的', '[{"en": "This is only a temporary solution to the problem.", "cn": "这只是问题的临时解决方案。"}, {"en": "She found a temporary job while looking for a permanent one.", "cn": "她在找固定工作的同时找了一份临时工作。"}]', '["provisional", "short-term"]', '["permanent", "lasting"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('unique', '/juˈniːk/', 'adjective', 'Being the only one of its kind; unlike anything else', '独特的；唯一的；独一无二的', 1, 600, '["cet4"]', '来自拉丁语unicus，unus意为一，表示独一无二的、无可替代的', '[{"en": "Each person has a unique set of fingerprints.", "cn": "每个人都有独一无二的指纹。"}, {"en": "This is a unique opportunity that shouldn''t be missed.", "cn": "这是一个不应错过的独特机会。"}]', '["distinctive", "singular"]', '["common", "ordinary"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('zone', '/zoʊn/', 'noun', 'An area distinguished by a particular feature or activity', '地带；区域；时区', 1, 800, '["cet4"]', '来自拉丁语zona，源自希腊语zone（腰带），原指像腰带一样环绕地球的地带', '[{"en": "This area is designated as a residential zone.", "cn": "这个区域被划为住宅区。"}, {"en": "The earthquake occurred in a danger zone.", "cn": "地震发生在危险区域。"}]', '["region", "area"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abolish', '/əˈbɒlɪʃ/', 'verb', 'To formally put an end to a system, practice, or institution', '废除，废止', 2, 2150, '["cet6"]', 'ab-(离开) + ol(生长) + -ish(动词后缀)，原义为"使其不再生长"', '[{"en":"The government voted to abolish the death penalty.","cn":"政府投票废除了死刑。"}]', '["eliminate","eradicate","terminate"]', '["establish","institute","create"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abort', '/əˈbɔːrt/', 'verb', 'To end prematurely or cancel a process before completion', '中止，终止；流产', 3, 3200, '["cet6"]', 'ab-(离开) + ort(出生)，原义为"未能出生"', '[{"en":"The mission had to be aborted due to a technical failure.","cn":"由于技术故障，任务不得不中止。"}]', '["cancel","terminate","halt"]', '["complete","continue","succeed"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abridge', '/əˈbrɪdʒ/', 'verb', 'To shorten a book, speech, or other text without losing the sense', '删节，缩减；剥夺', 3, 4100, '["cet6"]', 'a-(去) + bridge(桥)，比喻为"架桥跨越"，引申为缩短', '[{"en":"The editor decided to abridge the novel for younger readers.","cn":"编辑决定为年轻读者删节这部小说。"}]', '["shorten","condense","truncate"]', '["expand","lengthen","extend"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abrupt', '/əˈbrʌpt/', 'adjective', 'Sudden and unexpected, often in an unpleasant way', '突然的，意外的；粗鲁的', 2, 2350, '["cet6"]', 'ab-(离开) + rupt(断裂)，突然断开', '[{"en":"His abrupt departure left everyone in shock.","cn":"他的突然离开让所有人都感到震惊。"}]', '["sudden","unexpected","hasty"]', '["gradual","expected","leisurely"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abstain', '/əbˈsteɪn/', 'verb', 'To restrain oneself from doing or enjoying something', '戒除，弃权', 3, 3400, '["cet6"]', 'abs-(离开) + tain(持有)，保持距离', '[{"en":"He decided to abstain from alcohol for health reasons.","cn":"出于健康原因，他决定戒酒。"}]', '["refrain","forbear","desist"]', '["indulge","participate","engage"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('absurd', '/əbˈsɜːrd/', 'adjective', 'Wildly unreasonable, illogical, or inappropriate', '荒谬的，荒唐的', 2, 2080, '["cet6"]', 'ab-(离开) + surd(聋的)，引申为"不合理"', '[{"en":"It would be absurd to blame her for the accident.","cn":"把事故归咎于她是荒谬的。"}]', '["ridiculous","preposterous","ludicrous"]', '["reasonable","sensible","logical"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abundance', '/əˈbʌndəns/', 'noun', 'A very large quantity of something', '丰富，充裕', 2, 2050, '["cet6"]', 'ab-(加强) + und(波浪) + -ance，波浪涌动，形容大量', '[{"en":"The region is known for its abundance of natural resources.","cn":"该地区以丰富的自然资源而闻名。"}]', '["plenty","profusion","wealth"]', '["scarcity","shortage","deficiency"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accelerate', '/əkˈseləreɪt/', 'verb', 'To begin to move more quickly or to cause something to happen sooner', '加速，促进', 2, 2020, '["cet6"]', 'ac-(加强) + celer(快速) + -ate，使更快', '[{"en":"The company plans to accelerate its expansion into Asian markets.","cn":"公司计划加快向亚洲市场的扩张。"}]', '["speed up","hasten","expedite"]', '["decelerate","slow","delay"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accessible', '/əkˈsesəbl/', 'adjective', 'Able to be reached or entered; easy to understand', '可进入的；可理解的；易接近的', 2, 2030, '["cet6"]', 'ac-(朝向) + cess(走) + -ible，可以走到的', '[{"en":"The museum is accessible by public transport.","cn":"博物馆可以乘坐公共交通到达。"}]', '["reachable","attainable","approachable"]', '["inaccessible","unreachable","unavailable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('acclaim', '/əˈkleɪm/', 'noun', 'Enthusiastic and public praise', '赞扬，称赞', 2, 2800, '["cet6"]', 'ac-(朝向) + claim(呼喊)，大声喝彩', '[{"en":"The film received critical acclaim for its innovative storytelling.","cn":"这部电影因其创新的叙事方式获得了评论界的一致好评。"}]', '["praise","applause","commendation"]', '["criticism","condemnation","denunciation"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accommodate', '/əˈkɒmədeɪt/', 'verb', 'To provide lodging or sufficient space for; to adapt to', '容纳；适应；提供住宿', 2, 2100, '["cet6"]', 'ac-(加强) + commod(方便) + -ate，使方便', '[{"en":"The hotel can accommodate up to 500 guests.","cn":"这家酒店最多可容纳500位客人。"}]', '["house","lodge","adapt"]', '["reject","inconvenience","displace"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accountability', '/əˌkaʊntəˈbɪləti/', 'noun', 'The fact or condition of being responsible for one''s actions', '责任，问责制', 3, 3100, '["cet6"]', 'account(计算、说明) + -ability，能够说明自己的能力', '[{"en":"There must be greater accountability for public spending.","cn":"公共开支必须有更大的问责制。"}]', '["responsibility","liability","answerability"]', '["irresponsibility","impunity","exemption"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accumulate', '/əˈkjuːmjəleɪt/', 'verb', 'To gather together or acquire an increasing number of something', '积累，积聚', 2, 2200, '["cet6"]', 'ac-(加强) + cumul(堆) + -ate，不断堆积', '[{"en":"She accumulated a vast collection of rare books over the years.","cn":"多年来她积累了大量珍本书籍。"}]', '["amass","collect","gather"]', '["dissipate","scatter","disperse"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accurate', '/ˈækjərət/', 'adjective', 'Correct in all details; exact', '精确的，准确的', 2, 2010, '["cet6"]', 'ac-(加强) + cur(关心) + -ate，用心做到精确', '[{"en":"The report provides an accurate description of the situation.","cn":"该报告对情况进行了准确的描述。"}]', '["precise","exact","correct"]', '["inaccurate","wrong","erroneous"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accusation', '/ˌækjʊˈzeɪʃən/', 'noun', 'A charge or claim that someone has done something wrong', '指控，控告', 2, 2500, '["cet6"]', 'ac-(朝向) + cus(原因) + -ation，提出原因，即指控', '[{"en":"He denied the accusation of fraud.","cn":"他否认了欺诈指控。"}]', '["allegation","charge","indictment"]', '["defense","exoneration","acquittal"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('acquaint', '/əˈkweɪnt/', 'verb', 'To make someone aware of or familiar with', '使了解，使熟悉', 2, 2900, '["cet6"]', 'ac-(加强) + quaint(认识)，使认识', '[{"en":"You should acquaint yourself with the rules before playing.","cn":"在开始之前你应该先熟悉规则。"}]', '["familiarize","inform","introduce"]', '["estrange","alienate","unfamiliarize"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('acute', '/əˈkjuːt/', 'adjective', 'Having or showing a perceptive understanding; severe or intense', '敏锐的；严重的；急性的', 2, 2300, '["cet6"]', 'ac-(尖) + -ute，尖锐的，引申为敏锐或严重', '[{"en":"The hospital is facing an acute shortage of nurses.","cn":"医院正面临护士严重短缺的问题。"}]', '["sharp","keen","severe"]', '["dull","chronic","mild"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adhere', '/ədˈhɪər/', 'verb', 'To stick fast to a surface; to follow a practice or belief closely', '坚持；粘附；遵守', 2, 2600, '["cet6"]', 'ad-(朝向) + here(粘)，粘在上面', '[{"en":"All members must adhere to the code of conduct.","cn":"所有成员必须遵守行为准则。"}]', '["stick","comply","observe"]', '["detach","violate","deviate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adjacent', '/əˈdʒeɪsənt/', 'adjective', 'Close to or next to something', '邻近的，毗连的', 2, 2450, '["cet6"]', 'ad-(朝向) + jac(投掷) + -ent，投向旁边的', '[{"en":"The fire spread to the adjacent building.","cn":"火势蔓延到了邻近的建筑。"}]', '["neighboring","adjoining","contiguous"]', '["distant","remote","separate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adjective', '/ˈædʒɪktɪv/', 'noun', 'A word that describes or modifies a noun', '形容词', 2, 2750, '["cet6"]', 'ad-(朝向) + ject(投掷) + -ive，附加到名词上的', '[{"en":"In English, the adjective usually comes before the noun.","cn":"在英语中，形容词通常放在名词之前。"}]', '["modifier","descriptor"]', '["noun","verb"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('administer', '/ədˈmɪnɪstər/', 'verb', 'To manage and be responsible for the running of a business or organization', '管理，执行', 2, 2250, '["cet6"]', 'ad-(朝向) + minister(服务者)，去服务和管理', '[{"en":"She was appointed to administer the company''s pension fund.","cn":"她被任命管理公司的养老基金。"}]', '["manage","govern","supervise"]', '["neglect","mismanage","abandon"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adolescent', '/ˌædəˈlesənt/', 'noun', 'A young person in the process of developing into an adult', '青少年', 2, 2400, '["cet6"]', 'ad-(朝向) +olesc(成长) + -ent，正在成长的人', '[{"en":"Many adolescents struggle with issues of identity and self-esteem.","cn":"许多青少年在身份认同和自尊方面有困扰。"}]', '["teenager","youth","juvenile"]', '["adult","elder","senior"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adorn', '/əˈdɔːrn/', 'verb', 'To make more beautiful or attractive; to decorate', '装饰，装扮', 3, 3800, '["cet6"]', 'ad-(朝向) + orn(装饰)，加以装饰', '[{"en":"Flowers adorned the tables at the banquet.","cn":"鲜花装饰着宴会桌上的桌面。"}]', '["decorate","embellish","ornament"]', '["strip","deface","disfigure"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('advent', '/ˈædvent/', 'noun', 'The arrival of a notable person, thing, or event', '到来，出现', 2, 2650, '["cet6"]', 'ad-(朝向) + vent(来)，来到', '[{"en":"The advent of the internet revolutionized communication.","cn":"互联网的出现彻底改变了通信方式。"}]', '["arrival","emergence","appearance"]', '["departure","exit","disappearance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adversity', '/ədˈvɜːrsəti/', 'noun', 'Difficulties; misfortune', '逆境，不幸', 2, 2850, '["cet6"]', 'ad-(朝向) + vers(转) + -ity，转向不好的一面', '[{"en":"She showed great courage in the face of adversity.","cn":"面对逆境她表现出了极大的勇气。"}]', '["hardship","misfortune","tribulation"]', '["prosperity","fortune","blessing"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('advocate', '/ˈædvəkeɪt/', 'verb', 'To publicly recommend or support a particular cause or policy', '提倡，拥护', 2, 2100, '["cet6"]', 'ad-(朝向) + voc(声音) + -ate，为其发声', '[{"en":"She advocates for equal rights for all citizens.","cn":"她提倡所有公民享有平等权利。"}]', '["support","champion","promote"]', '["oppose","condemn","denounce"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aesthetic', '/iːsˈθetɪk/', 'adjective', 'Concerned with beauty or the appreciation of beauty', '美学的，审美的', 3, 3050, '["cet6"]', 'aisthetikos(感知)，源自希腊语，关于美的感知', '[{"en":"The building has great aesthetic appeal with its modern design.","cn":"这座建筑以其现代设计具有极大的审美吸引力。"}]', '["artistic","beautiful","tasteful"]', '["ugly","unartistic","tasteless"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('affiliate', '/əˈfɪlieɪt/', 'verb', 'To officially attach or connect to an organization', '使隶属，使附属', 3, 3300, '["cet6"]', 'af-(朝向) + fili(儿子) + -ate，成为其子机构', '[{"en":"The college is affiliated to the national university system.","cn":"该学院隶属于国家大学体系。"}]', '["associate","allied","connect"]', '["separate","disconnect","dissociate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('affirm', '/əˈfɜːrm/', 'verb', 'To state emphatically or publicly that something is true', '肯定，断言；批准', 2, 2550, '["cet6"]', 'af-(加强) + firm(坚固)，使更加坚定', '[{"en":"The court affirmed the lower court''s decision.","cn":"法院批准了下级法院的裁决。"}]', '["assert","confirm","declare"]', '["deny","contradict","refute"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('affluent', '/ˈæfluənt/', 'adjective', 'Having a great deal of money; wealthy', '富裕的，富足的', 2, 2700, '["cet6"]', 'af-(朝向) + flu(流) + -ent，财富源源不断流入', '[{"en":"They live in an affluent neighborhood with large houses.","cn":"他们住在一个拥有大型住宅的富裕社区。"}]', '["wealthy","prosperous","rich"]', '["poor","impoverished","destitute"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aggravate', '/ˈæɡrəveɪt/', 'verb', 'To make a problem, injury, or offense worse or more serious', '加重，恶化；激怒', 2, 2900, '["cet6"]', 'ag-(加强) + grav(重) + -ate，使更重', '[{"en":"His comments only served to aggravate the situation.","cn":"他的评论只会使局势更加恶化。"}]', '["worsen","intensify","exacerbate"]', '["alleviate","improve","mitigate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aggregate', '/ˈæɡrɪɡeɪt/', 'noun', 'A whole formed by combining several elements', '总计，合计；聚合体', 3, 3150, '["cet6"]', 'ag-(朝向) + greg(群体) + -ate，聚集到一起', '[{"en":"The aggregate score determines the final ranking.","cn":"总分决定最终排名。"}]', '["total","sum","composite"]', '["individual","single","separate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('agitate', '/ˈædʒɪteɪt/', 'verb', 'To make someone troubled or nervous; to campaign for a cause', '使焦虑；煽动；搅动', 3, 3500, '["cet6"]', 'ag(做) + -itate，反复做，使其不安', '[{"en":"The protesters continued to agitate for political reform.","cn":"抗议者继续为政治改革而奔走。"}]', '["disturb","stir","provoke"]', '["calm","soothe","pacify"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('agony', '/ˈæɡəni/', 'noun', 'Extreme physical or mental suffering', '极度痛苦', 2, 2600, '["cet6"]', 'agon(竞争、挣扎) + -y，源自希腊语agonia', '[{"en":"She waited in agony for news of her missing son.","cn":"她在极度痛苦中等待失踪儿子的消息。"}]', '["suffering","torment","anguish"]', '["comfort","pleasure","relief"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allege', '/əˈledʒ/', 'verb', 'To claim or assert that someone has done something wrong, typically without proof', '声称，断言（无证据）', 3, 3200, '["cet6"]', 'al-(朝向) + lege(法律)，在法律上提出指控', '[{"en":"He is alleged to have stolen millions of dollars.","cn":"据称他偷了数百万美元。"}]', '["claim","assert","contend"]', '["prove","demonstrate","substantiate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allegiance', '/əˈliːdʒəns/', 'noun', 'Loyalty or commitment to a group, cause, or person', '忠诚，效忠', 3, 3450, '["cet6"]', 'al-(加强) + lige(绑定) + -ance，绑在一起的状态', '[{"en":"Soldiers swear allegiance to their country.","cn":"士兵宣誓效忠国家。"}]', '["loyalty","devotion","fidelity"]', '["disloyalty","treason","betrayal"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allergy', '/ˈælərdʒi/', 'noun', 'A damaging immune response by the body to a substance', '过敏，变态反应', 2, 2850, '["cet6"]', 'allo-(异) + ergy(反应)，对异物的反应', '[{"en":"She has a severe allergy to peanuts.","cn":"她对花生严重过敏。"}]', '["hypersensitivity","intolerance","reaction"]', '["immunity","tolerance","resistance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('alleviate', '/əˈliːvieɪt/', 'verb', 'To make suffering, deficiency, or a problem less severe', '减轻，缓和', 2, 2500, '["cet6"]', 'al-(加强) + levi(轻) + -ate，使变轻', '[{"en":"The medicine helped to alleviate her pain.","cn":"这种药物帮助减轻了她的疼痛。"}]', '["relieve","ease","mitigate"]', '["aggravate","worsen","intensify"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('alliance', '/əˈlaɪəns/', 'noun', 'A union or association formed for mutual benefit', '联盟，结盟', 2, 2300, '["cet6"]', 'al-(加强) + li(绑定) + -ance，绑在一起', '[{"en":"The two countries formed a military alliance.","cn":"两国建立了军事联盟。"}]', '["coalition","partnership","union"]', '["conflict","opposition","rivalry"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allocate', '/ˈæləkeɪt/', 'verb', 'To distribute resources or duties for a particular purpose', '分配，拨出', 2, 2150, '["cet6"]', 'al-(加强) + loc(地方) + -ate，安排到各个位置', '[{"en":"The government allocated funds for education reform.","cn":"政府拨款用于教育改革。"}]', '["assign","distribute","apportion"]', '["withhold","retain","hoard"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allowance', '/əˈlaʊəns/', 'noun', 'The amount of something permitted; a sum of money granted regularly', '津贴，补贴；限额', 2, 2650, '["cet6"]', 'al-(加强) + low(允许) + -ance，允许给予的东西', '[{"en":"Employees receive a travel allowance of $200 per month.","cn":"员工每月可获得200美元的差旅补贴。"}]', '["stipend","subsidy","ration"]', '["denial","prohibition","withholding"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allusion', '/əˈluːʒən/', 'noun', 'An indirect or passing reference to something', '暗示，典故', 3, 3600, '["cet6"]', 'al-(朝向) + lus(玩) + -ion，玩弄文字，暗指', '[{"en":"The poem contains an allusion to Shakespeare''s Hamlet.","cn":"这首诗暗指了莎士比亚的《哈姆雷特》。"}]', '["reference","hint","implication"]', '["direct statement","explicit mention"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('alternate', '/ɔːlˈtɜːrnət/', 'adjective', 'Every other; occurring by turns', '交替的，轮流的', 2, 2700, '["cet6"]', 'alter(另一个) + -nate，一个接一个', '[{"en":"The meeting is held on alternate Thursdays.","cn":"会议每隔一个星期四举行一次。"}]', '["alternating","rotating","successive"]', '["continuous","constant","uninterrupted"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('amateur', '/ˈæmətər/', 'noun', 'A person who engages in a pursuit on an unpaid basis', '业余爱好者；外行', 2, 2400, '["cet6"]', 'amat(爱) + -eur，出于爱好而做的人', '[{"en":"He started as an amateur photographer before turning professional.","cn":"他在成为专业人士之前是一名业余摄影师。"}]', '["enthusiast","hobbyist","novice"]', '["professional","expert","specialist"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ambiguity', '/ˌæmbɪˈɡjuːəti/', 'noun', 'The quality of being open to more than one interpretation', '模棱两可，含糊不清', 3, 3250, '["cet6"]', 'ambi-(两个) + ig(做) + -uity，可以做两种理解', '[{"en":"The ambiguity of the law led to many legal disputes.","cn":"法律的模糊性导致了许多法律纠纷。"}]', '["vagueness","uncertainty","equivocation"]', '["clarity","certainty","precision"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('amend', '/əˈmend/', 'verb', 'To make minor changes to a text or piece of legislation in order to improve it', '修改，修正', 2, 2450, '["cet6"]', 'a-(加强) + mend(修复)，加以修复', '[{"en":"Parliament voted to amend the constitution.","cn":"议会投票修改宪法。"}]', '["revise","modify","rectify"]', '["worsen","corrupt","damage"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ample', '/ˈæmpəl/', 'adjective', 'Enough or more than enough; plentiful', '充足的，丰富的', 2, 2550, '["cet6"]', 'ampl(大) + -e，足够大的', '[{"en":"There was ample evidence to support the theory.","cn":"有充分的证据支持这一理论。"}]', '["plentiful","abundant","sufficient"]', '["scarce","insufficient","inadequate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('analogy', '/əˈnælədʒi/', 'noun', 'A comparison between two things for the purpose of explanation', '类比，类推', 2, 2800, '["cet6"]', 'ana-(依照) + logy(比例)，按比例比较', '[{"en":"He drew an analogy between the heart and a pump.","cn":"他把心脏与水泵进行了类比。"}]', '["comparison","parallel","correlation"]', '["contrast","difference","dissimilarity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('analytical', '/ˌænəˈlɪtɪkəl/', 'adjective', 'Relating to or using analysis or logical reasoning', '分析的，解析的', 2, 2350, '["cet6"]', 'ana-(向上) + ly(解开) + -tical，分解研究的', '[{"en":"She has strong analytical skills that make her a great researcher.","cn":"她有很强的分析能力，这使她成为一名优秀的研究人员。"}]', '["logical","systematic","methodical"]', '["synthetic","intuitive","unsystematic"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('angel', '/ˈeɪndʒəl/', 'noun', 'A spiritual being believed to act as an attendant or messenger of God', '天使', 2, 2200, '["cet6"]', 'angelos(使者)，源自希腊语，神的信使', '[{"en":"She was like an angel who came to help in his time of need.","cn":"她就像一个天使，在他困难的时候来帮助他。"}]', '["cherub","seraph","guardian"]', '["demon","devil","fiend"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('animate', '/ˈænɪmeɪt/', 'verb', 'To bring to life; to give energy and enthusiasm to', '赋予生命；使有活力', 3, 3700, '["cet6"]', 'anim(生命) + -ate，给予生命', '[{"en":"The characters in the film were beautifully animated.","cn":"电影中的人物被精美地赋予了生命力。"}]', '["enliven","vitalize","inspire"]', '["deaden","discourage","suppress"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('annex', '/əˈneks/', 'verb', 'To add as an extra or subordinate part; to seize territory', '吞并，附加', 3, 3900, '["cet6"]', 'an-(加强) + nex(绑定)，绑到一起', '[{"en":"The country attempted to annex the disputed territory.","cn":"该国试图吞并有争议的领土。"}]', '["seize","appropriate","attach"]', '["release","surrender","detach"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('anonymous', '/əˈnɒnɪməs/', 'adjective', 'Not identified by name; of unknown identity', '匿名的，无名的', 2, 2300, '["cet6"]', 'an-(无) + onym(名字) + -ous，没有名字的', '[{"en":"The donor wished to remain anonymous.","cn":"捐赠者希望保持匿名。"}]', '["unnamed","nameless","unidentified"]', '["named","identified","known"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('apparatus', '/ˌæpəˈreɪtəs/', 'noun', 'The technical equipment or machinery needed for a particular activity', '设备，器械；机构', 3, 3400, '["cet6"]', 'ap-(朝向) + par(准备) + -atus，准备好的工具', '[{"en":"The laboratory has sophisticated scientific apparatus.","cn":"实验室拥有精密的科学设备。"}]', '["equipment","machinery","device"]', '["none","absence"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('appease', '/əˈpiːz/', 'verb', 'To pacify or relieve a feeling by giving in to demands', '安抚，平息；绥靖', 3, 3600, '["cet6"]', 'ap-(朝向) + pease(和平)，使和平', '[{"en":"The government tried to appease the protesters by lowering taxes.","cn":"政府试图通过降低税收来安抚抗议者。"}]', '["pacify","placate","conciliate"]', '["provoke","agitate","inflame"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('applaud', '/əˈplɔːd/', 'verb', 'To show approval or praise by clapping; to express strong approval', '鼓掌，称赞', 2, 2400, '["cet6"]', 'ap-(加强) + plaud(拍手)，大声拍手', '[{"en":"The audience stood up to applaud the performers.","cn":"观众起立为表演者鼓掌。"}]', '["cheer","commend","praise"]', '["boo","criticize","condemn"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('applicable', '/əˈplɪkəbl/', 'adjective', 'Relevant or appropriate in the circumstances', '适用的，可应用的', 2, 2250, '["cet6"]', 'ap-(朝向) + plic(折叠) + -able，可以贴合的', '[{"en":"These regulations are applicable to all employees.","cn":"这些规定适用于所有员工。"}]', '["relevant","appropriate","suitable"]', '["irrelevant","inapplicable","unsuitable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('appraisal', '/əˈpreɪzəl/', 'noun', 'An expert estimate of the value of something; an assessment', '评估，鉴定', 2, 2750, '["cet6"]', 'ap-(加强) + pris(价格) + -al，评定价格', '[{"en":"The annual performance appraisal is conducted every December.","cn":"年度绩效评估每年12月进行。"}]', '["assessment","evaluation","estimate"]', '["ignorance","neglect","overlook"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('apprehend', '/ˌæprɪˈhend/', 'verb', 'To arrest someone for a crime; to understand or perceive', '逮捕；理解；忧虑', 3, 3500, '["cet6"]', 'ap-(朝向) + preh(抓取) + -end，抓住', '[{"en":"Police apprehended the suspect after a three-day manhunt.","cn":"警方在三天的搜捕后逮捕了嫌疑人。"}]', '["arrest","capture","comprehend"]', '["release","liberate","misunderstand"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('arbitrary', '/ˈɑːrbɪtrəri/', 'adjective', 'Based on random choice or personal whim rather than any reason or system', '任意的，武断的', 2, 2550, '["cet6"]', 'arbitr(裁判) + -ary，由裁判个人决定的', '[{"en":"The decision seemed arbitrary and unfair to many people.","cn":"这个决定在许多人看来是武断且不公平的。"}]', '["random","capricious","whimsical"]', '["rational","logical","systematic"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('archaic', '/ɑːrˈkeɪɪk/', 'adjective', 'Very old or old-fashioned; from an earlier period', '古老的，过时的', 3, 3800, '["cet6"]', 'archai(古老的) + -ic，源自希腊语archaios', '[{"en":"The archaic laws no longer apply to modern society.","cn":"那些古老的法律不再适用于现代社会。"}]', '["antiquated","obsolete","outdated"]', '["modern","current","contemporary"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('articulate', '/ɑːrˈtɪkjəleɪt/', 'adjective', 'Having or showing the ability to speak fluently and coherently', '表达清晰的；发音清楚的', 2, 2700, '["cet6"]', 'articul(关节) + -ate，说话条理分明如同关节连接', '[{"en":"She is an articulate speaker who can convey complex ideas clearly.","cn":"她是一位表达清晰的演讲者，能够清楚地传达复杂的想法。"}]', '["eloquent","fluent","coherent"]', '["inarticulate","mumbling","unclear"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
