INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assertion', '/əˈsɜːrʃən/', 'noun', 'A confident and forceful statement of fact or belief', '断言，声明', 2, 2650, '["cet6"]', 'as-(加强) + sert(加入) + -ion，坚定地加入自己的观点', '[{"en":"His assertion that the project would fail proved to be wrong.","cn":"他关于该项目会失败的断言被证明是错误的。"}]', '["declaration","claim","statement"]', '["denial","retraction","contradiction"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
