INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('atlas', '/ˈætləs/', 'noun', 'A book of maps or charts; a collection of tables or illustrations', '地图集，图册', 2, 2900, '["cet6"]', 'Atlas(阿特拉斯)，希腊神话中支撑天空的巨人，用于地图集的封面', '[{"en":"She bought a world atlas to study geography.","cn":"她买了一本世界地图集来学习地理。"}]', '["map book","chart collection","guidebook"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('atmosphere', '/ˈætməsfɪər/', 'noun', 'The envelope of gases surrounding the earth; the prevailing mood of a place', '大气层；气氛', 2, 2020, '["cet6"]', 'atmo(蒸汽) + sphere(球体)，包围地球的蒸汽层', '[{"en":"The restaurant has a warm and inviting atmosphere.","cn":"这家餐厅有着温馨宜人的气氛。"}]', '["ambiance","environment","mood"]', '["vacuum","void"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
