INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('benevolent', '/bəˈnevələnt/', 'adjective', 'Well-meaning and kindly; charitable', '仁慈的，慈善的', 3, 3500, '["cet6"]', 'bene(好) + vol(意愿) + -ent，好意的', '[{"en":"The benevolent organization provides food for the homeless.","cn":"这个慈善组织为无家可归者提供食物。"}]', '["kind","generous","charitable"]', '["cruel","malevolent","selfish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('besiege', '/bɪˈsiːdʒ/', 'verb', 'To surround a place with armed forces; to crowd around oppressively', '围攻，包围', 3, 4000, '["cet6"]', 'be-(围绕) + siege(围困)，四面围住', '[{"en":"The army besieged the city for three months.","cn":"军队围困了这座城市三个月。"}]', '["surround","encircle","blockade"]', '["liberate","free","release"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bewilder', '/bɪˈwɪldər/', 'verb', 'To cause someone to become perplexed and confused', '使困惑，使迷惑', 3, 3700, '["cet6"]', 'be-(使) + wilder(迷失)，使迷失方向', '[{"en":"The complex instructions completely bewildered the new employees.","cn":"复杂的说明完全让新员工感到困惑。"}]', '["confuse","perplex","baffle"]', '["clarify","enlighten","explain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bias', '/ˈbaɪəs/', 'noun', 'Prejudice in favor of or against one thing, person, or group', '偏见，偏差', 2, 2200, '["cet6"]', '源自法语biais，倾斜、偏离', '[{"en":"The study revealed a strong bias against female applicants.","cn":"该研究揭示了对女性申请者的严重偏见。"}]', '["prejudice","partiality","discrimination"]', '["fairness","impartiality","objectivity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bilateral', '/baɪˈlætərəl/', 'adjective', 'Having or relating to two sides; affecting both sides', '双边的，双方的', 3, 3100, '["cet6"]', 'bi-(两个) + later(边) + -al，两边的', '[{"en":"The two countries signed a bilateral trade agreement.","cn":"两国签署了一项双边贸易协定。"}]', '["mutual","two-sided","reciprocal"]', '["unilateral","one-sided","single"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bind', '/baɪnd/', 'verb', 'To tie or fasten tightly; to constrain or obligate', '绑定，约束；装订', 2, 2100, '["cet6"]', '源自古英语bindan，捆绑', '[{"en":"The contract binds both parties to the agreed terms.","cn":"合同将双方约束在约定的条款之内。"}]', '["tie","fasten","obligate"]', '["free","release","unbind"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('biography', '/baɪˈɒɡrəfi/', 'noun', 'An account of someone''s life written by someone else', '传记', 2, 2300, '["cet6"]', 'bio(生命) + graphy(书写)，书写一个人的生命', '[{"en":"She wrote a biography of the famous scientist.","cn":"她写了一本关于那位著名科学家的传记。"}]', '["life story","memoir","chronicle"]', '["fiction","novel","fantasy"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('blank', '/blæŋk/', 'adjective', 'Not written or printed on; showing no expression or understanding', '空白的；茫然的', 2, 2050, '["cet6"]', '源自法语blanc，白色的', '[{"en":"She stared at the blank page, unable to start writing.","cn":"她盯着空白的页面，无法开始写作。"}]', '["empty","bare","vacant"]', '["filled","covered","expressive"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('blaze', '/bleɪz/', 'noun', 'A very large or fiercely burning fire; a strong bright light', '火焰，烈火；光辉', 2, 2500, '["cet6"]', '源自古英语blæse，火炬', '[{"en":"Firefighters battled the blaze for over six hours.","cn":"消防员与大火搏斗了六个多小时。"}]', '["flame","inferno","flare"]', '["extinguish","darkness","gloom"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bleak', '/bliːk/', 'adjective', 'Lacking vegetation and exposed; not hopeful or encouraging', '荒凉的；暗淡的，不乐观的', 2, 2700, '["cet6"]', '源自古诺尔斯语bleikr，苍白的', '[{"en":"The economic outlook remains bleak for the foreseeable future.","cn":"在可预见的未来，经济前景仍然暗淡。"}]', '["gloomy","desolate","dismal"]', '["bright","hopeful","cheerful"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('blend', '/blend/', 'verb', 'To mix a substance with another so that they combine', '混合，融合', 2, 2150, '["cet6"]', '源自古英语blandan，混合', '[{"en":"Blend the ingredients together until smooth.","cn":"将配料混合搅拌至顺滑。"}]', '["mix","combine","merge"]', '["separate","divide","isolate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bless', '/bles/', 'verb', 'To ask God to look favorably on; to confer happiness or good fortune upon', '祝福，保佑', 2, 2150, '["cet6"]', '源自bletsian，用血献祭，引申为祝福', '[{"en":"The priest blessed the newly married couple.","cn":"牧师为新婚夫妇祝福。"}]', '["consecrate","sanctify","grace"]', '["curse","damn","condemn"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('blink', '/blɪŋk/', 'verb', 'To shut and open the eyes quickly; to flash on and off', '眨眼；闪烁', 2, 2350, '["cet6"]', '源自中世纪英语blenken，闪烁', '[{"en":"She blinked in the bright sunlight.","cn":"她在明亮的阳光下眨了眨眼。"}]', '["wink","flash","flicker"]', '["stare","gaze","fixate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bliss', '/blɪs/', 'noun', 'Supreme happiness; utter joy', '极乐，至福', 3, 3600, '["cet6"]', '源自古英语bliss，欢乐、幸福', '[{"en":"Lying on the beach in the sunshine was pure bliss.","cn":"躺在阳光下的沙滩上简直是纯粹的幸福。"}]', '["happiness","joy","ecstasy"]', '["misery","sorrow","anguish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abolish', '/əˈbɒlɪʃ/', 'verb', 'To formally put an end to a system, practice, or institution', '废除，废止（制度、习俗等）', 3, 3200, '["kaoyan"]', 'ab-（加强）+ bol（投掷）+ -ish（动词后缀），原义为"彻底抛弃"', '[{"en":"The government voted to abolish the outdated tax law.","cn":"政府投票废除了过时的税法。"}]', '["eliminate","eradicate","terminate"]', '["establish","institute","create"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abstract', '/ˈæbstrækt/', 'adjective', 'Existing in thought or as an idea but not having a physical or concrete existence', '抽象的；理论上的', 3, 2800, '["kaoyan"]', 'abs-（离开）+ tract（拉），字面义"从具体事物中抽离出来"', '[{"en":"The concept of justice is highly abstract and difficult to define.","cn":"正义的概念非常抽象，难以定义。"}]', '["theoretical","conceptual","intangible"]', '["concrete","tangible","practical"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accommodate', '/əˈkɒmədeɪt/', 'verb', 'To provide lodging or sufficient space for; to adapt or adjust to', '容纳；适应；提供住宿', 4, 3100, '["kaoyan"]', 'ac-（朝向）+ commod（方便）+ -ate（动词后缀），使方便、使适应', '[{"en":"The hotel can accommodate up to 500 guests.","cn":"这家酒店最多可容纳500位客人。"}]', '["house","lodge","adapt"]', '["reject","turn away"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accord', '/əˈkɔːd/', 'noun', 'An official agreement or treaty; conformity or harmony', '协议，条约；一致，和谐', 3, 3500, '["kaoyan"]', 'ac-（朝向）+ cord（心），心心相印→一致、协议', '[{"en":"Both nations signed a peace accord after years of conflict.","cn":"两国在多年冲突后签署了和平协议。"}]', '["agreement","treaty","pact"]', '["disagreement","conflict","discord"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accumulate', '/əˈkjuːmjəleɪt/', 'verb', 'To gather or acquire in increasing quantity over time', '积累，积聚', 3, 2900, '["kaoyan"]', 'ac-（加强）+ cumul（堆积）+ -ate（动词后缀），不断堆积', '[{"en":"She accumulated a vast collection of rare books over the years.","cn":"多年来她积累了大量的珍稀书籍。"}]', '["amass","gather","accrue"]', '["dissipate","scatter","deplete"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('acquisition', '/ˌækwɪˈzɪʃn/', 'noun', 'The act of acquiring or gaining possession of something', '获得，取得；收购', 4, 3300, '["kaoyan"]', 'ac-（加强）+ quisit（寻求）+ -ion（名词后缀），寻求并得到的过程', '[{"en":"The acquisition of language skills is critical during early childhood.","cn":"语言技能的习得在幼儿期至关重要。"}]', '["attainment","procurement","purchase"]', '["loss","forfeiture","surrender"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adhere', '/ədˈhɪə/', 'verb', 'To stick firmly to a surface; to follow a practice or belief consistently', '粘附；坚持，遵守', 4, 3400, '["kaoyan"]', 'ad-（朝向）+ here（粘），粘在一起→坚持', '[{"en":"All employees must adhere to the company''s code of conduct.","cn":"所有员工必须遵守公司的行为准则。"}]', '["comply","conform","cling"]', '["violate","deviate","disobey"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adjacent', '/əˈdʒeɪsnt/', 'adjective', 'Close to or next to something; adjoining', '邻近的，毗连的', 3, 3600, '["kaoyan"]', 'ad-（朝向）+ jac（投掷）+ -ent（形容词后缀），投向旁边→邻近的', '[{"en":"The laboratory is adjacent to the main academic building.","cn":"实验室紧邻主教学楼。"}]', '["neighboring","adjoining","contiguous"]', '["distant","remote","faraway"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adolescent', '/ˌædəˈlesnt/', 'noun', 'A young person in the process of developing from a child into an adult', '青少年；青春期的', 3, 3800, '["kaoyan"]', 'ad-（朝向）+olesc（成长）+ -ent（名词/形容词后缀），正在成长的人', '[{"en":"Adolescents are particularly vulnerable to peer pressure.","cn":"青少年特别容易受到同伴压力的影响。"}]', '["teenager","youth","juvenile"]', '["adult","elder","senior"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('advocate', '/ˈædvəkeɪt/', 'verb', 'To publicly recommend or support a particular cause or policy', '提倡，倡导；支持', 3, 2700, '["kaoyan"]', 'ad-（朝向）+ voc（声音）+ -ate（动词后缀），为某事发声→倡导', '[{"en":"Many scholars advocate the use of renewable energy sources.","cn":"许多学者倡导使用可再生能源。"}]', '["promote","champion","endorse"]', '["oppose","condemn","denounce"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aesthetic', '/iːsˈθetɪk/', 'adjective', 'Concerned with beauty or the appreciation of beauty', '审美的，美学的', 4, 3700, '["kaoyan"]', 'aisth-（感知）+ -etic（形容词后缀），与感知美有关的', '[{"en":"The aesthetic value of the building was widely recognized by architects.","cn":"这座建筑的美学价值受到建筑师的广泛认可。"}]', '["artistic","tasteful","elegant"]', '["unattractive","tasteless","ugly"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('affiliate', '/əˈfɪlɪeɪt/', 'verb', 'To officially attach or connect to an organization; to associate closely', '使隶属，使附属；加入', 4, 3900, '["kaoyan"]', 'af-（朝向）+ fili（儿子）+ -ate（动词后缀），收养为子→使隶属', '[{"en":"The research institute is affiliated with the university.","cn":"该研究所隶属于这所大学。"}]', '["associate","ally","attach"]', '["separate","detach","disaffiliate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('agenda', '/əˈdʒendə/', 'noun', 'A list of items to be discussed at a meeting; an underlying plan or motive', '议程；潜在动机', 3, 2600, '["kaoyan"]', 'ag-（做）+ -enda（待做之事），需要做的事情列表→议程', '[{"en":"Environmental protection was placed high on the political agenda.","cn":"环境保护被列在政治议程的重要位置。"}]', '["schedule","program","plan"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aggregate', '/ˈæɡrɪɡət/', 'adjective', 'Formed or calculated by the combination of many separate elements; total', '总计的，合计的；聚合的', 4, 3500, '["kaoyan"]', 'ag-（朝向）+ greg（群体）+ -ate（后缀），聚集到一起→聚合', '[{"en":"The aggregate demand for goods increased significantly last quarter.","cn":"上个季度商品总需求显著增长。"}]', '["total","combined","cumulative"]', '["individual","separate","single"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('align', '/əˈlaɪn/', 'verb', 'To place in a straight line or correct position; to bring into agreement', '对齐，排列；使一致', 3, 3000, '["kaoyan"]', 'a-（朝向）+ lign（线），排成一线→使一致', '[{"en":"The company aims to align its strategy with market demands.","cn":"公司致力于使其战略与市场需求保持一致。"}]', '["adjust","coordinate","synchronize"]', '["misalign","disarrange"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allege', '/əˈledʒ/', 'verb', 'To claim or assert that someone has done something, typically without proof', '声称，断言（未经证实）', 4, 3800, '["kaoyan"]', 'al-（加强）+ lege（法律），在法律上提出声明→声称', '[{"en":"The report alleges that the corporation violated environmental regulations.","cn":"该报告声称该公司违反了环境法规。"}]', '["assert","claim","contend"]', '["prove","demonstrate","verify"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allocate', '/ˈæləkeɪt/', 'verb', 'To distribute resources or duties for a particular purpose', '分配，拨出', 3, 2800, '["kaoyan"]', 'al-（加强）+ loc（位置）+ -ate（动词后缀），放到指定位置→分配', '[{"en":"The government allocated substantial funds to education reform.","cn":"政府拨出大量资金用于教育改革。"}]', '["assign","distribute","apportion"]', '["withhold","retain","hoard"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('alter', '/ˈɔːltə/', 'verb', 'To change or cause to change in character or composition', '改变，修改', 3, 2700, '["kaoyan"]', 'alter（其他的），使变成另外的样子→改变', '[{"en":"The new policy will significantly alter the structure of public healthcare.","cn":"新政策将显著改变公共医疗体系的结构。"}]', '["modify","transform","revise"]', '["preserve","maintain","retain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ambiguous', '/æmˈbɪɡjuəs/', 'adjective', 'Open to more than one interpretation; not having one obvious meaning', '模棱两可的，含糊不清的', 4, 3400, '["kaoyan"]', 'ambi-（两者）+ ag（做）+ -uous（形容词后缀），可以做两种理解→模棱两可的', '[{"en":"The wording of the contract is deliberately ambiguous.","cn":"合同的措辞故意含糊不清。"}]', '["vague","equivocal","unclear"]', '["clear","explicit","unequivocal"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('amend', '/əˈmend/', 'verb', 'To make minor changes to a text or piece of legislation in order to improve it', '修正，修改（法律、文件等）', 4, 3600, '["kaoyan"]', 'a-（加强）+ mend（修复），修复不足之处→修正', '[{"en":"Parliament voted to amend the constitution to protect civil liberties.","cn":"议会投票修正了宪法以保护公民自由。"}]', '["revise","modify","rectify"]', '["worsen","corrupt","damage"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ample', '/ˈæmpl/', 'adjective', 'Enough or more than enough; plentiful and abundant', '充足的，丰富的', 3, 3700, '["kaoyan"]', 'ampl（大）→充足的、丰富的', '[{"en":"There is ample evidence to support the research hypothesis.","cn":"有充足的证据支持该研究假设。"}]', '["abundant","plentiful","sufficient"]', '["scarce","insufficient","inadequate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('analogy', '/əˈnælədʒi/', 'noun', 'A comparison between two things for the purpose of explanation or clarification', '类比，类推', 4, 3100, '["kaoyan"]', 'ana-（对应）+ log（比例）+ -y（名词后缀），按比例对应→类比', '[{"en":"He drew an analogy between the human brain and a computer.","cn":"他将人脑与计算机进行了类比。"}]', '["comparison","parallel","correlation"]', '["difference","contrast","disparity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('anonymous', '/əˈnɒnɪməs/', 'adjective', 'Not identified by name; of unknown identity', '匿名的，无名的', 3, 3300, '["kaoyan"]', 'an-（无）+ onym（名字）+ -ous（形容词后缀），没有名字的', '[{"en":"The donation was made by an anonymous benefactor.","cn":"这笔捐款由一位匿名捐助者提供。"}]', '["unnamed","unidentified","nameless"]', '["identified","named","known"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('anticipate', '/ænˈtɪsɪpeɪt/', 'verb', 'To regard as probable; to expect or predict; to act in advance of', '预期，期望；先于…行动', 3, 2800, '["kaoyan"]', 'anti-（先于）+ cip（拿取）+ -ate（动词后缀），提前拿取→预期', '[{"en":"Researchers anticipate that the results will be published next year.","cn":"研究人员预计结果将在明年发表。"}]', '["expect","foresee","predict"]', '["doubt","dread"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('apparatus', '/ˌæpəˈreɪtəs/', 'noun', 'The technical equipment or machinery needed for a particular activity or purpose', '器械，设备；机构，体制', 4, 4100, '["kaoyan"]', 'ap-（朝向）+ par（准备）+ -atus（名词后缀），为某事准备好的器具', '[{"en":"The laboratory is equipped with sophisticated scientific apparatus.","cn":"实验室配备了精密的科学仪器。"}]', '["equipment","device","mechanism"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('apparent', '/əˈpærənt/', 'adjective', 'Clearly visible or understood; seeming real or true but not necessarily so', '明显的；表面上的', 3, 2600, '["kaoyan"]', 'ap-（加强）+ par（出现）+ -ent（形容词后缀），出现在眼前→明显的', '[{"en":"The apparent contradiction in the theory has been resolved by recent research.","cn":"该理论中表面上的矛盾已被最新研究所解决。"}]', '["obvious","evident","seeming"]', '["hidden","obscure","unclear"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('appeal', '/əˈpiːl/', 'noun', 'A serious or urgent request; the quality of being attractive or interesting', '呼吁，请求；吸引力；上诉', 3, 2500, '["kaoyan"]', 'ap-（朝向）+ peal（呼唤），向某人呼唤→呼吁、请求', '[{"en":"The charity made an appeal for donations to support disaster relief.","cn":"该慈善机构发出呼吁，请求捐款支持救灾工作。"}]', '["request","plea","attraction"]', '["repulsion","disinterest"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('arbitrary', '/ˈɑːbɪtrəri/', 'adjective', 'Based on random choice or personal whim rather than any reason or system', '任意的，武断的；专断的', 4, 3200, '["kaoyan"]', 'arbitr（裁判）+ -ary（形容词后缀），凭裁判个人意愿的→武断的', '[{"en":"The selection criteria appeared arbitrary and lacked scientific basis.","cn":"选择标准显得很武断，缺乏科学依据。"}]', '["random","capricious","subjective"]', '["rational","systematic","logical"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('articulate', '/ɑːˈtɪkjəleɪt/', 'verb', 'To express an idea or feeling fluently and coherently', '清楚地表达；明确阐述', 4, 3400, '["kaoyan"]', 'articul（关节）+ -ate（动词后缀），像关节连接一样使语言连贯→清楚表达', '[{"en":"She was able to articulate her concerns clearly during the debate.","cn":"她能够在辩论中清楚地表达自己的关切。"}]', '["express","enunciate","convey"]', '["mumble","garble","murmur"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ascend', '/əˈsend/', 'verb', 'To go up or climb; to rise to a higher level or position', '上升，攀登；晋升', 3, 3600, '["kaoyan"]', 'a-（朝向）+ scend（爬），向上爬→上升', '[{"en":"The smoke ascended from the chimney into the cold winter sky.","cn":"烟雾从烟囱升起，飘入寒冷的冬日天空。"}]', '["rise","climb","mount"]', '["descend","fall","decline"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aspect', '/ˈæspekt/', 'noun', 'A particular part or feature of something; a specific way of viewing something', '方面，层面；外观', 3, 2500, '["kaoyan"]', 'a-（朝向）+ spect（看），看到的部分→方面', '[{"en":"The study examines various aspects of urban development policy.","cn":"该研究考察了城市发展政策的各个方面。"}]', '["facet","feature","dimension"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aspiration', '/ˌæspəˈreɪʃn/', 'noun', 'A strong desire or ambition to achieve something', '抱负，志向；渴望', 4, 3300, '["kaoyan"]', 'a-（朝向）+ spir（呼吸）+ -ation（名词后缀），朝着目标呼吸→抱负', '[{"en":"Her aspiration to become a renowned scientist drove her academic pursuits.","cn":"她成为著名科学家的抱负推动了她的学术追求。"}]', '["ambition","goal","yearning"]', '["apathy","indifference","resignation"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assert', '/əˈsɜːt/', 'verb', 'To state a fact or belief confidently and forcefully', '断言，声称；坚持（权利）', 3, 2900, '["kaoyan"]', 'as-（加强）+ sert（连接），牢牢地表达→断言', '[{"en":"The researcher asserted that the findings were statistically significant.","cn":"该研究者断言这些发现具有统计学意义。"}]', '["declare","maintain","affirm"]', '["deny","contradict","retract"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assess', '/əˈses/', 'verb', 'To evaluate or estimate the nature, ability, or quality of something', '评估，评定', 3, 2600, '["kaoyan"]', 'as-（朝向）+ sess（坐），坐下来评判→评估', '[{"en":"The committee will assess the impact of the proposed policy changes.","cn":"委员会将评估拟议政策变更的影响。"}]', '["evaluate","appraise","estimate"]', '["ignore","neglect","overlook"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('asset', '/ˈæset/', 'noun', 'A useful or valuable thing, person, or quality; property owned by a person or company', '资产，财产；有价值的人或物', 3, 2700, '["kaoyan"]', 'as-（朝向）+ set（足够的），足够的东西→资产', '[{"en":"Intellectual property is a critical asset for technology companies.","cn":"知识产权是科技公司的关键资产。"}]', '["resource","possession","advantage"]', '["liability","burden","drawback"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assimilate', '/əˈsɪmɪleɪt/', 'verb', 'To take in and understand fully; to absorb and integrate into a wider group', '吸收，消化；同化', 4, 3900, '["kaoyan"]', 'as-（加强）+ simil（相似）+ -ate（动词后缀），使变得相似→同化', '[{"en":"Immigrants are often expected to assimilate into the dominant culture.","cn":"移民通常被期望融入主流文化。"}]', '["absorb","integrate","incorporate"]', '["reject","segregate","alienate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assume', '/əˈsjuːm/', 'verb', 'To suppose to be the case without proof; to take on responsibility or a role', '假设，假定；承担', 3, 2500, '["kaoyan"]', 'as-（朝向）+ sum（拿取），拿过来→承担；未经证实地接受→假设', '[{"en":"It is reasonable to assume that economic growth will continue steadily.","cn":"有理由假设经济将持续稳定增长。"}]', '["presume","suppose","undertake"]', '["prove","verify","relinquish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assurance', '/əˈʃʊərəns/', 'noun', 'A positive declaration intended to give confidence; a promise or guarantee', '保证，担保；信心，确信', 3, 3500, '["kaoyan"]', 'as-（加强）+ sur（确定）+ -ance（名词后缀），使人确定的东西→保证', '[{"en":"The manager gave assurance that no jobs would be lost in the restructuring.","cn":"经理保证在重组过程中不会有人失业。"}]', '["guarantee","pledge","confidence"]', '["doubt","uncertainty","apprehension"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('atmosphere', '/ˈætməsfɪə/', 'noun', 'The envelope of gases surrounding a planet; the pervading tone or mood of a place', '大气层；气氛，氛围', 3, 2600, '["kaoyan"]', 'atmo-（蒸汽）+ sphere（球体），围绕地球的蒸汽层→大气层', '[{"en":"The atmosphere in the conference room was tense during negotiations.","cn":"谈判期间会议室里的气氛很紧张。"}]', '["ambiance","mood","climate"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('attain', '/əˈteɪn/', 'verb', 'To succeed in achieving something after a lot of effort', '达到，获得；实现', 3, 2900, '["kaoyan"]', 'at-（加强）+ tain（握住），通过努力握住→达到', '[{"en":"She attained the highest level of academic achievement in her field.","cn":"她在自己的领域达到了学术成就的最高水平。"}]', '["achieve","accomplish","reach"]', '["fail","lose","miss"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('attribute', '/əˈtrɪbjuːt/', 'verb', 'To regard something as being caused by or belonging to someone or something', '把…归因于；属性，特征', 3, 2700, '["kaoyan"]', 'at-（朝向）+ tribut（给予），给予某原因→归因于', '[{"en":"Researchers attribute the decline in biodiversity to habitat destruction.","cn":"研究人员将生物多样性的下降归因于栖息地的破坏。"}]', '["ascribe","assign","impute"]', '["detach","dissociate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('authorize', '/ˈɔːθəraɪz/', 'verb', 'To give official permission for or approval to', '授权，批准', 3, 3200, '["kaoyan"]', 'author（作者、权威）+ -ize（动词后缀），赋予权威→授权', '[{"en":"Only the board of directors can authorize such a significant expenditure.","cn":"只有董事会才能批准如此重大的开支。"}]', '["permit","sanction","approve"]', '["forbid","prohibit","deny"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('autonomous', '/ɔːˈtɒnəməs/', 'adjective', 'Having the freedom to act independently or to govern oneself', '自治的，自主的；独立自主的', 4, 3600, '["kaoyan"]', 'auto-（自己）+ nom（法则）+ -ous（形容词后缀），自己制定法则的→自治的', '[{"en":"The region was granted autonomous status by the central government.","cn":"该地区被中央政府授予自治地位。"}]', '["independent","self-governing","sovereign"]', '["dependent","subordinate","controlled"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('available', '/əˈveɪləbl/', 'adjective', 'Able to be used or obtained; free to do something', '可获得的，可用的；有空的', 3, 2500, '["kaoyan"]', 'a-（加强）+ vail（有价值），有价值的→可获得的', '[{"en":"Scholarships are available for outstanding international students.","cn":"优秀国际学生可获得奖学金。"}]', '["accessible","obtainable","handy"]', '["unavailable","inaccessible","unobtainable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('avenue', '/ˈævənjuː/', 'noun', 'A broad road in a city; a way of approaching a problem or making progress', '大街；途径，渠道', 3, 3400, '["kaoyan"]', 'a-（朝向）+ ven（来）+ -ue（名词后缀），通往某处的路→大街、途径', '[{"en":"Education provides an important avenue for social mobility.","cn":"教育为社会流动提供了一条重要途径。"}]', '["pathway","channel","boulevard"]', '["dead end","obstacle"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adverse', '/ˈædvɜːs/', 'adjective', 'Preventing success or development; harmful or unfavorable', '不利的，有害的；相反的', 4, 3300, '["kaoyan"]', 'ad-（朝向）+ vers（转），转向对面的→不利的', '[{"en":"Adverse weather conditions delayed the construction project significantly.","cn":"不利的天气条件严重延误了建设项目。"}]', '["unfavorable","harmful","detrimental"]', '["favorable","beneficial","advantageous"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ballistic', '/bəˈlɪstɪk/', 'adjective', 'Relating to projectiles or their flight; moving under the force of gravity only', '弹道的；投射的', 5, 5800, '["kaoyan"]', 'ball（球）+ -istic（形容词后缀），与抛射物有关的', '[{"en":"The military conducted ballistic missile tests in the remote region.","cn":"军方在该偏远地区进行了弹道导弹试验。"}]', '["projectile","trajectory"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bankrupt', '/ˈbæŋkrʌpt/', 'adjective', 'Declared in law unable to pay outstanding debts; completely lacking in a particular quality', '破产的；完全缺乏的', 3, 3500, '["kaoyan"]', 'bank（长凳、钱桌）+ rupt（破裂），钱桌被砸碎→破产', '[{"en":"The company went bankrupt after failing to secure additional investment.","cn":"该公司在未能获得追加投资后破产了。"}]', '["insolvent","ruined","penniless"]', '["solvent","wealthy","prosperous"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('barrier', '/ˈbæriə/', 'noun', 'A fence or obstacle that prevents movement or access; an obstacle to progress', '障碍，屏障；隔阂', 3, 2700, '["kaoyan"]', 'bar（栏杆）+ -ier（名词后缀），栏杆状物→障碍', '[{"en":"Language barriers can hinder effective communication in international business.","cn":"语言障碍会妨碍国际商务中的有效沟通。"}]', '["obstacle","hindrance","impediment"]', '["bridge","opening","access"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('behalf', '/bɪˈhɑːf/', 'noun', 'In the interests of a person, group, or principle; as a representative of', '代表；利益，方面', 3, 2900, '["kaoyan"]', 'be-（在旁边）+ half（一半），站在某人一边→代表某人', '[{"en":"The lawyer spoke on behalf of her client during the hearing.","cn":"律师在听证会上代表她的当事人发言。"}]', '["interest","benefit","representation"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('benchmark', '/ˈbentʃmɑːk/', 'noun', 'A standard or point of reference against which things may be compared', '基准，标杆；参照标准', 4, 4200, '["kaoyan"]', 'bench（长凳）+ mark（标记），测量基准点→基准', '[{"en":"The study established a benchmark for measuring educational outcomes.","cn":"该研究建立了衡量教育成果的基准。"}]', '["standard","criterion","reference"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('benevolent', '/bɪˈnevələnt/', 'adjective', 'Well-meaning and kindly; charitable and generous', '仁慈的，慈善的；好意的', 4, 4000, '["kaoyan"]', 'bene-（好）+ vol（意愿）+ -ent（形容词后缀），好意的→仁慈的', '[{"en":"The benevolent donor funded scholarships for underprivileged students.","cn":"这位慈善的捐助者资助了贫困学生的奖学金。"}]', '["kind","charitable","generous"]', '["malevolent","cruel","selfish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bias', '/ˈbaɪəs/', 'noun', 'An inclination or prejudice for or against something in a way considered to be unfair', '偏见，偏差；倾向', 3, 2800, '["kaoyan"]', '源自法语 biais（斜线），偏离正中→偏见', '[{"en":"The study revealed significant bias in the hiring process against minority candidates.","cn":"该研究揭示了招聘过程中对少数族裔候选人的严重偏见。"}]', '["prejudice","partiality","inclination"]', '["impartiality","fairness","neutrality"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bilateral', '/baɪˈlætərəl/', 'adjective', 'Having or relating to two sides; affecting both sides', '双边的，双方的', 4, 3800, '["kaoyan"]', 'bi-（两个）+ later（边）+ -al（形容词后缀），两边的→双边的', '[{"en":"The two countries signed a bilateral trade agreement last month.","cn":"两国上月签署了双边贸易协定。"}]', '["two-sided","mutual","reciprocal"]', '["unilateral","one-sided"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bind', '/baɪnd/', 'verb', 'To tie or fasten tightly; to impose a legal or moral obligation', '捆绑，束缚；约束', 3, 3100, '["kaoyan"]', '古英语 bindan，捆绑、约束', '[{"en":"International treaties bind nations to uphold human rights standards.","cn":"国际条约约束各国维护人权标准。"}]', '["tie","fasten","oblige"]', '["unbind","release","liberate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('biography', '/baɪˈɒɡrəfi/', 'noun', 'An account of someone''s life written by someone else', '传记', 3, 3200, '["kaoyan"]', 'bio-（生命）+ graph（写）+ -y（名词后缀），书写一个人的生命→传记', '[{"en":"The biography of the scientist revealed her struggles and achievements.","cn":"这位科学家的传记揭示了她的奋斗与成就。"}]', '["memoir","chronicle","life story"]', '["autobiography","fiction"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('blueprint', '/ˈbluːprɪnt/', 'noun', 'A design or technical drawing; a detailed plan of action', '蓝图；详细计划', 3, 3700, '["kaoyan"]', 'blue（蓝色）+ print（印刷），蓝色印刷图→蓝图', '[{"en":"The government unveiled a blueprint for sustainable urban development.","cn":"政府公布了可持续城市发展的蓝图。"}]', '["plan","scheme","design"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('breed', '/briːd/', 'verb', 'To cause to reproduce; to produce or give rise to; a particular type of animal or person', '繁殖；培育；品种', 3, 3000, '["kaoyan"]', '古英语 bredan，养育、繁殖', '[{"en":"Poverty and unemployment can breed social instability.","cn":"贫困和失业可能滋生社会不稳定。"}]', '["reproduce","cultivate","generate"]', '["exterminate","suppress"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bulk', '/bʌlk/', 'noun', 'The mass or magnitude of something; the main or largest part', '大量，大批；体积；主体部分', 3, 2900, '["kaoyan"]', '源自古诺尔斯语 bulki，一堆货物→大量', '[{"en":"The bulk of the research funding comes from government grants.","cn":"大部分研究经费来自政府拨款。"}]', '["majority","mass","volume"]', '["minority","fraction"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bureaucratic', '/ˌbjʊərəˈkrætɪk/', 'adjective', 'Relating to overly complicated administrative procedures and regulations', '官僚主义的；繁文缛节的', 4, 3900, '["kaoyan"]', 'bureau（办公室）+ crat（统治者）+ -ic（形容词后缀），办公室统治的→官僚的', '[{"en":"Bureaucratic inefficiency often delays the implementation of public policies.","cn":"官僚主义的低效率常常延误公共政策的实施。"}]', '["administrative","official","red-tape"]', '["efficient","streamlined"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bypass', '/ˈbaɪpɑːs/', 'verb', 'To go past or around; to avoid or circumvent a procedure or system', '绕过，避开；旁路', 3, 3400, '["kaoyan"]', 'by-（旁边）+ pass（通过），从旁边通过→绕过', '[{"en":"The new highway will bypass the city center to reduce traffic congestion.","cn":"新高速公路将绕过市中心以减少交通拥堵。"}]', '["circumvent","avoid","skirt"]', '["confront","face","encounter"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cabinet', '/ˈkæbɪnɪt/', 'noun', 'A cupboard with shelves or drawers; a group of senior government ministers', '橱柜；内阁', 3, 3100, '["kaoyan"]', 'cabin（小屋）+ -et（小的），小密室→橱柜；引申为内阁（小会议室）', '[{"en":"The prime minister reshuffled the cabinet after the general election.","cn":"首相在大选后改组了内阁。"}]', '["cupboard","ministry","council"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('caliber', '/ˈkælɪbə/', 'noun', 'The quality of someone''s character or the level of ability; the internal diameter of a gun barrel', '才干，能力； caliber', 4, 4100, '["kaoyan"]', '源自阿拉伯语 qalib（模具），衡量质量的模具→才干', '[{"en":"The university is known for attracting faculty of the highest caliber.","cn":"该大学以吸引最高水平的教职员工而闻名。"}]', '["quality","ability","standard"]', '["incompetence","mediocrity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('candidate', '/ˈkændɪdət/', 'noun', 'A person who applies for a job or is nominated for election; a person taking an exam', '候选人；应聘者；考生', 3, 2600, '["kaoyan"]', 'candid（白色的）+ -ate（名词后缀），穿白袍的罗马竞选者→候选人', '[{"en":"Over 500 candidates applied for the research position.","cn":"超过500名候选人申请了该研究职位。"}]', '["applicant","nominee","contender"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capture', '/ˈkæptʃə/', 'verb', 'To take into possession by force or skill; to record or express accurately', '捕获，俘获；夺取；记录', 3, 2700, '["kaoyan"]', 'capt（抓）+ -ure（名词/动词后缀），抓住→捕获', '[{"en":"The documentary captured the daily lives of people in rural communities.","cn":"这部纪录片记录了农村社区人们的日常生活。"}]', '["seize","apprehend","record"]', '["release","liberate","free"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cardinal', '/ˈkɑːdɪnl/', 'adjective', 'Of the greatest importance; fundamental; a senior clergyman in the Roman Catholic Church', '最重要的，基本的；红衣主教', 4, 3800, '["kaoyan"]', 'cardin（铰链）+ -al（形容词后缀），像铰链一样关键的→最重要的', '[{"en":"Freedom of speech is a cardinal principle of democratic societies.","cn":"言论自由是民主社会的基本原则。"}]', '["fundamental","essential","paramount"]', '["trivial","minor","insignificant"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cascade', '/kæˈskeɪd/', 'noun', 'A small waterfall; a large number or amount of something occurring at the same time', '瀑布；大量倾泻；级联', 4, 4300, '["kaoyan"]', '源自拉丁语 cascata（瀑布），cas（落下）+ -ade（名词后缀）', '[{"en":"The financial crisis triggered a cascade of bank failures across the country.","cn":"金融危机引发了全国银行倒闭的连锁反应。"}]', '["waterfall","torrent","flood"]', '["trickle","drought"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('catastrophic', '/ˌkætəˈstrɒfɪk/', 'adjective', 'Involving or causing sudden great damage or suffering; extremely unfortunate', '灾难性的，极糟糕的', 4, 3500, '["kaoyan"]', 'cata-（向下）+ stroph（转）+ -ic（形容词后缀），急转直下的→灾难性的', '[{"en":"Climate change could have catastrophic consequences for coastal populations.","cn":"气候变化可能对沿海居民造成灾难性后果。"}]', '["disastrous","devastating","calamitous"]', '["fortunate","beneficial","auspicious"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('causal', '/ˈkɔːzl/', 'adjective', 'Relating to or acting as a cause; expressing a cause-and-effect relationship', '因果关系的；原因的', 4, 3600, '["kaoyan"]', 'caus（原因）+ -al（形容词后缀），关于原因的→因果的', '[{"en":"The study established a causal link between smoking and lung cancer.","cn":"该研究确立了吸烟与肺癌之间的因果关系。"}]', '["causative","consequential","related"]', '["unrelated","random","coincidental"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('census', '/ˈsensəs/', 'noun', 'An official count or survey of a population, typically recording various details', '人口普查', 3, 3700, '["kaoyan"]', '源自拉丁语 censere（评估），古罗马的人口评估→人口普查', '[{"en":"The national census is conducted every ten years to track demographic changes.","cn":"全国人口普查每十年进行一次，以追踪人口变化。"}]', '["survey","count","enumeration"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ceramic', '/səˈræmɪk/', 'adjective', 'Made of clay and hardened by heat; relating to the making of such objects', '陶瓷的；制陶的', 3, 4200, '["kaoyan"]', '源自希腊语 keramikos（陶工的），keramos（陶土）', '[{"en":"The museum houses an impressive collection of ancient ceramic artifacts.","cn":"该博物馆收藏了令人印象深刻的古代陶瓷文物。"}]', '["pottery","porcelain","earthenware"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('certify', '/ˈsɜːtɪfaɪ/', 'verb', 'To attest or confirm in a formal statement; to officially recognize someone or something as meeting certain standards', '证明，证实；颁发证书', 4, 3400, '["kaoyan"]', 'cert（确定的）+ -ify（使），使确定→证明', '[{"en":"The laboratory was certified to meet international quality standards.","cn":"该实验室经认证符合国际质量标准。"}]', '["confirm","verify","attest"]', '["deny","contradict","invalidate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('chronic', '/ˈkrɒnɪk/', 'adjective', 'Persisting for a long time or constantly recurring; habitual', '慢性的；长期的；习惯性的', 3, 3100, '["kaoyan"]', 'chron（时间）+ -ic（形容词后缀），持续很长时间的→慢性的', '[{"en":"Chronic unemployment remains one of the most pressing social issues.","cn":"长期失业仍然是最紧迫的社会问题之一。"}]', '["persistent","enduring","long-term"]', '["acute","temporary","brief"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('circumstance', '/ˈsɜːkəmstəns/', 'noun', 'A fact or condition connected with or relevant to an event or action', '环境，情况；条件', 3, 2700, '["kaoyan"]', 'circum-（围绕）+ st（站立）+ -ance（名词后缀），围绕在周围的事物→环境', '[{"en":"Under no circumstances should confidential information be shared with outsiders.","cn":"在任何情况下都不应将机密信息与外部分享。"}]', '["condition","situation","context"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cite', '/saɪt/', 'verb', 'To quote as evidence or justification; to refer to as an example', '引用，引证；传唤', 3, 2800, '["kaoyan"]', '源自拉丁语 citare（召唤、引用）', '[{"en":"The professor cited several landmark cases to illustrate the legal principle.","cn":"教授引用了几个具有里程碑意义的案例来说明这一法律原则。"}]', '["quote","reference","mention"]', '["ignore","omit","disregard"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('civic', '/ˈsɪvɪk/', 'adjective', 'Relating to a city or town and its citizens; relating to the duties of a citizen', '城市的；公民的，市民的', 3, 3500, '["kaoyan"]', 'civ（公民）+ -ic（形容词后缀），公民的→市民的', '[{"en":"Civic responsibility includes voting in elections and serving on juries.","cn":"公民责任包括参加选举投票和担任陪审员。"}]', '["municipal","public","civil"]', '["rural","private"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('clarify', '/ˈklærəfaɪ/', 'verb', 'To make a statement or situation less confused and more clearly comprehensible', '澄清，阐明；使明晰', 3, 2800, '["kaoyan"]', 'clar（清楚的）+ -ify（使），使清楚→澄清', '[{"en":"Could you clarify what you meant by that statement in your report?","cn":"你能否澄清你在报告中那段话的意思？"}]', '["elucidate","explain","illuminate"]', '["confuse","obscure","muddle"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('classify', '/ˈklæsɪfaɪ/', 'verb', 'To arrange in classes or categories according to shared qualities or characteristics', '分类，归类；列为机密', 3, 2900, '["kaoyan"]', 'class（类别）+ -ify（使），使归入类别→分类', '[{"en":"Biologists classify organisms based on their genetic similarities.","cn":"生物学家根据遗传相似性对生物进行分类。"}]', '["categorize","sort","group"]', '["mix","confuse","disorganize"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('clause', '/klɔːz/', 'noun', 'A unit of grammatical organization; a particular stipulation in a legal document', '条款；从句，分句', 4, 3300, '["kaoyan"]', '源自拉丁语 clausa（关闭），一个完整关闭的语法单元→从句、条款', '[{"en":"The contract includes a clause that prohibits disclosure of trade secrets.","cn":"合同中有一条禁止泄露商业秘密的条款。"}]', '["provision","stipulation","section"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('coherent', '/kəʊˈhɪərənt/', 'adjective', 'Logical and consistent; able to speak clearly and in an organized way', '连贯的，一致的；条理清楚的', 4, 3200, '["kaoyan"]', 'co-（共同）+ her（粘附）+ -ent（形容词后缀），粘在一起→连贯的', '[{"en":"The research paper presents a coherent argument supported by empirical data.","cn":"该研究论文提出了一个由实证数据支持的连贯论证。"}]', '["logical","consistent","organized"]', '["incoherent","confused","disjointed"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('coincide', '/ˌkəʊɪnˈsaɪd/', 'verb', 'To occur at or during the same time; to correspond in nature or character', '同时发生；一致，相符', 4, 3600, '["kaoyan"]', 'co-（共同）+ in-（在…上）+ cid（落下），同时落到一处→同时发生', '[{"en":"The dates of the two conferences happen to coincide this year.","cn":"今年两个会议的日期恰好同时。"}]', '["concur","correspond","overlap"]', '["differ","diverge","conflict"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('collaborate', '/kəˈlæbəreɪt/', 'verb', 'To work jointly with others on an activity or project', '合作，协作；勾结', 3, 2900, '["kaoyan"]', 'col-（共同）+ labor（劳动）+ -ate（动词后缀），共同劳动→合作', '[{"en":"Scientists from different countries collaborated on the climate research project.","cn":"来自不同国家的科学家在气候研究项目上进行了合作。"}]', '["cooperate","partner","team up"]', '["compete","oppose","conflict"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('collapse', '/kəˈlæps/', 'verb', 'To fall down or give way suddenly; to fail suddenly and completely', '倒塌，崩溃；瓦解', 3, 2800, '["kaoyan"]', 'col-（共同）+ laps（滑落），一起滑倒→倒塌', '[{"en":"The housing market collapsed, leading to a severe economic recession.","cn":"房地产市场崩溃，导致了严重的经济衰退。"}]', '["crumble","disintegrate","implode"]', '["expand","recover","flourish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('colonial', '/kəˈləʊniəl/', 'adjective', 'Relating to or characteristic of a colony or colonies; possessing colonies', '殖民的，殖民地的', 3, 3400, '["kaoyan"]', 'colonia（农场、殖民地）+ -al（形容词后缀），殖民地的', '[{"en":"Many colonial-era buildings have been preserved as historical landmarks.","cn":"许多殖民时代的建筑被保存为历史地标。"}]', '["imperial","settler","territorial"]', '["independent","sovereign","autonomous"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commemorate', '/kəˈmeməreɪt/', 'verb', 'To recall and show respect for someone or something in a ceremony', '纪念，庆祝；缅怀', 4, 4000, '["kaoyan"]', 'com-（加强）+ memor（记忆）+ -ate（动词后缀），加强记忆→纪念', '[{"en":"A monument was erected to commemorate the soldiers who died in the war.","cn":"建立了一座纪念碑来纪念在战争中牺牲的士兵。"}]', '["honor","memorialize","celebrate"]', '["forget","disregard","ignore"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commence', '/kəˈmens/', 'verb', 'To begin or start; to initiate a process or action', '开始，着手', 4, 3500, '["kaoyan"]', 'com-（加强）+ mence（开始），正式开始', '[{"en":"The ceremony will commence at noon in the university auditorium.","cn":"典礼将于中午在大学礼堂开始。"}]', '["begin","initiate","inaugurate"]', '["conclude","terminate","end"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commend', '/kəˈmend/', 'verb', 'To praise formally or officially; to present as suitable or good', '表扬，称赞；推荐；委托', 4, 3700, '["kaoyan"]', 'com-（加强）+ mend（委托），正式委托→称赞、推荐', '[{"en":"The board commended the team for their outstanding contribution to the project.","cn":"董事会表扬了该团队对项目的杰出贡献。"}]', '["praise","applaud","compliment"]', '["criticize","condemn","blame"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commentary', '/ˈkɒməntri/', 'noun', 'An expression of opinions or offering of explanations about an event or situation', '评论，解说；注释', 3, 3300, '["kaoyan"]', 'comment（评论）+ -ary（名词后缀），评论的集合→评论集', '[{"en":"The news program provides insightful commentary on current political affairs.","cn":"该新闻节目对当前政治事务提供了深刻的评论。"}]', '["analysis","interpretation","exposition"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commercial', '/kəˈmɜːʃl/', 'adjective', 'Relating to or engaged in commerce; intended to make a profit', '商业的，商务的；营利的', 3, 2600, '["kaoyan"]', 'com-（共同）+ merc（贸易）+ -ial（形容词后缀），共同贸易的→商业的', '[{"en":"The commercial success of the product exceeded all expectations.","cn":"该产品的商业成功超出了所有预期。"}]', '["business","trade","profitable"]', '["noncommercial","nonprofit","charitable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commodity', '/kəˈmɒdəti/', 'noun', 'A raw material or primary agricultural product that can be bought and sold', '商品，货物；日用品', 4, 3400, '["kaoyan"]', 'commod（方便）+ -ity（名词后缀），方便交换的物品→商品', '[{"en":"Oil and gold are among the most traded commodities in the global market.","cn":"石油和黄金是全球市场上交易量最大的商品。"}]', '["goods","product","merchandise"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commute', '/kəˈmjuːt/', 'verb', 'To travel some distance between one''s home and place of work on a regular basis; to reduce a judicial sentence', '通勤；减刑', 3, 3200, '["kaoyan"]', 'com-（共同）+ mut（改变），改变位置→通勤；改变判决→减刑', '[{"en":"Many employees commute over an hour each way to reach the office.","cn":"许多员工单程通勤超过一小时才能到达办公室。"}]', '["travel","shuttle","reduce"]', '["stay","remain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compact', '/kəmˈpækt/', 'adjective', 'Closely and neatly packed together; dense and small in size', '紧凑的，紧密的；小巧的', 3, 3400, '["kaoyan"]', 'com-（共同）+ pact（压紧），压在一起→紧凑的', '[{"en":"The compact design of the device makes it ideal for portable use.","cn":"该设备的紧凑设计使其非常适合便携使用。"}]', '["dense","concentrated","condensed"]', '["loose","scattered","sprawling"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('comparable', '/ˈkɒmpərəbl/', 'adjective', 'Able to be compared; similar in quality, quantity, or degree', '可比较的；类似的', 3, 3000, '["kaoyan"]', 'com-（共同）+ par（平等）+ -able（能够），能够平等对待的→可比较的', '[{"en":"The two studies used comparable methodologies and arrived at similar conclusions.","cn":"两项研究使用了可比较的方法，得出了类似的结论。"}]', '["similar","analogous","equivalent"]', '["different","incomparable","dissimilar"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compatible', '/kəmˈpætəbl/', 'adjective', 'Able to exist or occur together without conflict; consistent', '兼容的；相容的，协调的', 4, 3300, '["kaoyan"]', 'com-（共同）+ pat（感受）+ -ible（能够），能够共同感受的→相容的', '[{"en":"The new software is compatible with most existing operating systems.","cn":"新软件与大多数现有操作系统兼容。"}]', '["consistent","harmonious","congruous"]', '["incompatible","conflicting","discordant"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compel', '/kəmˈpel/', 'verb', 'To force or oblige someone to do something; to bring about by the use of force or pressure', '强迫，迫使', 4, 3200, '["kaoyan"]', 'com-（加强）+ pel（推动），强烈推动→强迫', '[{"en":"The evidence compelled the jury to reach a guilty verdict.","cn":"证据迫使陪审团做出了有罪裁决。"}]', '["force","oblige","coerce"]', '["persuade","encourage","allow"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compensate', '/ˈkɒmpenseɪt/', 'verb', 'To give something in recognition of loss, suffering, or injury; to make up for', '补偿，赔偿；弥补', 3, 2900, '["kaoyan"]', 'com-（共同）+ pens（称重）+ -ate（动词后缀），等量称出→补偿', '[{"en":"The company compensated workers for the injuries sustained on the job.","cn":"公司对工人在工作中受到的伤害进行了赔偿。"}]', '["reimburse","remunerate","offset"]', '["penalize","punish","fine"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('competent', '/ˈkɒmpɪtənt/', 'adjective', 'Having the necessary ability, knowledge, or skill to do something successfully', '有能力的，胜任的', 3, 3000, '["kaoyan"]', 'com-（共同）+ pet（追求）+ -ent（形容词后缀），有能力追求的→胜任的', '[{"en":"A competent manager should be able to handle both technical and interpersonal challenges.","cn":"一位称职的经理应该能够处理技术和人际关系方面的挑战。"}]', '["capable","proficient","qualified"]', '["incompetent","unqualified","inept"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compile', '/kəmˈpaɪl/', 'verb', 'To produce by assembling information collected from various sources', '编译；汇编，收集', 3, 3100, '["kaoyan"]', 'com-（共同）+ pile（堆积），堆积在一起→汇编', '[{"en":"The researcher compiled data from multiple surveys for the meta-analysis.","cn":"研究人员汇编了来自多个调查的数据以进行元分析。"}]', '["assemble","collect","gather"]', '["scatter","disperse","distribute"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('complement', '/ˈkɒmplɪment/', 'noun', 'A thing that completes or brings to perfection; to add to something in a way that enhances it', '补充，补足；使完美', 4, 3500, '["kaoyan"]', 'com-（共同）+ ple（充满）+ -ment（名词后缀），使充满→补充', '[{"en":"The two approaches complement each other and produce better results together.","cn":"两种方法相互补充，结合使用能产生更好的效果。"}]', '["supplement","addition","enhancement"]', '["detract","diminish","undermine"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('complexity', '/kəmˈpleksəti/', 'noun', 'The state of being complicated or intricate; a thing with many interconnected parts', '复杂性，复杂的事物', 3, 2800, '["kaoyan"]', 'com-（共同）+ plex（编织）+ -ity（名词后缀），编织在一起→复杂性', '[{"en":"The complexity of the tax system makes compliance difficult for small businesses.","cn":"税制的复杂性使小企业难以遵守规定。"}]', '["intricacy","complication","sophistication"]', '["simplicity","straightforwardness","clarity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compliance', '/kəmˈplaɪəns/', 'noun', 'The action of complying with a wish, command, or rule; the state of meeting rules or standards', '遵守，服从；合规', 4, 3600, '["kaoyan"]', 'com-（共同）+ pli（弯曲、顺从）+ -ance（名词后缀），顺从→遵守', '[{"en":"Strict compliance with safety regulations is mandatory in all manufacturing plants.","cn":"所有制造工厂必须严格遵守安全法规。"}]', '["conformity","obedience","adherence"]', '["noncompliance","defiance","violation"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('component', '/kəmˈpəʊnənt/', 'noun', 'A part or element of a larger whole; a constituent', '组成部分，成分；零件', 3, 2700, '["kaoyan"]', 'com-（共同）+ pon（放置）+ -ent（名词后缀），放在一起的部分→组成部分', '[{"en":"Education is a key component of the national development strategy.","cn":"教育是国家发展战略的关键组成部分。"}]', '["element","part","constituent"]', '["whole","totality"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compose', '/kəmˈpəʊz/', 'verb', 'To create or write a work of art, music, or literature; to make up or constitute', '组成，构成；创作；使镇定', 3, 2800, '["kaoyan"]', 'com-（共同）+ pos（放置），放到一起→组成', '[{"en":"The committee is composed of representatives from all member nations.","cn":"委员会由所有成员国的代表组成。"}]', '["constitute","create","formulate"]', '["decompose","disassemble","destroy"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('comprehensive', '/ˌkɒmprɪˈhensɪv/', 'adjective', 'Including all or nearly all elements or aspects of something; complete and thorough', '全面的，综合的；综合性的', 3, 2700, '["kaoyan"]', 'com-（共同）+ prehens（抓住）+ -ive（形容词后缀），全部抓住的→全面的', '[{"en":"The report provides a comprehensive analysis of the housing market trends.","cn":"该报告提供了对住房市场趋势的全面分析。"}]', '["thorough","complete","extensive"]', '["partial","limited","selective"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('comprise', '/kəmˈpraɪz/', 'verb', 'To consist of; to be made up of; to include or contain', '包含，包括；由…组成', 4, 3400, '["kaoyan"]', 'com-（共同）+ pris（抓住），抓在一起→包含', '[{"en":"The university comprises twelve faculties and over fifty research centers.","cn":"该大学由十二个学院和五十多个研究中心组成。"}]', '["include","contain","consist of"]', '["exclude","omit"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compulsory', '/kəmˈpʌlsəri/', 'adjective', 'Required by law or a rule; obligatory', '强制的，义务的；必修的', 3, 3200, '["kaoyan"]', 'com-（加强）+ puls（推动）+ -ory（形容词后缀），被强制推动的→强制的', '[{"en":"Compulsory education is required for all children between the ages of six and fifteen.","cn":"所有六至十五岁的儿童都必须接受义务教育。"}]', '["mandatory","obligatory","required"]', '["optional","voluntary","elective"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compute', '/kəmˈpjuːt/', 'verb', 'To calculate or reckon by a mathematical process; to determine using a computer', '计算，估算', 3, 2900, '["kaoyan"]', 'com-（共同）+ put（思考、计算），合在一起算→计算', '[{"en":"The system can compute millions of calculations per second.","cn":"该系统每秒可以进行数百万次计算。"}]', '["calculate","reckon","figure"]', '["estimate","guess"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('conceal', '/kənˈsiːl/', 'verb', 'To keep something secret or hidden; to prevent from being seen', '隐藏，隐瞒；掩盖', 3, 3100, '["kaoyan"]', 'con-（加强）+ ceal（隐藏），完全隐藏', '[{"en":"The company attempted to conceal the extent of its financial losses.","cn":"该公司试图隐瞒其财务损失的程度。"}]', '["hide","obscure","mask"]', '["reveal","disclose","expose"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('concede', '/kənˈsiːd/', 'verb', 'To admit that something is true after first resisting; to surrender or yield', '承认（失败、错误）；让步', 4, 3500, '["kaoyan"]', 'con-（共同）+ ced（走），走到一起→让步', '[{"en":"After reviewing the evidence, the defendant conceded the charges were valid.","cn":"审查证据后，被告承认指控是有效的。"}]', '["admit","acknowledge","yield"]', '["deny","resist","contest"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('conceive', '/kənˈsiːv/', 'verb', 'To form or devise a plan or idea in the mind; to become pregnant', '构想，设想；怀孕', 4, 3400, '["kaoyan"]', 'con-（共同）+ ceive（拿取），在头脑中拿取→构想', '[{"en":"It is difficult to conceive of a society without modern technology.","cn":"很难想象一个没有现代技术的社会。"}]', '["imagine","envision","devise"]', '["misunderstand","misconceive"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accommodate', '/əˈkɒmədeɪt/', 'verb', 'To provide lodging or sufficient space for; to adapt or adjust to something', '容纳；提供住宿；适应；迎合', 4, 4200, '["ielts"]', '源自拉丁语 accommodare，ad-（向）+ commodare（使适合），commodus 意为"合适的"', '[{"en":"The hotel can accommodate up to 500 guests during peak season.","cn":"这家酒店在旺季最多可容纳500位客人。"},{"en":"We need to accommodate different learning styles in the classroom.","cn":"我们需要在课堂上适应不同的学习风格。"}]', '["lodge","house","adapt","adjust"]', '["reject","exclude","inconvenience"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('acknowledge', '/əkˈnɒlɪdʒ/', 'verb', 'To accept or admit the existence or truth of something; to recognize the importance of', '承认；认可；致谢', 4, 3800, '["ielts"]', '源自中世纪英语 aknowlechen，acknowledge 的早期形式，与 knowledge（知识）相关', '[{"en":"The government has acknowledged the need for educational reform.","cn":"政府已承认教育改革的必要性。"},{"en":"She acknowledged her mistake and apologised to the team.","cn":"她承认了自己的错误并向团队道歉。"}]', '["admit","recognise","concede","accept"]', '["deny","ignore","disregard"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adjacent', '/əˈdʒeɪsənt/', 'adjective', 'Close to or next to something; bordering on', '邻近的；毗连的', 4, 5100, '["ielts"]', '源自拉丁语 adjacens，ad-（靠近）+ jacere（躺、位于），字面意为"躺在旁边"', '[{"en":"The university is adjacent to the city centre, making it easily accessible.","cn":"该大学毗邻市中心，交通十分便利。"},{"en":"Rooms adjacent to the hallway were most affected by the noise.","cn":"靠近走廊的房间受噪音影响最大。"}]', '["neighbouring","adjoining","contiguous","nearby"]', '["distant","remote","faraway"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('advocate', '/ˈædvəkeɪt/', 'verb', 'To publicly recommend or support a particular cause or policy', '提倡；拥护；支持', 4, 4000, '["ielts"]', '源自拉丁语 advocare，ad-（向）+ vocare（呼喊），原指"召唤来提供帮助"，后引申为"公开支持"', '[{"en":"Many environmental groups advocate stricter regulations on carbon emissions.","cn":"许多环保组织提倡对碳排放实施更严格的监管。"},{"en":"She advocates for equal access to healthcare in rural areas.","cn":"她倡导农村地区平等获得医疗服务。"}]', '["support","champion","promote","endorse"]', '["oppose","condemn","criticise"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('alleviate', '/əˈliːvieɪt/', 'verb', 'To make suffering, deficiency, or a problem less severe', '减轻；缓和；缓解', 4, 4800, '["ielts"]', '源自拉丁语 alleviare，ad-（向）+ levis（轻），字面意为"使变轻"', '[{"en":"The new policy aims to alleviate poverty in developing countries.","cn":"新政策旨在减轻发展中国家的贫困问题。"},{"en":"Medication can help alleviate the symptoms of chronic pain.","cn":"药物可以帮助缓解慢性疼痛的症状。"}]', '["relieve","ease","mitigate","lessen"]', '["worsen","aggravate","intensify"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ambiguous', '/æmˈbɪɡjuəs/', 'adjective', 'Open to more than one interpretation; not having one obvious meaning', '模棱两可的；含糊不清的', 4, 4900, '["ielts"]', '源自拉丁语 ambiguus，ambi-（两者）+ agere（驱使），字面意为"在两个方向间摇摆"', '[{"en":"The wording of the law is deliberately ambiguous, leaving room for interpretation.","cn":"该法律的措辞故意含糊不清，留有解释的余地。"},{"en":"His ambiguous response made it difficult to understand his position.","cn":"他模棱两可的回答让人难以理解他的立场。"}]', '["vague","unclear","equivocal","obscure"]', '["clear","unambiguous","explicit","definite"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('analyse', '/ˈænəlaɪz/', 'verb', 'To examine something methodically and in detail, typically to explain and interpret it', '分析；解析；研究', 3, 3500, '["ielts"]', '源自希腊语 analyein，ana-（向上、彻底）+ lyein（解开），字面意为"彻底解开以理解"', '[{"en":"Researchers analysed data from over 10,000 participants in the study.","cn":"研究人员分析了研究中超过一万名参与者的数据。"},{"en":"Students are expected to analyse the causes of the economic crisis.","cn":"学生需要分析经济危机的原因。"}]', '["examine","study","investigate","evaluate"]', '["ignore","neglect","overlook"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('anticipate', '/ænˈtɪsɪpeɪt/', 'verb', 'To regard as probable; to expect or predict; to act in advance of', '预期；期望；预料；先于…行动', 4, 4100, '["ielts"]', '源自拉丁语 anticipare，ante-（提前）+ capere（拿取），字面意为"提前把握"', '[{"en":"The company anticipates a significant increase in revenue next quarter.","cn":"公司预计下一季度收入将大幅增长。"},{"en":"We did not anticipate the strong public reaction to the proposal.","cn":"我们没有预料到公众对该提案的强烈反应。"}]', '["expect","foresee","predict","envisage"]', '["doubt","be surprised","react afterwards"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('apparatus', '/ˌæpəˈreɪtəs/', 'noun', 'The technical equipment or machinery needed for a particular activity or purpose', '设备；器械；装置；机构', 4, 5800, '["ielts"]', '源自拉丁语 apparare，ad-（向）+ parare（准备），字面意为"为某目的准备好的东西"', '[{"en":"The laboratory is equipped with state-of-the-art scientific apparatus.","cn":"实验室配备了最先进的科学仪器。"},{"en":"The entire apparatus of government was mobilised to deal with the crisis.","cn":"整个政府机构都被动员起来应对这场危机。"}]', '["equipment","device","machinery","instrument"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('apparent', '/əˈpærənt/', 'adjective', 'Clearly visible or understood; obvious; seeming real or true but not necessarily so', '明显的；表面上的；看似…的', 3, 3900, '["ielts"]', '源自拉丁语 apparens，apparere 的现在分词，ad-（向）+ parere（出现），意为"显现出来的"', '[{"en":"It was apparent from her expression that she was deeply upset.","cn":"从她的表情可以明显看出她非常难过。"},{"en":"The apparent simplicity of the task belies its true complexity.","cn":"这项任务表面上的简单掩盖了其真正的复杂性。"}]', '["obvious","evident","clear","seeming"]', '["hidden","obscure","unclear","genuine"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('arbitrary', '/ˈɑːbɪtrəri/', 'adjective', 'Based on random choice or personal whim rather than any reason or system', '任意的；武断的；专断的', 4, 5000, '["ielts"]', '源自拉丁语 arbitrarius，arbiter（裁判者）派生，原指"由裁判者个人判断决定的"', '[{"en":"The decision to raise tuition fees seemed arbitrary and unjustified.","cn":"提高学费的决定似乎武断且缺乏理由。"},{"en":"Many people feel that the tax system is arbitrary in its application.","cn":"许多人觉得税制在执行中很随意。"}]', '["random","capricious","subjective","whimsical"]', '["systematic","rational","logical","consistent"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('articulate', '/ɑːˈtɪkjuleɪt/', 'verb', 'To express an idea or feeling fluently and coherently; to pronounce clearly', '清楚地表达；清晰地发音', 4, 5200, '["ielts"]', '源自拉丁语 articulare，articulus（关节）派生，字面意为"像关节一样把语言连接清楚"', '[{"en":"She was able to articulate her concerns clearly during the meeting.","cn":"她能够在会议期间清楚地表达自己的担忧。"},{"en":"Good speakers know how to articulate complex ideas in simple terms.","cn":"优秀的演讲者知道如何用简单的语言清楚地表达复杂的想法。"}]', '["express","enunciate","state","verbalise"]', '["mumble","mutter","obscure"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aspect', '/ˈæspekt/', 'noun', 'A particular part or feature of something; the appearance or impression presented', '方面；层面；外观；面貌', 3, 3400, '["ielts"]', '源自拉丁语 aspectus，aspicere 的过去分词，ad-（向）+ specere（看），字面意为"所看到的一面"', '[{"en":"Climate change affects every aspect of human life, from agriculture to health.","cn":"气候变化影响人类生活的方方面面，从农业到健康。"},{"en":"One important aspect of the course is its focus on practical skills.","cn":"该课程的一个重要方面是它对实践技能的关注。"}]', '["feature","facet","element","dimension"]', '["whole","entirety"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assess', '/əˈses/', 'verb', 'To evaluate or estimate the nature, quality, or ability of something', '评估；评定；估算', 3, 3300, '["ielts"]', '源自拉丁语 assidere，ad-（向）+ sedere（坐），原意为"坐在旁边协助判断"，后引申为"评估"', '[{"en":"Teachers assess students through a combination of exams and coursework.","cn":"教师通过考试和课程作业相结合来评估学生。"},{"en":"The committee will assess the environmental impact of the proposed development.","cn":"委员会将评估拟议开发项目对环境的影响。"}]', '["evaluate","appraise","gauge","estimate"]', '["ignore","disregard"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('asset', '/ˈæset/', 'noun', 'A useful or valuable thing, person, or quality; property owned by a person or company', '资产；财产；有价值的人或物', 3, 3700, '["ielts"]', '源自拉丁语 assatis，ad-（向）+ satis（足够），原指"足够的东西"，后演变为"有价值的财产"', '[{"en":"Education is one of the most valuable assets a country can invest in.","cn":"教育是一个国家可以投资的最有价值的资产之一。"},{"en":"Her language skills were a great asset when she worked abroad.","cn":"她在国外工作时，语言能力是一笔巨大的财富。"}]', '["resource","property","advantage","possession"]', '["liability","burden","disadvantage"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assign', '/əˈsaɪn/', 'verb', 'To allocate a task or responsibility to someone; to designate or set apart for a specific purpose', '分配；指派；指定；布置', 3, 3600, '["ielts"]', '源自拉丁语 assignare，ad-（向）+ signare（标记），字面意为"用标记指定归属"', '[{"en":"The teacher assigned a research project to each group of students.","cn":"老师给每组学生布置了一个研究项目。"},{"en":"The building was assigned for use as a community centre.","cn":"该建筑被指定用作社区中心。"}]', '["allocate","designate","appoint","delegate"]', '["withhold","retain","keep"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('attribute', '/əˈtrɪbjuːt/', 'verb', 'To regard something as being caused by or belonging to someone or something', '归因于；认为…属于；属性', 4, 4300, '["ielts"]', '源自拉丁语 attribuere，ad-（向）+ tribuere（给予），字面意为"把…给予（归于）某来源"', '[{"en":"Scientists attribute the rise in global temperatures to increased greenhouse gas emissions.","cn":"科学家将全球气温上升归因于温室气体排放的增加。"},{"en":"Success in exams is often attributed to consistent study habits.","cn":"考试成功通常被认为归功于持续的学习习惯。"}]', '["ascribe","credit","assign","impute"]', '["deny","disclaim","divorce from"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('autonomous', '/ɔːˈtɒnəməs/', 'adjective', 'Having the freedom to govern oneself or control one''s own affairs; acting independently', '自治的；自主的；有自主权的', 4, 5400, '["ielts"]', '源自希腊语 autonomos，auto-（自我）+ nomos（法则），字面意为"自我治理、自我立法"', '[{"en":"The region was granted autonomous status, allowing it to make its own laws.","cn":"该地区获得了自治地位，被允许制定自己的法律。"},{"en":"Autonomous vehicles are expected to transform urban transportation.","cn":"自动驾驶汽车预计将改变城市交通。"}]', '["independent","self-governing","sovereign","self-directed"]', '["dependent","subordinate","controlled"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('behalf', '/bɪˈhɑːf/', 'noun', 'In the interests of a person, organisation, or group; as a representative of', '代表；利益；方面', 3, 4400, '["ielts"]', '由 be-（处于）+ half（一半、方面）构成，字面意为"站在某人一方"', '[{"en":"The lawyer spoke on behalf of the victims of the industrial accident.","cn":"律师代表工业事故的受害者发言。"},{"en":"On behalf of the entire committee, I would like to thank you for your contribution.","cn":"我代表全体委员会感谢您的贡献。"}]', '["interest","sake","representation"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bias', '/ˈbaɪəs/', 'noun', 'A prejudice in favour of or against one thing, person, or group, usually considered unfair', '偏见；偏向；偏差', 3, 3800, '["ielts"]', '源自古法语 biais，意为"斜线、倾斜"，引申为"不公正的倾向或偏袒"', '[{"en":"The study found evidence of gender bias in the recruitment process.","cn":"该研究发现了招聘过程中存在性别偏见的证据。"},{"en":"Media bias can significantly influence public opinion during elections.","cn":"媒体偏见可以在选举期间显著影响公众舆论。"}]', '["prejudice","partiality","inclination","predisposition"]', '["impartiality","fairness","neutrality","objectivity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('biodiversity', '/ˌbaɪəʊdaɪˈvɜːsəti/', 'noun', 'The variety of life in a particular habitat or ecosystem; the diversity of plant and animal species', '生物多样性；物种多样性', 4, 5600, '["ielts"]', '由 bio-（生命，源自希腊语 bios）+ diversity（多样性）组合而成的现代科学术语', '[{"en":"Deforestation is one of the greatest threats to biodiversity worldwide.","cn":"森林砍伐是全球生物多样性面临的最大威胁之一。"},{"en":"Protecting biodiversity is essential for maintaining ecosystem balance.","cn":"保护生物多样性对于维持生态平衡至关重要。"}]', '["species diversity","ecological diversity","biological variety"]', '["monoculture","extinction"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('breed', '/briːd/', 'verb', 'To cause an animal to produce offspring; to give rise to or cause something (usually negative)', '繁殖；培育；引起；导致', 3, 4500, '["ielts"]', '源自古英语 bredan，与日耳曼语族 brood（孵化）相关，原指"孵化、养育"', '[{"en":"Irresponsible waste disposal can breed disease in local communities.","cn":"不负责任的废物处理会在当地社区滋生疾病。"},{"en":"Poverty and unemployment often breed social unrest and crime.","cn":"贫困和失业往往滋生社会动荡和犯罪。"}]', '["reproduce","raise","generate","foster"]', '["sterilise","suppress","prevent"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bulk', '/bʌlk/', 'noun', 'The mass or magnitude of something large; the greater part of something', '大量；大批；主体部分；体积', 3, 4600, '["ielts"]', '源自古诺尔斯语 bulki，意为"一堆货物"，后引申为"大量、主体部分"', '[{"en":"The bulk of the evidence suggests that the policy has been ineffective.","cn":"大部分证据表明该政策一直无效。"},{"en":"Buying in bulk can significantly reduce the cost per unit.","cn":"批量购买可以显著降低单位成本。"}]', '["majority","mass","volume","quantity"]', '["minority","small amount"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bypass', '/ˈbaɪpɑːs/', 'verb', 'To go around or avoid something; to circumvent a rule or procedure', '绕过；避开；绕道', 4, 5300, '["ielts"]', '由 by-（旁边）+ pass（通过）构成，字面意为"从旁边通过而不经过"', '[{"en":"The new road was built to bypass the congested city centre.","cn":"修建新公路是为了绕开拥堵的市中心。"},{"en":"Some companies try to bypass safety regulations to cut costs.","cn":"一些公司试图绕过安全法规以降低成本。"}]', '["circumvent","avoid","sidestep","skirt"]', '["confront","face","comply with"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('candidate', '/ˈkændɪdət/', 'noun', 'A person who applies for a job or is nominated for a position or award', '候选人；申请人；应试者', 3, 3200, '["ielts"]', '源自拉丁语 candidatus，candidus（白色）派生，古罗马竞选者穿白色长袍以示纯洁', '[{"en":"There were over 200 candidates for the scholarship programme.","cn":"有超过200名奖学金项目的申请者。"},{"en":"She is considered a strong candidate for the managerial position.","cn":"她被认为是管理职位的有力候选人。"}]', '["applicant","contender","nominee","aspirant"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capable', '/ˈkeɪpəbl/', 'adjective', 'Having the ability, fitness, or quality necessary to do or achieve a specified thing', '有能力的；能干的；能够…的', 3, 3100, '["ielts"]', '源自拉丁语 capabilis，capere（拿取、容纳）派生，字面意为"有容纳或掌握能力的"', '[{"en":"She is capable of handling multiple projects simultaneously.","cn":"她有能力同时处理多个项目。"},{"en":"The new system is capable of processing thousands of transactions per second.","cn":"新系统能够每秒处理数千笔交易。"}]', '["competent","able","skilled","proficient"]', '["incapable","incompetent","unable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capacity', '/kəˈpæsəti/', 'noun', 'The maximum amount that something can contain; the ability or power to do something', '容量；能力；才能；身份', 3, 3500, '["ielts"]', '源自拉丁语 capacitas，capax（能容纳的）派生，capere（拿取）的词根，意为"容纳量或能力"', '[{"en":"The stadium has a seating capacity of 60,000 spectators.","cn":"该体育场可容纳6万名观众。"},{"en":"Children have a remarkable capacity for learning new languages quickly.","cn":"儿童有快速学习新语言的非凡能力。"}]', '["ability","capability","volume","aptitude"]', '["inability","incapacity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capture', '/ˈkæptʃə/', 'verb', 'To take into possession by force or skill; to record or express accurately', '捕获；俘获；捕捉；夺取', 3, 3700, '["ielts"]', '源自拉丁语 captura，capere（拿取、抓住）派生，字面意为"抓住的行为或结果"', '[{"en":"The documentary captures the daily lives of people in remote villages.","cn":"这部纪录片捕捉了偏远村庄人们的日常生活。"},{"en":"The company managed to capture a significant share of the market.","cn":"该公司成功夺取了相当大的市场份额。"}]', '["seize","catch","record","capture"]', '["release","free","liberate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('catalog', '/ˈkætəlɒɡ/', 'noun', 'A complete list of items in a systematic order; a publication containing details of items', '目录；系列；一览表', 3, 4700, '["ielts"]', '源自希腊语 katalogos，kata-（向下、完全）+ legein（收集、说），字面意为"完全列举"', '[{"en":"The library maintains an online catalog of all its books and resources.","cn":"图书馆维护着所有书籍和资源的在线目录。"},{"en":"The exhibition catalog provides detailed information about each artwork.","cn":"展览目录提供了每件艺术品的详细信息。"}]', '["list","inventory","index","register"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('category', '/ˈkætəɡəri/', 'noun', 'A class or division of people or things regarded as having particular shared characteristics', '类别；种类；范畴', 3, 3200, '["ielts"]', '源自希腊语 kategoria，kata-（向下）+ agora（集会），原指"在公共集会上进行的声明或分类"', '[{"en":"The questions in the survey fall into three main categories.","cn":"调查中的问题分为三大类。"},{"en":"Students are grouped by category based on their language proficiency.","cn":"学生按语言能力分组归类。"}]', '["class","group","type","classification"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('causal', '/ˈkɔːzl/', 'adjective', 'Relating to or acting as a cause; expressing or indicating a cause', '因果的；有因果关系的；表示原因的', 5, 6200, '["ielts"]', '源自拉丁语 causalis，causa（原因）派生，字面意为"与原因有关的"', '[{"en":"The research establishes a causal link between air pollution and respiratory diseases.","cn":"该研究建立了空气污染与呼吸系统疾病之间的因果关系。"},{"en":"It is important to distinguish between causal relationships and mere correlations.","cn":"区分因果关系和单纯的相关性很重要。"}]', '["causative","etiological","consequential"]', '["random","coincidental","unrelated"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cease', '/siːs/', 'verb', 'To bring or come to an end; to stop doing something', '停止；终止；结束', 4, 4800, '["ielts"]', '源自拉丁语 cessare，cedere（退让、离开）的频繁形式，字面意为"退后而停止"', '[{"en":"The factory ceased production last year due to financial difficulties.","cn":"该工厂去年因财务困难停止了生产。"},{"en":"Both sides agreed to cease hostilities and begin peace negotiations.","cn":"双方同意停止敌对行动并开始和平谈判。"}]', '["stop","halt","discontinue","terminate"]', '["continue","commence","persist","resume"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('characterize', '/ˈkærəktəraɪz/', 'verb', 'To describe the distinctive nature or features of something; to be a typical feature of', '描述…的特征；以…为特征；刻画', 4, 4200, '["ielts"]', '源自希腊语 kharakter（印记、特征）+ -ize（动词后缀），意为"赋予或描述特征"', '[{"en":"The era was characterized by rapid industrialisation and urban growth.","cn":"那个时代以快速工业化和城市增长为特征。"},{"en":"Her writing is characterized by vivid imagery and emotional depth.","cn":"她的写作以生动的意象和情感深度为特点。"}]', '["describe","depict","portray","distinguish"]', '["misrepresent","distort"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('chronic', '/ˈkrɒnɪk/', 'adjective', 'Persisting for a long time or constantly recurring; (of a problem) long-standing', '慢性的；长期的；持续不断的', 4, 5100, '["ielts"]', '源自希腊语 khronikos，khronos（时间）派生，字面意为"与时间相关的、长期持续的"', '[{"en":"Chronic unemployment remains a serious problem in many developing nations.","cn":"长期失业在许多发展中国家仍然是一个严重问题。"},{"en":"She suffers from chronic back pain that affects her daily activities.","cn":"她患有影响日常活动的慢性背痛。"}]', '["persistent","long-term","enduring","habitual"]', '["acute","temporary","brief","short-term"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cite', '/saɪt/', 'verb', 'To quote as evidence or authority; to refer to as an example or proof', '引用；引证；举例；传唤', 3, 3800, '["ielts"]', '源自拉丁语 citare，cie re（调动、推动）的频繁形式，原意为"召唤出庭"，后引申为"引用"', '[{"en":"The author cites several studies to support her argument about climate change.","cn":"作者引用了几项研究来支持她关于气候变化的论点。"},{"en":"He was cited as an example of how dedication can lead to success.","cn":"他被引为 dedication 可以带来成功的典范。"}]', '["quote","reference","mention","allude to"]', '["ignore","omit","plagiarise"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('civic', '/ˈsɪvɪk/', 'adjective', 'Relating to a city or town and its citizens; relating to the duties of a citizen', '城市的；市民的；公民的', 3, 5200, '["ielts"]', '源自拉丁语 civis（公民），与 civil（文明的）同源，字面意为"与公民或城市有关的"', '[{"en":"Civic leaders met to discuss plans for the new public transport system.","cn":"市政领导人开会讨论新公共交通系统的计划。"},{"en":"Residents have a civic duty to participate in local elections.","cn":"居民有参与地方选举的公民义务。"}]', '["municipal","urban","citizen","public"]', '["rural","private","personal"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('clarify', '/ˈklærɪfaɪ/', 'verb', 'To make a statement or situation less confused and more clearly comprehensible', '澄清；阐明；使更清楚', 3, 4000, '["ielts"]', '源自拉丁语 clarificare，clarus（清楚）+ facere（使），字面意为"使变清楚"', '[{"en":"Could you clarify what you mean by ''sustainable development''?","cn":"您能否澄清一下您所说的「可持续发展」是什么意思？"},{"en":"The government issued a statement to clarify the new immigration policy.","cn":"政府发表声明澄清新的移民政策。"}]', '["explain","elucidate","simplify","illuminate"]', '["confuse","obscure","complicate","muddle"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('classify', '/ˈklæsɪfaɪ/', 'verb', 'To arrange or organise something into classes or categories', '分类；归类；把…分级', 3, 4100, '["ielts"]', '源自拉丁语 classis（类别）+ facere（做、使），字面意为"使归入类别"', '[{"en":"Biologists classify organisms into different kingdoms based on their characteristics.","cn":"生物学家根据特征将生物分类到不同的界。"},{"en":"The documents were classified as confidential and restricted from public access.","cn":"这些文件被归类为机密文件，禁止公众查阅。"}]', '["categorise","sort","organise","group"]', '["confuse","mix","disorganise"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('clause', '/klɔːz/', 'noun', 'A unit of grammatical structure containing a subject and predicate; a stipulation in a legal document', '从句；条款', 4, 5500, '["ielts"]', '源自拉丁语 clausa，claudere（关闭）的过去分词，字面意为"一个闭合的语言单元"', '[{"en":"The contract includes a clause that allows either party to terminate the agreement.","cn":"合同中包含一条允许任何一方终止协议的条款。"},{"en":"Students must learn to identify main and subordinate clauses in complex sentences.","cn":"学生必须学会识别复杂句中的主句和从句。"}]', '["provision","stipulation","section","subsection"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('coherent', '/kəʊˈhɪərənt/', 'adjective', 'Logical and consistent; able to speak clearly and logically; forming a unified whole', '连贯的；一致的；条理清楚的', 4, 5300, '["ielts"]', '源自拉丁语 cohaerens，co-（共同）+ haerere（粘附），字面意为"粘在一起、形成整体"', '[{"en":"A coherent argument is essential for achieving a high score in the writing test.","cn":"连贯的论证是在写作考试中获得高分的关键。"},{"en":"The government has yet to present a coherent strategy for tackling unemployment.","cn":"政府尚未提出一套连贯的应对失业问题的战略。"}]', '["logical","consistent","unified","rational"]', '["incoherent","inconsistent","confused","disjointed"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('coincide', '/ˌkəʊɪnˈsaɪd/', 'verb', 'To occur at or during the same time; to correspond in nature or character', '同时发生；一致；重合', 4, 5600, '["ielts"]', '源自中世纪拉丁语 coincidere，co-（共同）+ incidere（落入、发生），字面意为"同时落入"', '[{"en":"The launch of the new product coincided with the annual technology conference.","cn":"新产品的发布恰逢年度技术大会。"},{"en":"Our views on environmental policy largely coincide.","cn":"我们在环境政策上的观点大体一致。"}]', '["concur","overlap","correspond","synchronise"]', '["differ","diverge","conflict"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('collaborate', '/kəˈlæbəreɪt/', 'verb', 'To work jointly with others on an activity or project; to cooperate', '合作；协作；通敌', 4, 4600, '["ielts"]', '源自拉丁语 collaborare，com-（共同）+ laborare（劳动），字面意为"共同劳动"', '[{"en":"Researchers from different countries collaborated on the climate change study.","cn":"来自不同国家的研究人员合作进行了气候变化研究。"},{"en":"The two organisations collaborated to develop a new training programme.","cn":"两个组织合作开发了新的培训项目。"}]', '["cooperate","partner","team up","work together"]', '["compete","oppose","conflict"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('colonial', '/kəˈləʊniəl/', 'adjective', 'Relating to or characteristic of a colony or colonies; possessing colonies', '殖民的；殖民地的；殖民地风格的', 4, 5000, '["ielts"]', '源自拉丁语 colonia（殖民地），colere（耕作、定居）派生，意为"与殖民活动相关的"', '[{"en":"Many African nations gained independence from colonial rule in the mid-twentieth century.","cn":"许多非洲国家在二十世纪中叶从殖民统治中获得独立。"},{"en":"The city still retains much of its colonial architecture from the nineteenth century.","cn":"这座城市至今仍保留着大量十九世纪的殖民时期建筑。"}]', '["imperial","settlement","territorial"]', '["independent","sovereign","postcolonial"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commemorate', '/kəˈmeməreɪt/', 'verb', 'To recall and show respect for someone or something in a ceremony or observance', '纪念；庆祝；缅怀', 4, 5700, '["ielts"]', '源自拉丁语 commemorare，com-（完全）+ memorare（提及、记住），字面意为"彻底铭记"', '[{"en":"A national holiday was established to commemorate the end of the war.","cn":"设立了国家假日以纪念战争结束。"},{"en":"The statue was erected to commemorate those who lost their lives in service.","cn":"这座雕像是为纪念在执行任务中牺牲的人们而竖立的。"}]', '["honour","remember","celebrate","memorialise"]', '["forget","ignore","neglect"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commence', '/kəˈmens/', 'verb', 'To begin or start something; to come into being', '开始；着手；启动', 4, 4700, '["ielts"]', '源自拉丁语 cominitiare，com-（强调）+ initiare（开始），initium（开端）派生', '[{"en":"The construction of the new hospital will commence next month.","cn":"新医院的建设将于下月开始。"},{"en":"The ceremony commenced with a speech by the university president.","cn":"仪式以大学校长的讲话开始。"}]', '["begin","initiate","launch","inaugurate"]', '["end","conclude","terminate","finish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commend', '/kəˈmend/', 'verb', 'To praise or approve of someone or something publicly; to entrust to someone''s care', '表扬；推荐；委托', 4, 5800, '["ielts"]', '源自拉丁语 commendare，com-（强调）+ mandare（委托），字面意为"郑重委托或推荐"', '[{"en":"The teacher commended the students for their outstanding community service.","cn":"老师表扬了学生们出色的社区服务。"},{"en":"I would commend this book to anyone interested in modern history.","cn":"我会把这本书推荐给任何对现代历史感兴趣的人。"}]', '["praise","applaud","recommend","endorse"]', '["condemn","criticise","blame","denounce"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commentary', '/ˈkɒməntəri/', 'noun', 'An expression of opinions or explanations about an event or situation; a running description', '评论；解说；实况报道；注释', 4, 5400, '["ielts"]', '源自拉丁语 commentarium（备忘录），commentus（思考、发明）派生，意为"对事件的解释性叙述"', '[{"en":"The documentary provides a thought-provoking commentary on modern consumer culture.","cn":"这部纪录片对现代消费文化提供了发人深省的评论。"},{"en":"Live commentary during sports events enhances the viewing experience for audiences.","cn":"体育赛事中的现场解说增强了观众的观看体验。"}]', '["analysis","narration","annotation","explanation"]', '["silence","ignorance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commodity', '/kəˈmɒdəti/', 'noun', 'A raw material or primary agricultural product that can be bought and sold; a useful or valuable thing', '商品；货物；有用的东西', 4, 4900, '["ielts"]', '源自拉丁语 commoditas，commodus（合适的、方便的）派生，字面意为"方便之物"，后指"商品"', '[{"en":"Oil remains one of the most traded commodities on the global market.","cn":"石油仍然是全球市场上交易量最大的商品之一。"},{"en":"Clean water has become a precious commodity in many parts of the world.","cn":"在世界许多地方，清洁水已成为珍贵的资源。"}]', '["product","goods","merchandise","resource"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commute', '/kəˈmjuːt/', 'verb', 'To travel some distance between one''s home and place of work on a regular basis', '通勤；减刑；改变', 3, 4500, '["ielts"]', '源自拉丁语 commutare，com-（完全）+ mutare（改变），原指"改变、交换"，后引申为"定期往返"', '[{"en":"Many workers commute over an hour each way to reach their offices.","cn":"许多上班族单程通勤超过一小时才能到达办公室。"},{"en":"The prison sentence was commuted to community service by the judge.","cn":"法官将监禁判决改为社区服务。"}]', '["travel","journey","reduce","lessen"]', '["stay","reside","increase"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compact', '/kəmˈpækt/', 'adjective', 'Closely and neatly packed together; dense; having all necessary features within a small space', '紧凑的；紧密的；小巧的', 3, 5100, '["ielts"]', '源自拉丁语 compactus，com-（共同）+ pangere（固定），字面意为"牢牢固定在一起"', '[{"en":"The compact design of the device makes it ideal for travel.","cn":"该设备紧凑的设计使其非常适合旅行使用。"},{"en":"The city has a compact centre that is easy to explore on foot.","cn":"这座城市有一个紧凑的中心，步行即可轻松游览。"}]', '["dense","condensed","concise","compressed"]', '["loose","sprawling","expanded","verbose"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('comparable', '/ˈkɒmpərəbl/', 'adjective', 'Able to be likened to another; similar in size, amount, or quality', '可比较的；类似的；比得上的', 3, 4400, '["ielts"]', '源自拉丁语 comparabilis，comparare（比较）派生，com-（共同）+ par（平等），意为"可以放在一起比较的"', '[{"en":"The two studies are not directly comparable because they used different methodologies.","cn":"这两项研究不能直接比较，因为它们使用了不同的方法论。"},{"en":"No other city in the region offers a comparable quality of life.","cn":"该地区没有其他城市能提供可与之相比的生活质量。"}]', '["similar","analogous","equivalent","akin"]', '["different","incomparable","unlike","dissimilar"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compatible', '/kəmˈpætəbl/', 'adjective', 'Able to exist or occur together without conflict; able to be used together', '兼容的；相容的；能共处的', 4, 5200, '["ielts"]', '源自拉丁语 compatibilis，com-（共同）+ pati（忍受），字面意为"能够共同忍受的"', '[{"en":"The new software is compatible with most operating systems currently in use.","cn":"新软件与目前使用的大多数操作系统兼容。"},{"en":"It is important that work and family life are compatible.","cn":"工作和家庭生活能够相容很重要。"}]', '["congruent","harmonious","suitable","consistent"]', '["incompatible","conflicting","discordant"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compelling', '/kəmˈpelɪŋ/', 'adjective', 'Evoking interest or attention in a powerful way; not able to be refuted; convincing', '引人注目的；令人信服的； compelling 的', 4, 4800, '["ielts"]', '源自拉丁语 compellere，com-（共同）+ pellere（推动），字面意为"强力推动"，引申为"令人无法抗拒的"', '[{"en":"The documentary presents a compelling argument for renewable energy adoption.","cn":"这部纪录片为可再生能源的采用提出了令人信服的论据。"},{"en":"She told a compelling story about her journey from poverty to success.","cn":"她讲述了一个从贫困到成功的引人入胜的故事。"}]', '["convincing","persuasive","captivating","powerful"]', '["unconvincing","weak","boring","feeble"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compensate', '/ˈkɒmpenseɪt/', 'verb', 'To give someone something in recognition of loss, suffering, or injury; to make up for', '补偿；赔偿；弥补', 4, 4300, '["ielts"]', '源自拉丁语 compensare，com-（共同）+ pensare（称量），字面意为"等价称量以补偿"', '[{"en":"The company agreed to compensate employees for the hours they worked overtime.","cn":"公司同意补偿员工的加班时间。"},{"en":"High salaries can compensate for the high cost of living in the city.","cn":"高工资可以弥补城市高昂的生活成本。"}]', '["reimburse","repay","offset","make up for"]', '["penalise","deprive","damage"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('competent', '/ˈkɒmpɪtənt/', 'adjective', 'Having the necessary ability, knowledge, or skill to do something successfully', '有能力的；胜任的；称职的', 3, 4200, '["ielts"]', '源自拉丁语 competens，competere 的现在分词，com-（共同）+ petere（追求），字面意为"有能力去争取的"', '[{"en":"A competent translator must be fluent in at least two languages.","cn":"一名称职的翻译必须至少精通两种语言。"},{"en":"The report was prepared by a competent team of researchers.","cn":"这份报告由一支称职的研究团队编写。"}]', '["capable","proficient","skilled","qualified"]', '["incompetent","incapable","unqualified"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compile', '/kəmˈpaɪl/', 'verb', 'To produce something by assembling information collected from various sources', '汇编；编制；收集；编译', 4, 5000, '["ielts"]', '源自拉丁语 compilare，com-（共同）+ pilare（堆叠），字面意为"把材料堆集在一起"', '[{"en":"The research team compiled data from over fifty different studies.","cn":"研究团队汇编了来自五十多项不同研究的数据。"},{"en":"It took several years to compile a comprehensive dictionary of the language.","cn":"编纂一部全面的该语言词典花了数年时间。"}]', '["assemble","collect","gather","compile"]', '["scatter","disperse","distribute"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('complement', '/ˈkɒmplɪment/', 'verb', 'To add to something in a way that enhances or improves it; to complete', '补充；补足；与…相配', 4, 5500, '["ielts"]', '源自拉丁语 complementum，complere（填满）派生，com-（完全）+ plere（填充），字面意为"使之完整"', '[{"en":"The wine was chosen to complement the flavours of the main course.","cn":"选酒是为了与主菜的味道相搭配。"},{"en":"Practical experience and theoretical knowledge complement each other.","cn":"实践经验和理论知识相辅相成。"}]', '["enhance","complete","accompany","augment"]', '["clash","conflict","detract","oppose"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('complexity', '/kəmˈpleksəti/', 'noun', 'The state of having many parts and being difficult to understand or find an answer to', '复杂性；复杂的事物；复杂因素', 4, 4600, '["ielts"]', '源自拉丁语 complexus，com-（共同）+ plectere（编织），字面意为"多部分交织在一起的状态"', '[{"en":"The complexity of the legal system makes it difficult for ordinary people to navigate.","cn":"法律体系的复杂性使普通人难以应对。"},{"en":"Modern technology has added new layers of complexity to global communication.","cn":"现代技术给全球通信增添了新的复杂层面。"}]', '["intricacy","complication","sophistication","elaboration"]', '["simplicity","straightforwardness","clarity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compliance', '/kəmˈplaɪəns/', 'noun', 'The action of complying with a wish, command, or rule; conformity', '遵从；服从；合规；顺从', 4, 5600, '["ielts"]', '源自拉丁语 complere（完成、满足），com-（完全）+ plere（填充），引申为"满足要求的状态"', '[{"en":"Compliance with safety regulations is mandatory for all construction companies.","cn":"遵守安全法规对所有建筑公司是强制性的。"},{"en":"The firm was fined for non-compliance with environmental standards.","cn":"该公司因未遵守环境标准而被罚款。"}]', '["conformity","adherence","observance","obedience"]', '["violation","noncompliance","defiance","disobedience"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('component', '/kəmˈpəʊnənt/', 'noun', 'A part or element of a larger whole; a piece of equipment in a system', '组成部分；成分；零部件', 3, 3900, '["ielts"]', '源自拉丁语 componens，componere 的现在分词，com-（共同）+ ponere（放置），字面意为"放在一起的部分"', '[{"en":"Education is a key component of any successful economic development strategy.","cn":"教育是任何成功经济发展战略的关键组成部分。"},{"en":"The factory manufactures electronic components for mobile phones.","cn":"该工厂生产手机电子零部件。"}]', '["element","part","constituent","ingredient"]', '["whole","totality","entirety"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('comprehensive', '/ˌkɒmprɪˈhensɪv/', 'adjective', 'Complete; including all or nearly all elements or aspects of something', '全面的；综合的；详尽的', 4, 4100, '["ielts"]', '源自拉丁语 comprehensivus，comprehendere（完全抓住），com-（完全）+ prehendere（抓住），意为"涵盖一切"', '[{"en":"The report provides a comprehensive overview of the current housing market.","cn":"该报告提供了当前住房市场的全面概述。"},{"en":"A comprehensive review of the literature was conducted before the experiment.","cn":"实验前进行了全面的文献综述。"}]', '["thorough","complete","extensive","exhaustive"]', '["partial","incomplete","limited","narrow"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('comprise', '/kəmˈpraɪz/', 'verb', 'To consist of; to be made up of; to include or contain', '包含；由…组成；构成', 4, 4700, '["ielts"]', '源自拉丁语 comprehendere 的变体，com-（共同）+ prehendere（抓住），字面意为"全部包含在内"', '[{"en":"The committee comprises representatives from all major political parties.","cn":"委员会由所有主要政党的代表组成。"},{"en":"The course comprises ten modules covering different aspects of business management.","cn":"该课程由涵盖商业管理不同方面的十个模块组成。"}]', '["consist of","include","contain","encompass"]', '["exclude","omit","lack"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('compulsory', '/kəmˈpʌlsəri/', 'adjective', 'Required by law or a rule; obligatory; mandatory', '强制的；义务的；必修的', 4, 4800, '["ielts"]', '源自拉丁语 compulsorius，compellere（强迫）派生，com-（共同）+ pellere（推动），字面意为"被强制推动的"', '[{"en":"Compulsory education laws require children to attend school until the age of sixteen.","cn":"义务教育法要求儿童在十六岁之前必须上学。"},{"en":"Wearing seat belts is compulsory for all passengers in the vehicle.","cn":"车上所有乘客都必须系安全带。"}]', '["mandatory","obligatory","required","imperative"]', '["optional","voluntary","elective","discretionary"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('concede', '/kənˈsiːd/', 'verb', 'To admit that something is true after first resisting it; to surrender or yield', '承认；让步；允许；认输', 4, 5400, '["ielts"]', '源自拉丁语 concedere，con-（共同、完全）+ cedere（退让），字面意为"完全退让、承认对方正确"', '[{"en":"The government conceded that the initial estimates were inaccurate.","cn":"政府承认最初的估计不准确。"},{"en":"After a long debate, she conceded that his argument had some merit.","cn":"经过长时间的辩论，她承认他的论点有一定道理。"}]', '["admit","grant","yield","acknowledge"]', '["deny","resist","contest","refute"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('conceive', '/kənˈsiːv/', 'verb', 'To form or devise a plan or idea in the mind; to become pregnant', '构想；设想；怀孕；理解', 4, 5100, '["ielts"]', '源自拉丁语 concipere，con-（共同）+ capere（拿取），字面意为"在心中接纳想法"', '[{"en":"It is difficult to conceive of a world without modern technology.","cn":"很难想象一个没有现代技术的世界。"},{"en":"The project was originally conceived as a way to help disadvantaged students.","cn":"该项目最初的构想是帮助弱势学生。"}]', '["imagine","envisage","devise","formulate"]', '["destroy","misunderstand","overlook"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('concentrate', '/ˈkɒnsntreɪt/', 'verb', 'To focus all one''s attention on a particular object or activity; to gather closely together', '集中；专注；浓缩；聚集', 3, 3300, '["ielts"]', '源自拉丁语 concentrare，con-（共同）+ centrum（中心），字面意为"聚集到中心点"', '[{"en":"Students need to concentrate on their studies if they want to succeed.","cn":"学生如果想要成功就需要专注于学业。"},{"en":"The population is concentrated in the coastal regions of the country.","cn":"人口集中在该国的沿海地区。"}]', '["focus","converge","intensify","gather"]', '["distract","disperse","scatter","dilute"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('conceptual', '/kənˈseptʃuəl/', 'adjective', 'Relating to or based on mental concepts; abstract rather than concrete', '概念的；观念的；抽象的', 5, 5800, '["ielts"]', '源自拉丁语 conceptus（概念），concipere（构想）的过去分词，意为"与思维概念相关的"', '[{"en":"The course introduces students to the conceptual framework of modern economics.","cn":"该课程向学生介绍现代经济学的概念框架。"},{"en":"There is a conceptual difference between justice and equality.","cn":"正义与平等之间存在概念上的差异。"}]', '["theoretical","abstract","ideational","philosophical"]', '["concrete","practical","tangible","empirical"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('concrete', '/ˈkɒŋkriːt/', 'adjective', 'Existing in a material form; real and specific rather than abstract or general', '具体的；实在的；混凝土的', 3, 4000, '["ielts"]', '源自拉丁语 concretus，con-（共同）+ crescere（生长），字面意为"生长在一起的、实体化的"', '[{"en":"The report provides concrete evidence of widespread corruption in the industry.","cn":"该报告提供了该行业普遍腐败的确凿证据。"},{"en":"We need concrete plans, not just vague ideas about what might be done.","cn":"我们需要具体的计划，而不是关于可能做什么的模糊想法。"}]', '["tangible","real","specific","substantial"]', '["abstract","theoretical","vague","intangible"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('concurrent', '/kənˈkʌrənt/', 'adjective', 'Existing, happening, or done at the same time; operating simultaneously', '同时发生的；并行的；一致的', 5, 6100, '["ielts"]', '源自拉丁语 concurrens，concurrere 的现在分词，con-（共同）+ currere（跑），字面意为"同时跑向"', '[{"en":"The two concurrent events made it difficult for attendees to choose which to attend.","cn":"两个同时举行的活动让与会者难以选择。"},{"en":"Concurrent translation services will be available in three languages.","cn":"将提供三种语言的同声翻译服务。"}]', '["simultaneous","parallel","coinciding","synchronous"]', '["sequential","consecutive","successive"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('condemn', '/kənˈdem/', 'verb', 'To express complete disapproval of; to sentence to a particular punishment', '谴责；判刑；宣告…有罪', 4, 4900, '["ielts"]', '源自拉丁语 condemnare，con-（完全）+ damnare（判罪），字面意为"彻底宣判有罪"', '[{"en":"The international community condemned the use of chemical weapons.","cn":"国际社会谴责使用化学武器。"},{"en":"The building was condemned as unsafe after the earthquake.","cn":"地震后该建筑被宣布为不安全建筑。"}]', '["denounce","criticise","censure","sentence"]', '["praise","commend","approve","acquit"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('condense', '/kənˈdens/', 'verb', 'To make something denser or more concentrated; to express in fewer words', '压缩；浓缩；精简；凝结', 4, 5300, '["ielts"]', '源自拉丁语 condensare，con-（完全）+ densus（密集），字面意为"使变得更加密集"', '[{"en":"The author condensed her 500-page novel into a shorter version for young readers.","cn":"作者将她500页的小说压缩成适合年轻读者的精简版本。"},{"en":"Water vapour condenses to form clouds in the atmosphere.","cn":"水蒸气在大气中凝结形成云。"}]', '["compress","abbreviate","concentrate","summarise"]', '["expand","elaborate","dilute","lengthen"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('conditional', '/kənˈdɪʃənl/', 'adjective', 'Subject to one or more requirements being met; not absolute; dependent on something', '有条件的；附带条件的；依条件而定的', 4, 5000, '["ielts"]', '源自拉丁语 conditionalis，condicio（条件、协议）派生，意为"取决于特定条件的"', '[{"en":"The offer of employment is conditional on passing a medical examination.","cn":"录用通知以通过体检为条件。"},{"en":"Conditional sentences are an important part of English grammar.","cn":"条件句是英语语法的重要组成部分。"}]', '["provisional","contingent","qualified","dependent"]', '["unconditional","absolute","absolute","certain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('confide', '/kənˈfaɪd/', 'verb', 'To tell someone about a secret or private matter while trusting them not to repeat it', '倾诉；吐露；信赖', 4, 5700, '["ielts"]', '源自拉丁语 confidere，con-（完全）+ fidere（信任），字面意为"完全信任某人而告知"', '[{"en":"She confided in her close friend about her struggles with anxiety.","cn":"她向密友倾诉了自己与焦虑作斗争的经历。"},{"en":"He confided that he was planning to resign from his position.","cn":"他透露自己正打算辞职。"}]', '["entrust","reveal","disclose","divulge"]', '["conceal","hide","withhold","suppress"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('configuration', '/kənˌfɪɡjʊˈreɪʃn/', 'noun', 'An arrangement of elements in a particular form or figure; the overall layout', '配置；构造；外形；布局', 5, 5900, '["ielts"]', '源自拉丁语 configuratio，con-（共同）+ figurare（塑造），字面意为"各部分共同塑造的整体形态"', '[{"en":"The configuration of the network determines how data flows between devices.","cn":"网络的配置决定了数据如何在设备之间流动。"},{"en":"Different configurations of seating arrangements were tested in the classroom.","cn":"课堂上测试了不同的座位布局配置。"}]', '["arrangement","layout","structure","formation"]', '["disarray","chaos","disorder"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('confine', '/kənˈfaɪn/', 'verb', 'To keep or restrict someone or something within certain limits of space, scope, or time', '限制；局限于；禁闭；关押', 4, 4800, '["ielts"]', '源自拉丁语 confinis，con-（共同）+ finis（边界），字面意为"限制在共同边界内"', '[{"en":"The discussion should be confined to the topic of environmental sustainability.","cn":"讨论应仅限于环境可持续性的话题。"},{"en":"Patients with infectious diseases are often confined to isolation wards.","cn":"传染病患者通常被限制在隔离病房。"}]', '["restrict","limit","restrain","imprison"]', '["free","release","liberate","expand"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('conform', '/kənˈfɔːm/', 'verb', 'To comply with rules, standards, or laws; to behave according to social norms', '遵守；符合；顺应；一致', 4, 4500, '["ielts"]', '源自拉丁语 conformare，con-（完全）+ formare（塑造），字面意为"完全按照标准塑造"', '[{"en":"All products must conform to strict safety standards before being sold.","cn":"所有产品在销售前必须符合严格的安全标准。"},{"en":"Teenagers often feel pressure to conform to the expectations of their peers.","cn":"青少年常常感到有顺从同龄人期望的压力。"}]', '["comply","adhere","follow","observe"]', '["defy","violate","rebel","deviate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('confrontation', '/ˌkɒnfrʌnˈteɪʃn/', 'noun', 'A hostile or argumentative situation or meeting between opposing parties', '对抗；冲突；对峙；当面指责', 4, 5500, '["ielts"]', '源自拉丁语 confrontare，con-（面对面）+ frons（前额、正面），字面意为"面对面相遇"', '[{"en":"The confrontation between protesters and police led to several arrests.","cn":"抗议者与警察之间的对峙导致了数人被捕。"},{"en":"Diplomatic efforts were made to avoid a military confrontation.","cn":"为避免军事对抗进行了外交努力。"}]', '["conflict","clash","standoff","dispute"]', '["agreement","cooperation","harmony","peace"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('congest', '/kənˈdʒest/', 'verb', 'To make a road, passage, or area blocked or overcrowded; to cause congestion', '使拥挤；使拥堵；使充血', 4, 6000, '["ielts"]', '源自拉丁语 congestus，congerere 的过去分词，con-（共同）+ gerere（搬运），字面意为"堆积在一起"', '[{"en":"Heavy traffic regularly congests the main roads during rush hour.","cn":"高峰时段大量车辆经常使主要道路拥堵。"},{"en":"Tourist attractions can become congested during holiday seasons.","cn":"旅游景点在假期可能会变得拥挤不堪。"}]', '["clog","block","overcrowd","jam"]', '["clear","open","unclog","empty"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('consensus', '/kənˈsensəs/', 'noun', 'A general agreement among a group of people; collective opinion', '共识；一致意见；共同看法', 4, 4700, '["ielts"]', '源自拉丁语 consensus，con-（共同）+ sentire（感觉），字面意为"共同的感觉或判断"', '[{"en":"There is a growing scientific consensus that human activity is driving climate change.","cn":"越来越多的科学共识认为人类活动正在推动气候变化。"},{"en":"The committee reached a consensus after hours of discussion.","cn":"委员会经过数小时讨论后达成了共识。"}]', '["agreement","unanimity","accord","harmony"]', '["disagreement","dissent","discord","conflict"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('consequence', '/ˈkɒnsɪkwəns/', 'noun', 'A result or effect of an action or condition; importance or relevance', '结果；后果；重要性', 3, 3200, '["ielts"]', '源自拉丁语 consequentia，con-（跟随）+ sequi（跟随），字面意为"跟随而来的事物"', '[{"en":"Global warming will have serious consequences for future generations.","cn":"全球变暖将对后代产生严重后果。"},{"en":"The government must consider the economic consequences of its policies.","cn":"政府必须考虑其政策的经济后果。"}]', '["result","outcome","effect","repercussion"]', '["cause","origin","source"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('conservation', '/ˌkɒnsəˈveɪʃn/', 'noun', 'The protection and preservation of the natural environment; the act of preventing waste', '保护；保存；节约；守恒', 3, 4100, '["ielts"]', '源自拉丁语 conservatio，con-（完全）+ servare（保护、保存），字面意为"完整保存的行为"', '[{"en":"Wildlife conservation is a priority for many environmental organisations.","cn":"野生动物保护是许多环保组织的首要任务。"},{"en":"Energy conservation measures can significantly reduce household expenses.","cn":"节能措施可以显著减少家庭开支。"}]', '["preservation","protection","safeguarding","maintenance"]', '["destruction","waste","neglect","exploitation"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('consolidate', '/kənˈsɒlɪdeɪt/', 'verb', 'To make something stronger or more solid; to combine several things into a single entity', '巩固；加强；合并；统一', 4, 5200, '["ielts"]', '源自拉丁语 consolidare，con-（完全）+ solidare（使坚固），solidus（坚固）派生', '[{"en":"The company plans to consolidate its position as the market leader.","cn":"该公司计划巩固其市场领导者的地位。"},{"en":"Several small schools were consolidated into one larger institution.","cn":"几所小学校被合并为一所更大的机构。"}]', '["strengthen","merge","unify","reinforce"]', '["weaken","divide","separate","fragment"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('constitute', '/ˈkɒnstɪtjuːt/', 'verb', 'To be a part of a whole; to amount to; to establish or create by legal authority', '构成；组成；设立；被视为', 4, 4300, '["ielts"]', '源自拉丁语 constituere，con-（共同）+ statuere（建立），字面意为"共同建立或构成"', '[{"en":"Women constitute nearly half of the total workforce in the country.","cn":"女性占该国总劳动力的近一半。"},{"en":"The agreement constitutes a significant step towards peace in the region.","cn":"该协议构成了该地区迈向和平的重要一步。"}]', '["comprise","form","compose","establish"]', '["dissolve","exclude","dismantle"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('constraint', '/kənˈstreɪnt/', 'noun', 'A limitation or restriction; the threat or use of force to prevent something', '约束；限制；限制因素；克制', 4, 4600, '["ielts"]', '源自古法语 constraindre，源自拉丁语 constringere，con-（共同）+ stringere（拉紧），字面意为"被拉紧束缚"', '[{"en":"Financial constraints prevent many students from pursuing higher education.","cn":"经济限制使许多学生无法接受高等教育。"},{"en":"The project was completed on time despite severe resource constraints.","cn":"尽管资源严重受限，该项目仍按时完成。"}]', '["restriction","limitation","restraint","hindrance"]', '["freedom","liberty","abundance","excess"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('consult', '/kənˈsʌlt/', 'verb', 'To seek information or advice from someone with expertise; to refer to a source of information', '咨询；请教；查阅；商讨', 3, 3800, '["ielts"]', '源自拉丁语 consultare，consulere（商议）的频繁形式，意为"反复寻求建议"', '[{"en":"You should consult a doctor if your symptoms persist for more than a week.","cn":"如果症状持续超过一周，你应该咨询医生。"},{"en":"The committee consulted with experts before making its final recommendation.","cn":"委员会在提出最终建议前征询了专家意见。"}]', '["seek advice","refer to","discuss","deliberate"]', '["ignore","disregard","neglect"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('consumer', '/kənˈsjuːmə/', 'noun', 'A person who purchases goods or uses services; an organism that feeds on other organisms', '消费者；用户', 3, 3400, '["ielts"]', '源自拉丁语 consumere，con-（完全）+ sumere（拿取），字面意为"完全消耗资源的人"', '[{"en":"Consumer spending accounts for a large proportion of the national economy.","cn":"消费支出占国民经济的很大比例。"},{"en":"Consumer protection laws are designed to prevent unfair business practices.","cn":"消费者保护法旨在防止不公平的商业行为。"}]', '["buyer","customer","purchaser","user"]', '["producer","manufacturer","supplier"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('contemporary', '/kənˈtemprəri/', 'adjective', 'Living or occurring at the same time; belonging to the present period; modern', '当代的；同时代的；现代的', 4, 4200, '["ielts"]', '源自拉丁语 contemporarius，con-（共同）+ tempus（时间），字面意为"处于同一时代的"', '[{"en":"Contemporary art often challenges traditional notions of beauty and aesthetics.","cn":"当代艺术常常挑战传统的美学和审美观念。"},{"en":"Shakespeare and Cervantes were contemporary writers, though they likely never met.","cn":"莎士比亚和塞万提斯是同时代的作家，尽管他们可能从未见过面。"}]', '["modern","current","present-day","concurrent"]', '["ancient","historical","outdated","traditional"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('contend', '/kənˈtend/', 'verb', 'To struggle to deal with a difficulty; to assert something as a position in an argument', '竞争；主张；声称；应对', 4, 5400, '["ielts"]', '源自拉丁语 contendere，con-（完全）+ tendere（伸展），字面意为"全力伸张、奋力争取"', '[{"en":"Critics contend that the new policy will disproportionately affect low-income families.","cn":"批评者声称新政策将对低收入家庭造成不成比例的影响。"},{"en":"Athletes from around the world will contend for medals at the championship.","cn":"来自世界各地的运动员将在锦标赛上争夺奖牌。"}]', '["argue","assert","compete","struggle"]', '["concede","agree","yield","surrender"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('context', '/ˈkɒntekst/', 'noun', 'The circumstances that form the setting for an event or idea; the parts surrounding a passage', '背景；环境；上下文；语境', 3, 3500, '["ielts"]', '源自拉丁语 contextus，con-（共同）+ texere（编织），字面意为"编织在一起的整体环境"', '[{"en":"It is important to understand historical events within their proper context.","cn":"在适当的历史背景下理解事件很重要。"},{"en":"Words can have different meanings depending on the context in which they are used.","cn":"词语的含义可能因使用语境不同而不同。"}]', '["setting","background","environment","framework"]', '["isolation","irrelevance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('contingent', '/kənˈtɪndʒənt/', 'adjective', 'Subject to chance; occurring by chance; dependent on certain conditions', '取决于…的；偶然的；视情况而定的', 5, 6200, '["ielts"]', '源自拉丁语 contingens，contingere 的现在分词，con-（共同）+ tangere（触碰），字面意为"碰巧发生的"', '[{"en":"The success of the project is contingent on securing adequate funding.","cn":"项目的成功取决于能否获得充足的资金。"},{"en":"Many economic outcomes are contingent on global market conditions.","cn":"许多经济结果取决于全球市场状况。"}]', '["dependent","conditional","provisional","subject to"]', '["certain","inevitable","independent","definite"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('contradict', '/ˌkɒntrəˈdɪkt/', 'verb', 'To deny the truth of a statement by asserting the opposite; to be in conflict with', '反驳；与…矛盾；与…抵触', 4, 4600, '["ielts"]', '源自拉丁语 contradicere，contra-（反对）+ dicere（说），字面意为"说出反对的话"', '[{"en":"The findings of the new study contradict earlier research on the topic.","cn":"新研究的发现与该主题早期研究相矛盾。"},{"en":"Witnesses gave statements that contradicted each other.","cn":"证人们的陈述互相矛盾。"}]', '["deny","oppose","refute","counter"]', '["confirm","support","agree","corroborate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('controversial', '/ˌkɒntrəˈvɜːʃl/', 'adjective', 'Giving rise to public disagreement; relating to or causing controversy', '有争议的；引起争论的', 4, 4300, '["ielts"]', '源自拉丁语 controversia，contra-（反对）+ versare（转动），字面意为"各方转向不同方向的争论"', '[{"en":"The proposed tax reform has been highly controversial among economists.","cn":"拟议的税制改革在经济学家中一直备受争议。"},{"en":"Capital punishment remains a controversial issue in many societies.","cn":"死刑在许多社会仍然是一个有争议的问题。"}]', '["debatable","contentious","disputed","polarising"]', '["uncontroversial","agreed","undisputed","accepted"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('convention', '/kənˈvenʃn/', 'noun', 'A way in which something is usually done; a large meeting or conference; an international agreement', '惯例；大会；公约；常规', 3, 4000, '["ielts"]', '源自拉丁语 conventio，convenire（聚会）的过去分词，con-（共同）+ venire（来），字面意为"共同来到"', '[{"en":"Social conventions vary significantly between different cultures.","cn":"社会惯例在不同文化之间差异显著。"},{"en":"The international convention on climate change was signed by over 190 countries.","cn":"关于气候变化的国际公约由190多个国家签署。"}]', '["custom","tradition","conference","treaty"]', '["innovation","deviation","irregularity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('converge', '/kənˈvɜːdʒ/', 'verb', 'To come together from different directions to meet at a common point; to tend towards the same conclusion', '汇聚；趋同；聚集；会合', 4, 5600, '["ielts"]', '源自拉丁语 convergere，con-（共同）+ vergere（倾向），字面意为"共同倾向一个点"', '[{"en":"Several major roads converge at the city centre, causing heavy traffic.","cn":"几条主要道路在市中心汇合，造成交通拥堵。"},{"en":"Scientists from different disciplines have converged on similar conclusions.","cn":"不同学科的科学家得出了相似的结论。"}]', '["meet","merge","unite","gather"]', '["diverge","separate","split","scatter"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('converse', '/kənˈvɜːs/', 'verb', 'To engage in conversation; to talk informally with someone', '交谈；谈话；相反地', 4, 5300, '["ielts"]', '源自拉丁语 conversari，con-（共同）+ versare（转动），字面意为"在一起交流往来"', '[{"en":"The delegates conversed in small groups during the break.","cn":"代表们在休息期间分成小组交谈。"},{"en":"She was able to converse fluently in three different languages.","cn":"她能用三种不同的语言流利地交谈。"}]', '["talk","discuss","communicate","chat"]', '["silence","ignore","avoid"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('convey', '/kənˈveɪ/', 'verb', 'To transport or carry to a place; to communicate or make known; to transfer legally', '传达；运输；传递；转让', 4, 4400, '["ielts"]', '源自拉丁语 convehere，con-（共同）+ vehere（运送），字面意为"一起运送"', '[{"en":"The painting conveys a deep sense of loneliness and isolation.","cn":"这幅画传达了一种深刻的孤独感和隔离感。"},{"en":"Please convey my best wishes to your family.","cn":"请向你的家人转达我最美好的祝愿。"}]', '["communicate","transport","transmit","express"]', '["withhold","conceal","retain","keep"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('convince', '/kənˈvɪns/', 'verb', 'To cause someone to believe firmly in the truth of something; to persuade', '说服；使确信；使信服', 3, 3600, '["ielts"]', '源自拉丁语 convincere，con-（完全）+ vincere（征服），字面意为"完全征服对方的疑虑"', '[{"en":"The evidence convinced the jury of the defendant''s guilt.","cn":"证据使陪审团确信被告有罪。"},{"en":"She tried to convince her parents to let her study abroad.","cn":"她试图说服父母让她出国留学。"}]', '["persuade","assure","satisfy","sway"]', '["dissuade","discourage","deter","disillusion"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cooperate', '/kəʊˈɒpəreɪt/', 'verb', 'To work jointly towards the same end; to assist or comply with a request', '合作；协作；配合', 3, 3700, '["ielts"]', '源自拉丁语 cooperari，co-（共同）+ operari（工作），字面意为"共同工作"', '[{"en":"Countries must cooperate to address global challenges such as climate change.","cn":"各国必须合作应对气候变化等全球性挑战。"},{"en":"The witness agreed to cooperate with the police investigation.","cn":"证人同意配合警方调查。"}]', '["collaborate","work together","coordinate","assist"]', '["oppose","compete","obstruct","hinder"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('coordinate', '/kəʈˈɔːdɪneɪt/', 'verb', 'To bring different elements into a relationship that ensures efficiency; to organise activities', '协调；使配合；统筹', 4, 4500, '["ielts"]', '源自拉丁语 coordinare，co-（共同）+ ordinare（排列），字面意为"使各部分有序配合"', '[{"en":"The agency coordinates relief efforts during natural disasters.","cn":"该机构在自然灾害期间协调救援工作。"},{"en":"It is essential to coordinate the schedules of all team members.","cn":"协调所有团队成员的日程安排至关重要。"}]', '["organise","harmonise","synchronise","manage"]', '["disorganise","disrupt","neglect"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('core', '/kɔː/', 'noun', 'The central or most important part of something; the tough central part of a fruit', '核心；要点；中心；地核', 3, 3300, '["ielts"]', '源自古英语 coren，可能与 corn（谷物）相关，原指"果实的坚硬中心部分"', '[{"en":"The core values of the organisation include integrity, respect, and innovation.","cn":"该组织的核心价值观包括诚信、尊重和创新。"},{"en":"At the core of the debate is the question of individual freedom versus collective security.","cn":"这场辩论的核心是个人自由与集体安全的问题。"}]', '["centre","heart","essence","nucleus"]', '["periphery","surface","exterior","margin"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('corporate', '/ˈkɔːpərət/', 'adjective', 'Relating to a large company or group; shared by all members of a group', '公司的；企业的；团体的；法人的', 3, 4100, '["ielts"]', '源自拉丁语 corporatus，corpus（身体、团体）派生，字面意为"形成一个整体的团体"', '[{"en":"Corporate social responsibility has become a key concern for modern businesses.","cn":"企业社会责任已成为现代企业关注的焦点。"},{"en":"The merger created one of the largest corporate entities in the industry.","cn":"这次合并创建了该行业最大的企业实体之一。"}]', '["business","company","commercial","enterprise"]', '["individual","personal","private","nonprofit"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('correspond', '/ˌkɒrɪˈspɒnd/', 'verb', 'To have a close similarity; to match or agree almost exactly; to communicate by letter', '相符；相当；通信；对应', 4, 4300, '["ielts"]', '源自拉丁语 correspondere，cor-（共同）+ respondere（回应），字面意为"相互回应、一致"', '[{"en":"The results of the experiment correspond closely with our original hypothesis.","cn":"实验结果与我们最初的假设高度吻合。"},{"en":"She corresponded with colleagues around the world via email.","cn":"她通过电子邮件与世界各地的同事通信。"}]', '["match","agree","relate","communicate"]', '["differ","contradict","disagree","conflict"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('credible', '/ˈkredɪbl/', 'adjective', 'Able to be believed; convincing; capable of being trusted', '可信的；可靠的；令人信服的', 4, 4900, '["ielts"]', '源自拉丁语 credibilis，credere（相信）派生，字面意为"值得相信的"', '[{"en":"The witness provided a credible account of the events that took place.","cn":"证人对所发生的事件提供了可信的描述。"},{"en":"Without credible evidence, the allegations cannot be taken seriously.","cn":"没有可信的证据，这些指控不能被认真对待。"}]', '["believable","trustworthy","plausible","reliable"]', '["incredible","implausible","unbelievable","doubtful"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('criteria', '/kraɪˈtɪəriə/', 'noun', 'Plural of criterion; the standards or principles by which something is judged or evaluated', '标准；准则；评判依据（criterion 的复数）', 3, 3800, '["ielts"]', '源自希腊语 kriterion（判断标准），krinein（判断、区分）派生，字面意为"用于判断事物的标准"', '[{"en":"Applicants must meet certain criteria to be eligible for the scholarship.","cn":"申请者必须满足一定标准才有资格获得奖学金。"},{"en":"The criteria for assessing student performance have been updated this year.","cn":"今年评估学生表现的标准已更新。"}]', '["standards","benchmarks","requirements","guidelines"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('crucial', '/ˈkruːʃl/', 'adjective', 'Decisive or critical, especially in the success or failure of something; of great importance', '关键的；决定性的；至关重要的', 3, 3500, '["ielts"]', '源自拉丁语 crux（十字架），在交叉路口做选择，引申为"决定性时刻的、关键的"', '[{"en":"Education plays a crucial role in reducing poverty and inequality.","cn":"教育在减少贫困和不平等方面发挥着关键作用。"},{"en":"The next few weeks will be crucial for the success of the project.","cn":"接下来几周对项目的成功至关重要。"}]', '["critical","vital","essential","pivotal"]', '["trivial","insignificant","unimportant","minor"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('culminate', '/ˈkʌlmɪneɪt/', 'verb', 'To reach a climax or point of highest development; to end in a specified result', '达到顶点；以…告终； culminates', 5, 5800, '["ielts"]', '源自拉丁语 culminare，culmen（顶点）派生，字面意为"到达最高点"', '[{"en":"Years of research culminated in the discovery of a new treatment for the disease.","cn":"多年的研究最终发现了该疾病的新疗法。"},{"en":"The festival will culminate with a grand fireworks display on the final night.","cn":"节日将在最后一晚以盛大的烟火表演达到高潮。"}]', '["climax","peak","conclude","terminate"]', '["begin","commence","initiate","start"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cultivate', '/ˈkʌltɪveɪt/', 'verb', 'To prepare and use land for growing crops; to foster the growth of a skill or quality', '耕种；培养；培育；陶冶', 4, 4700, '["ielts"]', '源自拉丁语 cultivare，cultura（耕种、培养）派生，colere（耕作）的词根，字面意为"用心培育"', '[{"en":"Farmers cultivate rice in the fertile valleys of the region.","cn":"农民在该地区肥沃的山谷中种植水稻。"},{"en":"Parents should cultivate a love of reading in their children from an early age.","cn":"父母应从孩子幼年时就培养他们对阅读的热爱。"}]', '["nurture","foster","develop","grow"]', '["neglect","destroy","abandon","suppress"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cumulative', '/ˈkjuːmjʊlətɪv/', 'adjective', 'Increasing or growing by accumulation or successive additions', '累积的；渐增的；累计的', 4, 5500, '["ielts"]', '源自拉丁语 cumulativus，cumulus（堆、堆积）派生，字面意为"不断堆积增加的"', '[{"en":"The cumulative effect of air pollution on health is a growing concern.","cn":"空气污染对健康的累积影响日益引起关注。"},{"en":"Students are assessed through cumulative examinations that cover all topics studied.","cn":"学生通过涵盖所有已学内容的累积考试进行评估。"}]', '["accumulative","aggregate","collective","additive"]', '["individual","single","decreasing","reducing"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('curriculum', '/kəˈrɪkjʊləm/', 'noun', 'The subjects comprising a course of study in a school or college', '课程；教学大纲；全部课程', 4, 4400, '["ielts"]', '源自拉丁语 curriculum（跑道、跑道上的赛程），currere（跑）派生，字面意为"学习的跑道"', '[{"en":"The national curriculum includes core subjects such as mathematics, science, and English.","cn":"国家课程包括数学、科学和英语等核心科目。"},{"en":"Schools should incorporate digital literacy into their curriculum.","cn":"学校应将数字素养纳入课程体系。"}]', '["syllabus","programme","course of study","subjects"]', '[]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('customary', '/ˈkʌstəməri/', 'adjective', 'According to the customs or usual practices of a particular society, place, or time', '习惯的；惯例的；通常的', 4, 5400, '["ielts"]', '源自拉丁语 consuetudinarius，consuetudo（习惯、惯例）派生，意为"与既定习惯相符的"', '[{"en":"It is customary in many cultures to remove shoes before entering a home.","cn":"在许多文化中，进门前脱鞋是习惯做法。"},{"en":"The customary greeting in Japan involves bowing rather than shaking hands.","cn":"日本的惯例问候方式是鞠躬而非握手。"}]', '["traditional","conventional","usual","habitual"]', '["unusual","unconventional","atypical","rare"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abandon', '/əˈbændən/', 'verb', 'To leave something or someone permanently; to give up completely', '放弃；遗弃；抛弃', 3, 3200, '["toefl"]', '源自法语abandonner，a-（在…之下）+ bandon（管辖权），原意为"置于他人管辖之下"，引申为"放弃"', '[{"en":"The crew was forced to abandon the sinking ship.","cn":"船员被迫弃船逃生。"},{"en":"She abandoned her plans to travel abroad.","cn":"她放弃了出国旅行的计划。"}]', '["forsake","desert","relinquish"]', '["keep","maintain","retain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abnormal', '/æbˈnɔːrml/', 'adjective', 'Deviating from what is normal or typical', '不正常的；反常的；异常的', 3, 4100, '["toefl"]', '前缀ab-（偏离）+ normal（正常的），意为"偏离正常状态的"', '[{"en":"The doctor noticed abnormal cells in the tissue sample.","cn":"医生在组织样本中发现了异常细胞。"},{"en":"Abnormal weather patterns have been observed this year.","cn":"今年观察到了异常的天气模式。"}]', '["unusual","atypical","irregular"]', '["normal","typical","regular"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abstract', '/ˈæbstrækt/', 'adjective', 'Relating to ideas rather than physical objects; not concrete', '抽象的；理论的', 4, 3500, '["toefl"]', '源自拉丁语abstractus，abs-（离开）+ trahere（拉），原意为"被拉离的"，即从具体事物中抽离出来的', '[{"en":"The painting was an abstract composition of colors and shapes.","cn":"这幅画是色彩和形状的抽象组合。"},{"en":"Justice is an abstract concept that is difficult to define.","cn":"正义是一个难以定义的抽象概念。"}]', '["theoretical","conceptual","intangible"]', '["concrete","tangible","real"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('abundant', '/əˈbʌndənt/', 'adjective', 'Existing in large quantities; plentiful', '丰富的；充裕的；大量的', 3, 3800, '["toefl"]', '源自拉丁语abundans，ab-（加强）+ undare（涌出），原意为"大量涌出的"', '[{"en":"The region has abundant natural resources.","cn":"该地区拥有丰富的自然资源。"},{"en":"Evidence of climate change is abundant in scientific literature.","cn":"科学文献中有大量气候变化的证据。"}]', '["plentiful","ample","copious"]', '["scarce","sparse","insufficient"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accessible', '/əkˈsesəbl/', 'adjective', 'Easy to approach, reach, or understand', '可接近的；可进入的；易懂的', 4, 3600, '["toefl"]', '源自拉丁语accessus，ad-（朝向）+ cedere（走），意为"可以走过去的"，引申为"容易到达或理解的"', '[{"en":"The museum is accessible to visitors with disabilities.","cn":"该博物馆对残障人士开放。"},{"en":"The professor made complex theories accessible to students.","cn":"教授使复杂的理论变得通俗易懂。"}]', '["available","obtainable","approachable"]', '["inaccessible","unavailable","unreachable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accomplish', '/əˈkɑːmplɪʃ/', 'verb', 'To achieve or complete something successfully', '完成；实现；达到', 3, 3400, '["toefl"]', '源自拉丁语accomplere，ad-（朝向）+ complere（填满、完成），意为"使之圆满"', '[{"en":"She accomplished her goal of running a marathon.","cn":"她实现了跑马拉松的目标。"},{"en":"The team accomplished the project ahead of schedule.","cn":"团队提前完成了该项目。"}]', '["achieve","attain","fulfill"]', '["fail","abandon","neglect"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accumulate', '/əˈkjuːmjəleɪt/', 'verb', 'To gather or collect over time; to increase gradually', '积累；积聚；逐渐增加', 4, 3900, '["toefl"]', '源自拉丁语accumulare，ad-（朝向）+ cumulus（堆），原意为"堆在一起"', '[{"en":"Dust tends to accumulate on unused furniture.","cn":"灰尘容易在不用的家具上积聚。"},{"en":"He accumulated a vast collection of rare books over the years.","cn":"多年来他积累了大量珍稀书籍。"}]', '["gather","amass","collect"]', '["disperse","dissipate","scatter"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('accurate', '/ˈækjərət/', 'adjective', 'Correct in all details; exact and precise', '准确的；精确的；正确的', 3, 3100, '["toefl"]', '源自拉丁语accuratus，ad-（朝向）+ cura（关心、注意），原意为"用心做的"', '[{"en":"The survey provided accurate data about consumer behavior.","cn":"该调查提供了关于消费者行为的准确数据。"},{"en":"It is important to keep accurate records of all transactions.","cn":"保留所有交易的准确记录非常重要。"}]', '["precise","exact","correct"]', '["inaccurate","incorrect","wrong"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('acknowledge', '/əkˈnɑːlɪdʒ/', 'verb', 'To accept or admit the existence or truth of something', '承认；认可；致谢', 4, 3300, '["toefl"]', '由acknowledge构成，ac-（朝向）+ knowledge（知识），原意为"使人知晓"，引申为"承认真相"', '[{"en":"The company acknowledged that errors had been made.","cn":"公司承认犯了错误。"},{"en":"She is widely acknowledged as the leading expert in her field.","cn":"她被广泛认为是该领域的首席专家。"}]', '["admit","recognize","concede"]', '["deny","reject","dispute"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adapt', '/əˈdæpt/', 'verb', 'To change to fit new conditions or circumstances', '适应；改编；改造', 3, 3250, '["toefl"]', '源自拉丁语adaptare，ad-（朝向）+ aptare（使适合），意为"使之适应"', '[{"en":"Animals must adapt to changes in their environment to survive.","cn":"动物必须适应环境变化才能生存。"},{"en":"The novel was adapted into a successful film.","cn":"这部小说被改编成了一部成功的电影。"}]', '["adjust","accommodate","modify"]', '["resist","remain","stay"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adequate', '/ˈædɪkwət/', 'adjective', 'Sufficient or satisfactory for a particular purpose', '足够的；充分的；适当的', 3, 3700, '["toefl"]', '源自拉丁语adaequatus，ad-（朝向）+ aequare（使相等），原意为"使与需求相等"', '[{"en":"The school does not have adequate funding for new equipment.","cn":"学校没有足够的资金购买新设备。"},{"en":"Is the lighting adequate for reading?","cn":"光线够看书吗？"}]', '["sufficient","enough","satisfactory"]', '["inadequate","insufficient","lacking"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adjacent', '/əˈdʒeɪsnt/', 'adjective', 'Next to or adjoining something else; nearby', '邻近的；毗连的；紧挨的', 4, 4800, '["toefl"]', '源自拉丁语adjacens，ad-（朝向）+ jacere（躺），原意为"躺在旁边的"', '[{"en":"The hotel is adjacent to the convention center.","cn":"酒店毗邻会议中心。"},{"en":"Adjacent rooms were combined to create a larger space.","cn":"相邻的房间被合并以创造更大的空间。"}]', '["neighboring","adjoining","nearby"]', '["distant","remote","far"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adjust', '/əˈdʒʌst/', 'verb', 'To change something slightly to make it correct or suitable', '调整；调节；适应', 3, 3150, '["toefl"]', '源自法语ajuster，a-（朝向）+ juste（正确的），原意为"使之正确"', '[{"en":"You can adjust the height of the chair to suit your needs.","cn":"你可以调整椅子的高度以适应你的需要。"},{"en":"It took time for her to adjust to the new culture.","cn":"她花了一些时间来适应新文化。"}]', '["modify","regulate","adapt"]', '["disturb","disarrange","upset"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('administer', '/ədˈmɪnɪstər/', 'verb', 'To manage or be in charge of; to give or apply formally', '管理；执行；给予', 4, 4200, '["toefl"]', '源自拉丁语administrare，ad-（朝向）+ ministrare（服务），原意为"为…提供服务和管理"', '[{"en":"The committee administers the scholarship program.","cn":"委员会管理奖学金项目。"},{"en":"The nurse administered the medication to the patient.","cn":"护士给病人用药。"}]', '["manage","supervise","direct"]', '["neglect","disorganize","mismanage"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('adolescent', '/ˌædəˈlesnt/', 'noun', 'A young person developing from a child into an adult', '青少年；青春期的', 4, 4500, '["toefl"]', '源自拉丁语adolescens，adolescere（成长），ad-（朝向）+ alescere（生长），意为"正在成长的人"', '[{"en":"Adolescents often experience significant emotional changes.","cn":"青少年经常经历重大的情感变化。"},{"en":"The program is designed specifically for adolescent learners.","cn":"该项目专门为青少年学习者设计。"}]', '["teenager","youth","juvenile"]', '["adult","child","elder"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('advocate', '/ˈædvəkeɪt/', 'verb', 'To publicly support or recommend a particular cause or policy', '提倡；拥护；支持', 4, 3800, '["toefl"]', '源自拉丁语advocare，ad-（朝向）+ vocare（呼喊），原意为"为某人呼喊助威"，引申为"公开支持"', '[{"en":"Many scientists advocate for stricter environmental regulations.","cn":"许多科学家提倡更严格的环境法规。"},{"en":"She advocates equal rights for all citizens.","cn":"她倡导所有公民享有平等权利。"}]', '["support","promote","champion"]', '["oppose","resist","condemn"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('agenda', '/əˈdʒendə/', 'noun', 'A list of items to be discussed at a meeting; a plan of things to do', '议程；议事日程；计划', 3, 3400, '["toefl"]', '源自拉丁语agendum，agere（做）的中性动名词复数，原意为"待做的事项"', '[{"en":"The first item on the agenda is the budget review.","cn":"议程上的第一项是预算审查。"},{"en":"Environmental protection is high on the government''s agenda.","cn":"环境保护在政府议程中占据重要位置。"}]', '["schedule","program","plan"]', '["disorder","chaos","confusion"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aggregate', '/ˈæɡrɪɡət/', 'noun', 'A whole formed by combining several elements; a total', '总计；合计；聚合体', 5, 5200, '["toefl"]', '源自拉丁语aggregare，ad-（朝向）+ gregare（使成群），原意为"使聚集在一起"', '[{"en":"The aggregate score determines the final ranking.","cn":"总分决定最终排名。"},{"en":"Researchers studied the aggregate data from all participating schools.","cn":"研究人员研究了所有参与学校的汇总数据。"}]', '["total","sum","combination"]', '["individual","unit","single"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aid', '/eɪd/', 'noun', 'Help or support; financial or material assistance', '援助；帮助；辅助', 3, 3050, '["toefl"]', '源自古法语aide，源自拉丁语adjutare，ad-（朝向）+ juvare（帮助），意为"给予帮助"', '[{"en":"The organization provides aid to refugees around the world.","cn":"该组织向世界各地的难民提供援助。"},{"en":"Visual aids can greatly enhance a presentation.","cn":"视觉辅助工具可以极大地增强演讲效果。"}]', '["help","assistance","support"]', '["hindrance","obstacle","impediment"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('align', '/əˈlaɪn/', 'verb', 'To place in a straight line or correct position; to bring into agreement', '对齐；排列；使一致', 4, 4000, '["toefl"]', '源自法语aligner，a-（朝向）+ ligne（线），原意为"排成一条线"', '[{"en":"The wheels need to be aligned properly for safe driving.","cn":"车轮需要正确对齐以确保安全驾驶。"},{"en":"The company''s goals must align with its core values.","cn":"公司的目标必须与其核心价值观一致。"}]', '["line up","arrange","coordinate"]', '["misalign","disarrange","disorder"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('allocate', '/ˈæləkeɪt/', 'verb', 'To distribute resources or duties for a particular purpose', '分配；拨出；分派', 4, 4100, '["toefl"]', '源自拉丁语allocare，ad-（朝向）+ locare（放置），原意为"放置到指定位置"，引申为"分配资源"', '[{"en":"The government allocates funds for education each year.","cn":"政府每年拨款用于教育。"},{"en":"Time should be allocated carefully to complete all tasks.","cn":"应仔细分配时间以完成所有任务。"}]', '["distribute","assign","apportion"]', '["collect","gather","accumulate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('alter', '/ˈɔːltər/', 'verb', 'To change or cause to change in character or composition', '改变；修改；变更', 3, 3500, '["toefl"]', '源自拉丁语alterare，alter（其他的），意为"使变成其他的"', '[{"en":"The renovations significantly altered the appearance of the building.","cn":"翻新工程大大改变了建筑的外观。"},{"en":"Climate change may alter migration patterns of birds.","cn":"气候变化可能改变鸟类的迁徙模式。"}]', '["change","modify","transform"]', '["preserve","maintain","retain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('alternative', '/ɔːlˈtɜːrnətɪv/', 'noun', 'One of two or more available possibilities', '替代选择；可供选择的', 3, 3200, '["toefl"]', '源自拉丁语alternativus，alternare（交替），alter（其他的），意为"轮流的其他选择"', '[{"en":"Public transportation is a viable alternative to driving.","cn":"公共交通是开车出行的可行替代方案。"},{"en":"We need to explore alternative energy sources.","cn":"我们需要探索替代能源。"}]', '["option","substitute","replacement"]', '["necessity","obligation","requirement"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ambitious', '/æmˈbɪʃəs/', 'adjective', 'Having a strong desire for success or achievement', '有雄心的；有抱负的；费力的', 3, 3900, '["toefl"]', '源自拉丁语ambitiosus，ambitio（四处走动拉票），ambi-（周围）+ ire（走），原意为"到处走动争取支持"', '[{"en":"She is an ambitious student who wants to attend a top university.","cn":"她是一个志向远大的学生，想上顶尖大学。"},{"en":"The project was ambitious in scope and required years of work.","cn":"该项目规模宏大，需要数年的工作。"}]', '["aspiring","driven","determined"]', '["unambitious","lazy","indifferent"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('ample', '/ˈæmpl/', 'adjective', 'Enough or more than enough; plentiful', '充足的；丰富的；宽敞的', 3, 4600, '["toefl"]', '源自拉丁语amplus（大的、宽广的），意为"空间或数量充裕的"', '[{"en":"There was ample time to finish the exam.","cn":"有充足的时间完成考试。"},{"en":"The hotel room was ample in size and well furnished.","cn":"酒店房间宽敞且家具齐全。"}]', '["plentiful","abundant","sufficient"]', '["scant","insufficient","meager"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('analyze', '/ˈænəlaɪz/', 'verb', 'To examine something methodically and in detail', '分析；解析；剖析', 3, 3100, '["toefl"]', '源自希腊语analyein，ana-（向上、彻底）+ lyein（解开），原意为"彻底拆解以了解组成"', '[{"en":"Scientists analyze soil samples to determine pollution levels.","cn":"科学家分析土壤样本以确定污染程度。"},{"en":"Students are asked to analyze the themes in the novel.","cn":"学生被要求分析小说中的主题。"}]', '["examine","study","investigate"]', '["synthesize","combine","ignore"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('annual', '/ˈænjuəl/', 'adjective', 'Occurring once every year; lasting for a year', '年度的；每年的；一年生的', 3, 3300, '["toefl"]', '源自拉丁语annus（年），ann-（年）+ -al（…的），意为"与年有关的"', '[{"en":"The company publishes an annual report on its financial performance.","cn":"公司发布年度财务报告。"},{"en":"The annual migration of monarch butterflies covers thousands of miles.","cn":"帝王蝶每年的迁徙覆盖数千英里。"}]', '["yearly","annual","perennial"]', '["monthly","weekly","daily"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('anticipate', '/ænˈtɪsɪpeɪt/', 'verb', 'To expect or predict; to look forward to', '预期；预料；期望', 4, 3700, '["toefl"]', '源自拉丁语anticipare，ante-（之前）+ capere（拿取），原意为"提前拿取"，即预先考虑到', '[{"en":"We anticipate that the project will be completed by June.","cn":"我们预计该项目将在六月完成。"},{"en":"The demand exceeded what analysts had anticipated.","cn":"需求超出了分析师的预期。"}]', '["expect","foresee","predict"]', '["doubt","surprise","unexpected"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('apparent', '/əˈpærənt/', 'adjective', 'Clearly visible or understood; obvious', '明显的；显而易见的；表面上的', 3, 3500, '["toefl"]', '源自拉丁语apparens，apparere（出现），ad-（朝向）+ parere（出现），意为"看得见的、明显的"', '[{"en":"It was apparent that the experiment had failed.","cn":"很明显实验失败了。"},{"en":"The apparent simplicity of the task was misleading.","cn":"任务表面上的简单性具有误导性。"}]', '["obvious","evident","clear"]', '["hidden","unclear","obscure"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('appendix', '/əˈpendɪks/', 'noun', 'A section of additional information at the end of a book or document', '附录；附件', 4, 5500, '["toefl"]', '源自拉丁语appendere，ad-（朝向）+ pendere（悬挂），原意为"悬挂在旁边的东西"，引申为"附加内容"', '[{"en":"The appendix contains a detailed list of all research participants.","cn":"附录包含所有研究参与者的详细名单。"},{"en":"Refer to Appendix B for the survey questionnaire.","cn":"请参阅附录B中的调查问卷。"}]', '["supplement","addendum","attachment"]', '["main text","body","core"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('applicable', '/əˈplɪkəbl/', 'adjective', 'Relevant or appropriate to a particular situation', '适用的；适当的；可应用的', 4, 4200, '["toefl"]', '源自拉丁语applicare，ad-（朝向）+ plicare（折叠、贴合），意为"可以贴合到…上的"', '[{"en":"This rule is applicable to all employees without exception.","cn":"此规则适用于所有员工，无一例外。"},{"en":"The findings are not applicable to other populations.","cn":"这些发现不适用于其他人群。"}]', '["relevant","appropriate","suitable"]', '["irrelevant","inapplicable","unsuitable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('approach', '/əˈproʊtʃ/', 'verb', 'To come near to; to deal with something in a particular way', '接近；处理；方法', 3, 3050, '["toefl"]', '源自拉丁语appropiare，ad-（朝向）+ prope（近），原意为"使靠近"', '[{"en":"Researchers used a new approach to solve the problem.","cn":"研究人员用新方法解决了这个问题。"},{"en":"As winter approaches, the days become shorter.","cn":"随着冬天临近，白天变得更短。"}]', '["method","strategy","near"]', '["avoid","retreat","distance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('appropriate', '/əˈproʊpriət/', 'adjective', 'Suitable or proper in the circumstances', '适当的；合适的；恰当的', 3, 3200, '["toefl"]', '源自拉丁语appropriare，ad-（朝向）+ proprius（自己的），原意为"使成为自己的"，引申为"恰如其分的"', '[{"en":"Casual clothing is not appropriate for a formal dinner.","cn":"休闲装不适合正式晚宴。"},{"en":"The teacher chose an appropriate reading level for the class.","cn":"老师为班级选择了合适的阅读水平。"}]', '["suitable","fitting","proper"]', '["inappropriate","unsuitable","improper"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('approximate', '/əˈprɑːksɪmət/', 'adjective', 'Close to the actual but not completely accurate', '大约的；近似的', 4, 4500, '["toefl"]', '源自拉丁语approximare，ad-（朝向）+ proximare（靠近），原意为"最靠近的"', '[{"en":"The approximate cost of the project is two million dollars.","cn":"该项目的大约费用是两百万美元。"},{"en":"Can you give me an approximate time of arrival?","cn":"你能给我一个大致的到达时间吗？"}]', '["rough","estimated","close"]', '["exact","precise","accurate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('arbitrary', '/ˈɑːrbɪtreri/', 'adjective', 'Based on random choice rather than reason; unreasonable', '任意的；武断的；专横的', 5, 4900, '["toefl"]', '源自拉丁语arbitrarius，arbiter（裁判者），原意为"由裁判自行决定的"，引申为"主观武断的"', '[{"en":"The decision seemed arbitrary and unfair to the employees.","cn":"这个决定对员工来说似乎武断且不公正。"},{"en":"There is no arbitrary limit on the number of attempts.","cn":"尝试次数没有随意设定的限制。"}]', '["random","capricious","subjective"]', '["rational","logical","reasoned"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('archaic', '/ɑːrˈkeɪɪk/', 'adjective', 'Very old or old-fashioned; belonging to an earlier period', '过时的；古老的；陈旧的', 5, 5400, '["toefl"]', '源自希腊语archaikos，archaios（古代的），arche（开始、起源），意为"属于早期的"', '[{"en":"The museum displays archaic tools used by early settlers.","cn":"博物馆展示早期定居者使用的古老工具。"},{"en":"Some archaic laws are still on the books but rarely enforced.","cn":"一些过时的法律仍然存在于法典中但很少执行。"}]', '["antiquated","obsolete","ancient"]', '["modern","contemporary","current"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('area', '/ˈeriə/', 'noun', 'A region or part of a town, country, or the world; a subject or field', '地区；领域；面积', 3, 3000, '["toefl"]', '源自拉丁语area（空地、打谷场），原意为"开阔的空间"', '[{"en":"This area is known for its diverse wildlife.","cn":"这个地区以其多样的野生动物而闻名。"},{"en":"She is an expert in the area of molecular biology.","cn":"她是分子生物学领域的专家。"}]', '["region","zone","field"]', '["center","core","point"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('argue', '/ˈɑːrɡjuː/', 'verb', 'To give reasons in support of an idea or theory; to dispute', '论证；争论；辩论', 3, 3100, '["toefl"]', '源自拉丁语arguere（证明、表明），原意为"用证据说明"，引申为"提出理由"', '[{"en":"Scientists argue that climate change is accelerating.","cn":"科学家认为气候变化正在加速。"},{"en":"The two sides argued about the best solution.","cn":"双方就最佳解决方案进行了辩论。"}]', '["debate","contend","assert"]', '["agree","accept","concede"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('arise', '/əˈraɪz/', 'verb', 'To emerge or become apparent; to come into being', '出现；产生；兴起', 3, 3400, '["toefl"]', '由arise构成，a-（向上）+ rise（升起），原意为"升起"，引申为"出现或发生"', '[{"en":"New challenges arise as technology advances.","cn":"随着技术进步，新的挑战不断出现。"},{"en":"A conflict arose between the two departments.","cn":"两个部门之间产生了冲突。"}]', '["emerge","appear","occur"]', '["disappear","vanish","cease"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('arrange', '/əˈreɪndʒ/', 'verb', 'To put things in a particular order; to organize or plan', '安排；整理；排列', 3, 3300, '["toefl"]', '源自法语arranger，a-（朝向）+ rang（排列），原意为"排成一排"，引申为"组织安排"', '[{"en":"The books were arranged alphabetically on the shelves.","cn":"书架上的书按字母顺序排列。"},{"en":"They arranged a meeting to discuss the proposal.","cn":"他们安排了一次会议来讨论该提案。"}]', '["organize","order","plan"]', '["disarrange","disorganize","scatter"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assemble', '/əˈsembl/', 'verb', 'To gather together in one place; to fit together the parts of', '集合；组装；汇集', 3, 3600, '["toefl"]', '源自法语assembler，a-（朝向）+ sembler（聚集），源自拉丁语simul（一起），意为"聚集在一起"', '[{"en":"The students assembled in the auditorium for the ceremony.","cn":"学生们在礼堂集合参加典礼。"},{"en":"Workers assemble the cars on a production line.","cn":"工人在生产线上组装汽车。"}]', '["gather","collect","construct"]', '["disassemble","scatter","separate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assert', '/əˈsɜːrt/', 'verb', 'To state a fact or belief confidently and forcefully', '断言；主张；维护', 4, 3800, '["toefl"]', '源自拉丁语asserere，ad-（朝向）+ serere（连接），原意为"把…与自己连接起来"，即声明所有权', '[{"en":"The researcher asserted that the data supported her hypothesis.","cn":"研究人员断言数据支持她的假设。"},{"en":"He asserted his right to a fair trial.","cn":"他主张自己有权获得公正审判。"}]', '["declare","claim","affirm"]', '["deny","retract","withdraw"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assess', '/əˈses/', 'verb', 'To evaluate or estimate the nature, quality, or ability of', '评估；评定；估算', 3, 3400, '["toefl"]', '源自拉丁语assidere，ad-（朝向）+ sedere（坐），原意为"坐在旁边协助判断"，后与税收评估相关', '[{"en":"Teachers assess student progress through regular tests.","cn":"教师通过定期考试评估学生进步。"},{"en":"The committee will assess the environmental impact of the project.","cn":"委员会将评估该项目的环境影响。"}]', '["evaluate","appraise","estimate"]', '["ignore","neglect","overlook"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assign', '/əˈsaɪn/', 'verb', 'To allocate a task or responsibility to someone', '分配；指派；指定', 3, 3200, '["toefl"]', '源自拉丁语assignare，ad-（朝向）+ signare（标记），原意为"标记指定给某人"', '[{"en":"The teacher assigned a research paper to each student.","cn":"老师给每个学生分配了一篇研究论文。"},{"en":"A detective was assigned to investigate the case.","cn":"一名侦探被指派调查此案。"}]', '["allocate","appoint","designate"]', '["release","free","discharge"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assist', '/əˈsɪst/', 'verb', 'To help someone by doing work or providing support', '帮助；协助；支援', 3, 3100, '["toefl"]', '源自拉丁语assistere，ad-（朝向）+ sistere（站立），原意为"站在旁边"，引申为"提供帮助"', '[{"en":"The volunteer assisted elderly residents with daily tasks.","cn":"志愿者帮助老年居民处理日常事务。"},{"en":"Technology can assist in the learning process.","cn":"技术可以辅助学习过程。"}]', '["help","aid","support"]', '["hinder","impede","obstruct"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assume', '/əˈsuːm/', 'verb', 'To suppose something is true without proof; to take on responsibility', '假设；承担；假定', 3, 3200, '["toefl"]', '源自拉丁语assumere，ad-（朝向）+ sumere（拿取），原意为"拿来"，引申为"接受某个前提"或"承担"', '[{"en":"Scientists assume that the universe is expanding.","cn":"科学家假设宇宙正在膨胀。"},{"en":"She assumed responsibility for the entire project.","cn":"她承担了整个项目的责任。"}]', '["suppose","presume","undertake"]', '["prove","verify","relinquish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('assure', '/əˈʃʊr/', 'verb', 'To tell someone confidently that something is true; to make certain', '保证；确保；使确信', 3, 3600, '["toefl"]', '源自法语assurer，源自拉丁语ad-（朝向）+ securus（安全的），意为"使某人感到安全"', '[{"en":"The manager assured the team that the deadline would be extended.","cn":"经理向团队保证截止日期将会延长。"},{"en":"I can assure you that all safety measures are in place.","cn":"我可以向你保证所有安全措施都已到位。"}]', '["guarantee","promise","reassure"]', '["worry","threaten","endanger"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('attach', '/əˈtætʃ/', 'verb', 'To fasten or join one thing to another; to assign importance to', '附上；附加；附着', 3, 3300, '["toefl"]', '源自古法语attacher，a-（朝向）+ tache（钉子、扣子），原意为"用钉子固定"', '[{"en":"Please attach your resume to the application form.","cn":"请将简历附在申请表上。"},{"en":"The researcher attached great importance to field observations.","cn":"研究人员非常重视实地观察。"}]', '["fasten","affix","connect"]', '["detach","remove","separate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('attain', '/əˈteɪn/', 'verb', 'To succeed in achieving something; to reach a particular level', '达到；获得；实现', 4, 4000, '["toefl"]', '源自拉丁语attingere，ad-（朝向）+ tangere（触摸），原意为"触及"，引申为"达到目标"', '[{"en":"She attained the highest score in the examination.","cn":"她在考试中获得了最高分。"},{"en":"Many species attain maturity at different ages.","cn":"许多物种在不同年龄达到成熟。"}]', '["achieve","reach","obtain"]', '["fail","lose","miss"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('attempt', '/əˈtempt/', 'verb', 'To make an effort to achieve or complete something', '尝试；试图；企图', 3, 3100, '["toefl"]', '源自拉丁语attemptare，ad-（朝向）+ temptare（试探），原意为"去试探、尝试"', '[{"en":"The climbers attempted to reach the summit before dawn.","cn":"登山者试图在黎明前到达山顶。"},{"en":"This is an attempt to explain the observed phenomena.","cn":"这是试图解释观察到的现象。"}]', '["try","endeavor","strive"]', '["succeed","accomplish","achieve"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('attend', '/əˈtend/', 'verb', 'To be present at; to pay attention to; to deal with', '出席；参加；照料', 3, 3100, '["toefl"]', '源自拉丁语attendere，ad-（朝向）+ tendere（伸展），原意为"把注意力伸向"', '[{"en":"Over 500 delegates attended the conference.","cn":"超过500名代表出席了会议。"},{"en":"Students must attend classes regularly.","cn":"学生必须定期上课。"}]', '["participate","join","observe"]', '["absent","miss","skip"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('attribute', '/əˈtrɪbjuːt/', 'verb', 'To regard something as being caused by; a quality or feature', '归因于；属性；特质', 4, 3600, '["toefl"]', '源自拉丁语attribuere，ad-（朝向）+ tribuere（给予），原意为"把…归于"，引申为"归因"或"属性"', '[{"en":"Scientists attribute the rise in temperatures to greenhouse gases.","cn":"科学家将气温上升归因于温室气体。"},{"en":"Patience is an important attribute for a teacher.","cn":"耐心是教师的重要品质。"}]', '["ascribe","credit","quality"]', '["deny","disclaim","fault"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('authority', '/əˈθɔːrəti/', 'noun', 'The power or right to give orders and enforce obedience; an expert', '权威；权力；当局', 3, 3200, '["toefl"]', '源自拉丁语auctoritas，auctor（创始者、推动者），原意为"创始者的影响力"，引申为"权威和权力"', '[{"en":"The local authorities imposed new regulations on waste disposal.","cn":"地方当局实施了新的废物处理规定。"},{"en":"She is considered an authority on ancient civilizations.","cn":"她被认为是古代文明方面的权威。"}]', '["power","control","expertise"]', '["subordination","weakness","ignorance"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('automate', '/ˈɔːtəmeɪt/', 'verb', 'To make a process operate by automatic equipment', '使自动化；自动操作', 4, 4700, '["toefl"]', '源自希腊语automatos（自动的），auto-（自己）+ matos（运动的），意为"自己运动的"', '[{"en":"The factory automated its production line to increase efficiency.","cn":"工厂自动化了生产线以提高效率。"},{"en":"Many routine tasks can now be automated using software.","cn":"许多常规任务现在可以使用软件自动化。"}]', '["mechanize","computerize","streamline"]', '["manualize","complicate","hinder"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('available', '/əˈveɪləbl/', 'adjective', 'Able to be used or obtained; free to do something', '可用的；可获得的；有空的', 3, 3000, '["toefl"]', '源自法语à valoir（有价值的），a-（朝向）+ valoir（有价值），意为"可以有效利用的"', '[{"en":"Scholarships are available for international students.","cn":"奖学金面向国际学生开放。"},{"en":"The professor is available for consultation during office hours.","cn":"教授在办公时间可以咨询。"}]', '["accessible","obtainable","handy"]', '["unavailable","inaccessible","occupied"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('avenue', '/ˈævənuː/', 'noun', 'A broad road or street; a way of approaching a problem', '大街；途径；渠道', 3, 4200, '["toefl"]', '源自法语avenue，avenir（到达），a-（朝向）+ venir（来），原意为"通向某处的路"', '[{"en":"We explored every possible avenue to find a solution.","cn":"我们探索了所有可能的解决途径。"},{"en":"The tree-lined avenue leads to the university campus.","cn":"绿树成荫的大街通向大学校园。"}]', '["boulevard","pathway","route"]', '["dead end","block","obstacle"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('aware', '/əˈwer/', 'adjective', 'Having knowledge or perception of a situation or fact', '意识到的；知道的；觉察的', 3, 3100, '["toefl"]', '源自古英语gewaer（警觉的），ge-（加强）+ waer（小心的），意为"对周围事物有警觉的"', '[{"en":"People are becoming more aware of environmental issues.","cn":"人们越来越意识到环境问题。"},{"en":"She was fully aware of the consequences of her decision.","cn":"她完全清楚自己决定的后果。"}]', '["conscious","cognizant","mindful"]', '["unaware","ignorant","oblivious"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('balance', '/ˈbæləns/', 'noun', 'A state of equilibrium; equal distribution of weight or importance', '平衡；均衡；天平', 3, 3050, '["toefl"]', '源自拉丁语bilanx，bi-（两个）+ lanx（盘子），原意为"两个盘子等重的天平"', '[{"en":"Maintaining a balance between work and life is important.","cn":"保持工作与生活的平衡很重要。"},{"en":"The ecosystem requires a delicate balance to function properly.","cn":"生态系统需要微妙的平衡才能正常运作。"}]', '["equilibrium","stability","harmony"]', '["imbalance","instability","disorder"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('barrier', '/ˈbæriər/', 'noun', 'A fence or obstacle that prevents movement or access; an obstacle', '障碍；屏障；隔阂', 3, 3500, '["toefl"]', '源自古法语barre（横杆），意为"阻挡通行的障碍物"', '[{"en":"Language barriers can make communication difficult.","cn":"语言障碍会使沟通变得困难。"},{"en":"The Great Barrier Reef is the largest coral reef system in the world.","cn":"大堡礁是世界上最大的珊瑚礁系统。"}]', '["obstacle","hindrance","impediment"]', '["opening","passage","access"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('basis', '/ˈbeɪsɪs/', 'noun', 'The underlying support or foundation for something', '基础；根据；基本原则', 3, 3100, '["toefl"]', '源自希腊语basis（步伐、基础），bainein（走），原意为"站立的地方"，引申为"基础"', '[{"en":"The research was conducted on the basis of empirical evidence.","cn":"该研究是在实证证据的基础上进行的。"},{"en":"Students are selected on the basis of academic merit.","cn":"学生根据学业成绩选拔。"}]', '["foundation","groundwork","base"]', '["top","peak","superstructure"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('behalf', '/bɪˈhæf/', 'noun', 'In the interest of or as a representative of someone', '代表；为了…的利益', 4, 4000, '["toefl"]', '由be-（在…方面）+ half（一半）构成，原意为"在某一方"，即代表某人的利益', '[{"en":"The lawyer spoke on behalf of her client.","cn":"律师代表她的当事人发言。"},{"en":"We would like to thank you on behalf of the entire organization.","cn":"我们谨代表整个组织向您表示感谢。"}]', '["interest","representation","support"]', '["opposition","against","self"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('beneficial', '/ˌbenɪˈfɪʃl/', 'adjective', 'Resulting in good; favorable or advantageous', '有益的；有利的；有帮助的', 3, 3700, '["toefl"]', '源自拉丁语beneficium，bene（好）+ facere（做），原意为"做好事的行为"，引申为"产生好结果的"', '[{"en":"Regular exercise is beneficial to both physical and mental health.","cn":"定期锻炼对身心健康都有益。"},{"en":"The partnership proved beneficial to both companies.","cn":"这种合作关系对两家公司都有利。"}]', '["advantageous","helpful","favorable"]', '["harmful","detrimental","damaging"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bias', '/ˈbaɪəs/', 'noun', 'Prejudice in favor of or against something; a systematic deviation', '偏见；偏差；偏袒', 4, 3800, '["toefl"]', '源自古法语biais（斜的），原意为"倾斜的角度"，引申为"不公正的偏向"', '[{"en":"The study was designed to minimize bias in data collection.","cn":"该研究的设计旨在减少数据收集中的偏差。"},{"en":"Media bias can influence public opinion.","cn":"媒体偏见可以影响公众舆论。"}]', '["prejudice","partiality","inclination"]', '["fairness","impartiality","objectivity"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bind', '/baɪnd/', 'verb', 'To tie or fasten together; to impose a legal or moral obligation', '束缚；约束；结合', 4, 4300, '["toefl"]', '源自古英语bindan，日耳曼语根，意为"用绳索系在一起"，引申为"约束和结合"', '[{"en":"The contract binds both parties to specific obligations.","cn":"合同约束双方履行特定义务。"},{"en":"Shared values can bind a community together.","cn":"共同的价值观可以将社区凝聚在一起。"}]', '["tie","unite","oblige"]', '["unbind","free","release"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('blank', '/blæŋk/', 'adjective', 'Not written or printed on; empty; showing no expression', '空白的；空的；茫然的', 3, 3800, '["toefl"]', '源自古法语blanc（白色的），日耳曼语根，原意为"纯白的、未书写的"', '[{"en":"Leave the last line blank for the examiner to fill in.","cn":"最后一行留空让考官填写。"},{"en":"She stared at the blank screen, unsure what to write.","cn":"她盯着空白的屏幕，不知道该写什么。"}]', '["empty","bare","unmarked"]', '["filled","written","marked"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('blend', '/blend/', 'verb', 'To mix two or more substances together; to combine harmoniously', '混合；融合；协调', 3, 4100, '["toefl"]', '源自古英语blandan（混合），日耳曼语根，意为"将不同物质搅在一起"', '[{"en":"The architect blended modern and traditional styles in the design.","cn":"建筑师在设计中融合了现代和传统风格。"},{"en":"Blend the ingredients until smooth.","cn":"将原料搅拌至顺滑。"}]', '["mix","combine","merge"]', '["separate","divide","isolate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('boast', '/boʊst/', 'verb', 'To talk with excessive pride about one''s achievements; to possess something impressive', '自夸；拥有（值得自豪的事物）', 4, 4600, '["toefl"]', '源自中古英语bosten，起源不确定，可能源自古法语，意为"夸耀自己的成就"', '[{"en":"The city boasts several world-class museums.","cn":"这座城市拥有多个世界级博物馆。"},{"en":"He boasted about his academic achievements.","cn":"他自夸自己的学术成就。"}]', '["brag","flaunt","possess"]', '["humble","modest","lack"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('boom', '/buːm/', 'noun', 'A period of great prosperity or rapid economic growth', '繁荣；迅速增长；轰鸣', 3, 3900, '["toefl"]', '可能源自荷兰语bommen（发出嗡嗡声），拟声词，后引申为"经济快速增长"', '[{"en":"The post-war period saw an economic boom in many countries.","cn":"战后时期许多国家经历了经济繁荣。"},{"en":"The technology boom created many new jobs.","cn":"科技繁荣创造了许多新就业机会。"}]', '["prosperity","growth","surge"]', '["decline","recession","bust"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('boundary', '/ˈbaʊndəri/', 'noun', 'A line that marks the limits of an area; a dividing line', '边界；界限；分界线', 3, 3600, '["toefl"]', '由bound（界限，源自拉丁语bonus）+ -ary（名词后缀）构成，意为"划定范围的线"', '[{"en":"The river forms the boundary between the two countries.","cn":"这条河构成两国的边界。"},{"en":"Scientists are pushing the boundaries of human knowledge.","cn":"科学家正在推动人类知识的边界。"}]', '["border","limit","frontier"]', '["center","interior","core"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('breed', '/briːd/', 'verb', 'To produce offspring; to raise animals; to cause or give rise to', '繁殖；饲养；培育', 4, 4100, '["toefl"]', '源自古英语bredan（培育），日耳曼语根，与brood（幼雏）相关，意为"抚养后代"', '[{"en":"Certain plants breed more rapidly in warm climates.","cn":"某些植物在温暖气候中繁殖更快。"},{"en":"Poverty can breed crime and social unrest.","cn":"贫穷可能滋生犯罪和社会动荡。"}]', '["reproduce","cultivate","nurture"]', '["destroy","extinguish","suppress"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('brief', '/briːf/', 'adjective', 'Of short duration; concise and to the point', '简短的；简洁的；短暂的', 3, 3200, '["toefl"]', '源自拉丁语brevis（短的），意为"时间或篇幅短的"', '[{"en":"The professor gave a brief overview of the course.","cn":"教授对课程做了简短的概述。"},{"en":"Please keep your comments brief and to the point.","cn":"请保持评论简短且切中要点。"}]', '["short","concise","succinct"]', '["long","lengthy","extended"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bulk', '/bʌlk/', 'noun', 'The mass or magnitude of something; the greater part', '大量；体积；大部分', 3, 4000, '["toefl"]', '源自古诺尔斯语bulki（货物堆），意为"物体的体积或大部分"', '[{"en":"The bulk of the research was conducted in laboratories.","cn":"大部分研究是在实验室中进行的。"},{"en":"Buying in bulk can save money.","cn":"批量购买可以省钱。"}]', '["mass","majority","volume"]', '["minority","small amount","trifle"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('burst', '/bɜːrst/', 'verb', 'To break open or apart suddenly; to appear or come suddenly', '爆裂；突然发生；迸发', 3, 4200, '["toefl"]', '源自古英语berstan，日耳曼语根，意为"因内部压力而突然破裂"', '[{"en":"The dam burst after days of heavy rain.","cn":"连日暴雨后大坝溃堤了。"},{"en":"The market burst into activity when the announcement was made.","cn":"公告发布后市场突然活跃起来。"}]', '["explode","erupt","break"]', '["repair","seal","contain"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('bypass', '/ˈbaɪpæs/', 'verb', 'To go around or avoid something; to circumvent', '绕过；避开；旁路', 4, 4800, '["toefl"]', '由by-（旁边）+ pass（通过）构成，意为"从旁边通过以避开"', '[{"en":"The new highway bypasses the city center to reduce traffic.","cn":"新高速公路绕过市中心以减少交通拥堵。"},{"en":"Some companies try to bypass environmental regulations.","cn":"一些公司试图绕过环境法规。"}]', '["circumvent","avoid","sidestep"]', '["confront","face","encounter"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('calculate', '/ˈkælkjuleɪt/', 'verb', 'To determine a number or amount using mathematics; to plan', '计算；估计；打算', 3, 3300, '["toefl"]', '源自拉丁语calculus（小石子），古罗马人用小石子计算，calx（石灰石）+ -ulus（小词后缀）', '[{"en":"Scientists calculate the distance between planets using advanced formulas.","cn":"科学家使用高级公式计算行星之间的距离。"},{"en":"We need to calculate the total cost before proceeding.","cn":"我们需要在继续之前计算总成本。"}]', '["compute","estimate","determine"]', '["guess","ignore","approximate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('campaign', '/kæmˈpeɪn/', 'noun', 'An organized course of action to achieve a goal', '运动；活动；战役', 3, 3400, '["toefl"]', '源自法语campagne（田野、旷野），源自拉丁语campus（原野），原意为"在旷野中进行的军事行动"', '[{"en":"The government launched a campaign to promote healthy eating.","cn":"政府发起了一场促进健康饮食的运动。"},{"en":"The presidential campaign lasted over a year.","cn":"总统竞选活动持续了一年多。"}]', '["movement","initiative","crusade"]', '["inaction","apathy","indifference"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capable', '/ˈkeɪpəbl/', 'adjective', 'Having the ability or qualities necessary for doing something', '有能力的；能干的；有才能的', 3, 3200, '["toefl"]', '源自拉丁语capabilis，capere（拿取、容纳），意为"有能力容纳或处理的"', '[{"en":"She is a highly capable researcher with many publications.","cn":"她是一位非常有能力的研究人员，发表了很多论文。"},{"en":"The system is capable of processing thousands of requests per second.","cn":"该系统能够每秒处理数千个请求。"}]', '["competent","skilled","able"]', '["incapable","incompetent","unable"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capacity', '/kəˈpæsəti/', 'noun', 'The maximum amount that something can contain; the ability to do something', '容量；能力；才能', 3, 3300, '["toefl"]', '源自拉丁语capacitas，capere（拿取、容纳），意为"可以容纳的量"', '[{"en":"The stadium has a seating capacity of 50,000.","cn":"体育场可容纳5万人。"},{"en":"The brain has an enormous capacity for storing information.","cn":"大脑有巨大的信息存储能力。"}]', '["ability","capability","volume"]', '["inability","incapacity","emptiness"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('capture', '/ˈkæptʃər/', 'verb', 'To take into possession by force or skill; to record or depict', '捕获；捕捉；俘获', 3, 3400, '["toefl"]', '源自拉丁语captura，capere（抓取），原意为"用手抓住"', '[{"en":"The photographer captured stunning images of the sunset.","cn":"摄影师捕捉到了令人惊叹的日落画面。"},{"en":"The army captured the enemy fortress.","cn":"军队攻占了敌方堡垒。"}]', '["seize","catch","record"]', '["release","free","liberate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cast', '/kæst/', 'verb', 'To throw; to direct one''s gaze or vote; to shape by pouring into a mold', '投掷；投射；铸造', 4, 4000, '["toefl"]', '源自古诺尔斯语kasta（投掷），日耳曼语根，意为"用力扔出"', '[{"en":"The setting sun cast long shadows across the field.","cn":"落日在田野上投下了长长的影子。"},{"en":"The sculpture was cast in bronze.","cn":"这座雕塑是用青铜铸造的。"}]', '["throw","project","mold"]', '["catch","receive","absorb"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('catalog', '/ˈkætəlɔːɡ/', 'noun', 'A complete list of items; a systematic listing', '目录；目录册；系列', 4, 4300, '["toefl"]', '源自希腊语katalogos，kata-（完全）+ legein（说、收集），原意为"完整的列举"', '[{"en":"The library catalog lists all available books and journals.","cn":"图书馆目录列出了所有可用的书籍和期刊。"},{"en":"A catalog of artifacts was compiled for the exhibition.","cn":"为展览编制了一份文物目录。"}]', '["directory","index","listing"]', '["omission","exclusion","absence"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('category', '/ˈkætəɡɔːri/', 'noun', 'A class or division of things that share particular characteristics', '类别；种类；范畴', 3, 3300, '["toefl"]', '源自希腊语kategoria，kata-（向下）+ agora（集会），原意为"在公共集会上对事物的归类声明"', '[{"en":"The questions are divided into three categories: easy, medium, and hard.","cn":"问题分为三类：简单、中等和困难。"},{"en":"This species belongs to a different taxonomic category.","cn":"该物种属于不同的分类学类别。"}]', '["class","group","type"]', '["individual","single","unique"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('caution', '/ˈkɔːʃn/', 'noun', 'Care taken to avoid danger or mistakes; a warning', '谨慎；小心；警告', 3, 3800, '["toefl"]', '源自拉丁语cautio，cavere（小心、提防），原意为"采取防范措施的行为"', '[{"en":"Proceed with caution when handling hazardous chemicals.","cn":"处理危险化学品时要谨慎行事。"},{"en":"The teacher issued a caution about plagiarism.","cn":"老师发出了关于抄袭的警告。"}]', '["care","prudence","warning"]', '["recklessness","carelessness","haste"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cease', '/siːs/', 'verb', 'To bring or come to an end; to stop', '停止；终止；结束', 4, 4200, '["toefl"]', '源自拉丁语cessare（停止），cedere（走、退让）的频繁形式，意为"不再进行"', '[{"en":"The factory ceased production last year.","cn":"该工厂去年停止了生产。"},{"en":"The rain finally ceased after three days.","cn":"三天后雨终于停了。"}]', '["stop","halt","discontinue"]', '["continue","begin","commence"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('celebrate', '/ˈselɪbreɪt/', 'verb', 'To acknowledge a significant event with activities; to praise', '庆祝；赞美；颂扬', 3, 3200, '["toefl"]', '源自拉丁语celebrare（频繁前往、庆祝），celeber（热闹的、受欢迎的），意为"举行庆祝活动"', '[{"en":"The city celebrates its founding every year with a parade.","cn":"这座城市每年用游行庆祝建城纪念日。"},{"en":"Her work is celebrated for its originality and depth.","cn":"她的作品因原创性和深度而受到赞誉。"}]', '["commemorate","honor","praise"]', '["ignore","neglect","mourn"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('challenge', '/ˈtʃælɪndʒ/', 'noun', 'A task or situation that tests someone''s abilities; a call to compete', '挑战；难题；质疑', 3, 3100, '["toefl"]', '源自古法语chalenge（声称所有权），源自拉丁语calumnia（虚假指控），后引申为"对能力的考验"', '[{"en":"Climate change poses a significant challenge to global agriculture.","cn":"气候变化对全球农业构成重大挑战。"},{"en":"She embraced the challenge of learning a new language.","cn":"她接受了学习新语言的挑战。"}]', '["difficulty","obstacle","test"]', '["ease","simplicity","solution"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('channel', '/ˈtʃænl/', 'noun', 'A passage for water; a means of communication or expression', '渠道；频道；海峡', 3, 3300, '["toefl"]', '源自拉丁语canalis（管道），原意为"水流通的路径"，引申为"信息传播的途径"', '[{"en":"The river channel was widened to prevent flooding.","cn":"河道被拓宽以防止洪水。"},{"en":"Social media has become an important channel for marketing.","cn":"社交媒体已成为重要的营销渠道。"}]', '["medium","pathway","conduit"]', '["blockage","obstacle","barrier"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('characterize', '/ˈkærəktəraɪz/', 'verb', 'To describe the distinctive qualities of; to be typical of', '描述…的特征；以…为特征', 4, 3900, '["toefl"]', '源自希腊语charakter（印记、标记），charassein（雕刻），意为"刻画特征"', '[{"en":"The region is characterized by its diverse ecosystems.","cn":"该地区的特征是多样的生态系统。"},{"en":"Scientists characterized the new species based on its DNA.","cn":"科学家根据其DNA描述了新物种的特征。"}]', '["describe","depict","distinguish"]', '["misrepresent","distort","confuse"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('chart', '/tʃɑːrt/', 'noun', 'A sheet of information in graphical or tabular form; a map', '图表；海图；趋势图', 3, 3500, '["toefl"]', '源自拉丁语charta（纸莎草纸），源自希腊语khartes，意为"用于记录信息的纸张"', '[{"en":"The chart shows the population growth over the past century.","cn":"该图表显示了过去一个世纪的人口增长。"},{"en":"Navigators used star charts to plot their course.","cn":"航海者使用星图来规划航线。"}]', '["graph","diagram","map"]', '["text","narrative","description"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('chemical', '/ˈkemɪkl/', 'adjective', 'Relating to chemistry or the interactions of substances', '化学的；化学制品', 3, 3300, '["toefl"]', '源自中世纪拉丁语chimicus（炼金术的），源自阿拉伯语al-kimiya，意为"与物质变化有关的"', '[{"en":"Chemical reactions produce new substances from existing ones.","cn":"化学反应从现有物质中产生新物质。"},{"en":"The use of chemical fertilizers has increased crop yields.","cn":"化学肥料的使用提高了农作物产量。"}]', '["molecular","synthetic","organic"]', '["natural","physical","biological"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('chronicle', '/ˈkrɑːnɪkl/', 'noun', 'A factual written account of important events in order of time', '编年史；年代记；记录', 5, 5600, '["toefl"]', '源自希腊语chronika（按时间排列的事件），chronos（时间），意为"按时间顺序记录的历史"', '[{"en":"The chronicle records the history of the dynasty from its founding.","cn":"该编年史记录了王朝从建立以来的历史。"},{"en":"The book chronicles the lives of immigrant families.","cn":"这本书记录了移民家庭的生活。"}]', '["record","history","annals"]', '["fiction","prediction","forecast"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cite', '/saɪt/', 'verb', 'To quote as evidence; to refer to as an example', '引用；引证；举例', 4, 3600, '["toefl"]', '源自拉丁语citare（召唤、引用），ciere（推动），原意为"召唤证据来支持论点"', '[{"en":"The researcher cited several studies to support her argument.","cn":"研究人员引用了几项研究来支持她的论点。"},{"en":"He was cited for his contributions to the field.","cn":"他因对该领域的贡献而受到表彰。"}]', '["quote","reference","mention"]', '["ignore","omit","suppress"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('clarify', '/ˈklærəfaɪ/', 'verb', 'To make a statement or situation less confused and more understandable', '澄清；阐明；使清楚', 3, 3500, '["toefl"]', '源自拉丁语clarus（清楚的）+ facere（使），意为"使变得清楚"', '[{"en":"Could you clarify what you mean by that statement?","cn":"你能澄清一下那句话的意思吗？"},{"en":"The professor clarified the requirements for the assignment.","cn":"教授阐明了作业的要求。"}]', '["explain","elucidate","illuminate"]', '["confuse","obscure","complicate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('classify', '/ˈklæsɪfaɪ/', 'verb', 'To arrange things in groups according to shared characteristics', '分类；归类；把…分级', 4, 3900, '["toefl"]', '源自拉丁语classis（类别）+ facere（使），意为"按类别进行分组"', '[{"en":"Biologists classify organisms based on their genetic similarities.","cn":"生物学家根据遗传相似性对生物进行分类。"},{"en":"The documents were classified according to their sensitivity level.","cn":"文件按照敏感程度进行了分类。"}]', '["categorize","sort","organize"]', '["disorganize","mix","confuse"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('client', '/ˈklaɪənt/', 'noun', 'A person who uses the services of a professional; a customer', '客户；委托人；顾客', 3, 3200, '["toefl"]', '源自拉丁语cliens（追随者、门客），原指古罗马受庇护的平民，后引申为"接受专业服务的人"', '[{"en":"The law firm has clients from all over the world.","cn":"该律师事务所拥有来自世界各地的客户。"},{"en":"Understanding client needs is essential for business success.","cn":"了解客户需求对商业成功至关重要。"}]', '["customer","patron","consumer"]', '["provider","seller","vendor"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('climate', '/ˈklaɪmət/', 'noun', 'The weather conditions prevailing in an area over a long period', '气候；气候区；风气', 3, 3300, '["toefl"]', '源自希腊语klima（倾斜、地区），原指地球表面的倾斜角度决定的气候带，引申为"长期天气模式"', '[{"en":"Tropical climates support a wide variety of plant species.","cn":"热带气候支持多种多样的植物物种。"},{"en":"The political climate has changed significantly in recent years.","cn":"近年来政治风气发生了重大变化。"}]', '["weather","atmosphere","environment"]', '["single day","moment","instant"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('cluster', '/ˈklʌstər/', 'noun', 'A group of similar things positioned close together', '群；簇；丛；集群', 4, 4200, '["toefl"]', '源自古英语clyster（一串葡萄），日耳曼语根，意为"聚集在一起的一组"', '[{"en":"A cluster of stars forms a galaxy.","cn":"一群恒星构成一个星系。"},{"en":"The researchers identified a cluster of genes related to the disease.","cn":"研究人员发现了一组与该疾病相关的基因。"}]', '["group","bunch","collection"]', '["scatter","disperse","separate"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('coarse', '/kɔːrs/', 'adjective', 'Rough or loose in texture; not refined; crude', '粗糙的；粗俗的；粗粒的', 4, 5100, '["toefl"]', '源自中古英语cours（普通的、粗糙的），可能与course（过程）同源，指未经精细加工的', '[{"en":"The coarse sand made it difficult to walk barefoot.","cn":"粗糙的沙子使人难以赤脚行走。"},{"en":"Coarse language is not appropriate in academic writing.","cn":"粗俗的语言不适合学术写作。"}]', '["rough","crude","unrefined"]', '["fine","smooth","refined"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('coincide', '/ˌkoʊɪnˈsaɪd/', 'verb', 'To occur at the same time; to correspond exactly', '同时发生；一致；相吻合', 5, 5200, '["toefl"]', '源自拉丁语co-（一起）+ incidere（落入），in-（进入）+ cadere（落下），意为"恰好落入同一位置"', '[{"en":"The festival coincides with the start of the harvest season.","cn":"节日恰逢收获季节的开始。"},{"en":"Their opinions coincide on most major issues.","cn":"他们在大多数重大问题上意见一致。"}]', '["concur","overlap","correspond"]', '["differ","conflict","diverge"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('collapse', '/kəˈlæps/', 'verb', 'To fall down or give way suddenly; to fail completely', '倒塌；崩溃；瓦解', 3, 3500, '["toefl"]', '源自拉丁语collabi，com-（一起）+ labi（滑动、坠落），原意为"一起滑落崩塌"', '[{"en":"The bridge collapsed during the earthquake.","cn":"桥梁在地震中倒塌了。"},{"en":"The economy collapsed after years of mismanagement.","cn":"经济在多年管理不善后崩溃了。"}]', '["crumble","disintegrate","fail"]', '["build","construct","strengthen"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('colony', '/ˈkɑːləni/', 'noun', 'A territory under the control of another country; a community of organisms', '殖民地；群落', 4, 4500, '["toefl"]', '源自拉丁语colonia（农场、定居点），colere（耕种、居住），意为"在他处建立的定居点"', '[{"en":"Many colonies gained independence in the twentieth century.","cn":"许多殖民地在二十世纪获得了独立。"},{"en":"A colony of ants can contain millions of individuals.","cn":"一个蚁群可以包含数百万只蚂蚁。"}]', '["settlement","territory","community"]', '["homeland","metropolis","independence"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('column', '/ˈkɑːləm/', 'noun', 'A vertical structure used as a support; a vertical arrangement of data', '柱子；专栏；纵列', 3, 3700, '["toefl"]', '源自拉丁语columna（柱子），原意为"支撑建筑的垂直结构"，引申为"纵向排列"', '[{"en":"Greek architecture is famous for its ornate marble columns.","cn":"希腊建筑以其华丽的大理石柱而闻名。"},{"en":"The data was organized into columns in the spreadsheet.","cn":"数据在电子表格中按列组织。"}]', '["pillar","post","series"]', '["row","horizontal","base"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('combine', '/kəmˈbaɪn/', 'verb', 'To join or merge two or more things together', '结合；联合；合并', 3, 3100, '["toefl"]', '源自拉丁语combinare，com-（一起）+ binare（成对），原意为"两两配对结合"', '[{"en":"The researchers combined data from multiple sources.","cn":"研究人员合并了多个来源的数据。"},{"en":"The dish combines sweet and savory flavors.","cn":"这道菜结合了甜和咸的味道。"}]', '["merge","unite","integrate"]', '["separate","divide","split"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('command', '/kəˈmænd/', 'verb', 'To give an authoritative order; to have authority over', '命令；指挥；掌握', 3, 3200, '["toefl"]', '源自拉丁语commandare，com-（加强）+ mandare（委托），原意为"强力委托"，引申为"发号施令"', '[{"en":"The general commanded his troops to advance.","cn":"将军命令部队前进。"},{"en":"She commands great respect in the scientific community.","cn":"她在科学界受到极大的尊敬。"}]', '["order","direct","control"]', '["obey","submit","follow"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commence', '/kəˈmens/', 'verb', 'To begin or start something', '开始；着手；启动', 4, 4600, '["toefl"]', '源自古法语commencer，源自拉丁语com-（一起）+ initiare（开始），意为"正式开始"', '[{"en":"The ceremony will commence at ten o''clock.","cn":"典礼将于十点钟开始。"},{"en":"Construction on the new building commenced last month.","cn":"新大楼的建设于上个月开始。"}]', '["begin","initiate","start"]', '["end","conclude","finish"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('comment', '/ˈkɑːment/', 'noun', 'A verbal or written remark expressing an opinion or reaction', '评论；注释；意见', 3, 3050, '["toefl"]', '源自拉丁语commentum（发明、设计），comminisci（构想），意为"经过思考后提出的看法"', '[{"en":"The reviewer made several insightful comments about the paper.","cn":"审稿人对论文提出了几个有见地的评论。"},{"en":"She declined to comment on the ongoing investigation.","cn":"她拒绝对正在进行的调查发表评论。"}]', '["remark","observation","note"]', '["silence","ignorance","indifference"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commit', '/kəˈmɪt/', 'verb', 'To carry out or pledge to do something; to entrust', '承诺；犯（罪）；投入', 3, 3200, '["toefl"]', '源自拉丁语committere，com-（加强）+ mittere（发送），原意为"交托、委托"，引申为"全身心投入"', '[{"en":"The government committed to reducing carbon emissions by 2030.","cn":"政府承诺到2030年减少碳排放。"},{"en":"She committed herself to studying medicine.","cn":"她致力于学习医学。"}]', '["pledge","devote","undertake"]', '["withdraw","abandon","neglect"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('commodity', '/kəˈmɑːdəti/', 'noun', 'A raw material or primary agricultural product that can be bought and sold', '商品；日用品；有用的东西', 5, 4800, '["toefl"]', '源自拉丁语commoditas（便利），commodus（合适的），意为"方便交易的物品"', '[{"en":"Oil is one of the most traded commodities in the world.","cn":"石油是世界上交易量最大的商品之一。"},{"en":"Clean water has become a precious commodity in many regions.","cn":"清洁水在许多地区已成为珍贵的资源。"}]', '["goods","product","merchandise"]', '["service","labor","expertise"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('communicate', '/kəˈmjuːnɪkeɪt/', 'verb', 'To share or exchange information; to convey thoughts or feelings', '沟通；传达；交流', 3, 3100, '["toefl"]', '源自拉丁语communicare（分享），communis（共同的），意为"使信息共享"', '[{"en":"Effective leaders communicate their vision clearly to their teams.","cn":"有效的领导者清楚地向团队传达他们的愿景。"},{"en":"Dolphins communicate with each other using complex sounds.","cn":"海豚用复杂的声音相互交流。"}]', '["convey","express","share"]', '["conceal","withhold","suppress"]');
INSERT IGNORE INTO words (word, phonetic, part_of_speech, definition_en, definition_cn, difficulty, frequency_rank, tags, etymology, example_sentences, synonyms, antonyms) VALUES
('community', '/kəˈmjuːnəti/', 'noun', 'A group of people living in the same place or sharing common interests', '社区；社会；群落', 3, 3050, '["toefl"]', '源自拉丁语communitas（共同的），communis（共同的），意为"共同生活或分享的群体"', '[{"en":"The local community organized a fundraiser for the school.","cn":"当地社区为学校组织了一次筹款活动。"},{"en":"The scientific community has reached a consensus on this issue.","cn":"科学界已就这个问题达成共识。"}]', '["society","group","population"]', '["isolation","individual","solitude"]');
